var e=JSON.parse('[{"id":"basics-1","module":"basics","title":"基础知识","number":1,"type":"single","prompt":"以下描述操作系统的特征错误的是:","options":[{"key":"A","text":"共享性"},{"key":"B","text":"异步性"},{"key":"C","text":"并发性"},{"key":"D","text":"交互性"}],"answer":["D"],"explanation":"操作系统的基本特征通常概括为并发、共享、虚拟和异步。交互性是某些系统提供的使用体验。"},{"id":"basics-2","module":"basics","title":"基础知识","number":2,"type":"single","prompt":"下面描述七层体系结构阶级正确的是:","options":[{"key":"A","text":"物理层-数据链路层-网络层-传输层-会话层-表示层-应用层"},{"key":"B","text":"物理层-传输层-表示层-网络层-会话层-数据链路层-应用层"},{"key":"C","text":"物理层-传输层-表示层-数据链路层-会话层-网络层-应用层"},{"key":"D","text":"物理层-传输层-网络层-数据链路层-会话层-表示层-应用层"}],"answer":["A"],"explanation":"OSI 自底向上依次处理比特传输、链路成帧、网络寻址、端到端传输、会话管理、数据表示和应用服务。"},{"id":"basics-3","module":"basics","title":"基础知识","number":3,"type":"single","prompt":"在图形流中，两个 RGB信号被直接发送给_____控制单元，用于立体观察。","options":[{"key":"A","text":"HMD"},{"key":"B","text":"LCD"},{"key":"C","text":"CRT"},{"key":"D","text":"PC"}],"answer":["A"],"explanation":"HMD 是头戴式显示器，其控制单元接收分别对应左右眼的图像信号，利用双眼视差形成深度感。"},{"id":"basics-4","module":"basics","title":"基础知识","number":4,"type":"judge","prompt":"计算机信息系统安全保护条例是为了保护计算机信息系统的安全，特别指出计算机信息系统及其存储介质中的\\"有害数据\\"应当被禁止，虚拟现实从业人员也应把握好计算机信息服务中对于\\"有害数据\\"的定义。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"按题意判断。条例涉及危害系统安全的有害数据及其防治，题干的“应当被禁止”应结合具体行为和适用条款理解。"},{"id":"basics-5","module":"basics","title":"基础知识","number":5,"type":"single","prompt":"采用一个或多个大屏幕投影来实现大画面的立体视觉和听觉效果，使多个用户同时产生完全投入的感觉，该系统采用_____。","options":[{"key":"A","text":"座舱式虚拟现实系统"},{"key":"B","text":"洞穴式虚拟现实系统"},{"key":"C","text":"投影式虚拟现实系统"},{"key":"D","text":"头盔式虚拟现实系统"}],"answer":["C"],"explanation":"题干的识别点是通过一个或多个大屏幕进行多人立体投影。洞穴式系统还强调多面围合的投影空间。"},{"id":"basics-6","module":"basics","title":"基础知识","number":6,"type":"judge","prompt":"switch语句中case标签结束可以有跳转语句，也可以没有。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"按 C# 理解，非空分支到达末尾前必须退出或转移控制流。相邻的空 case 标签可以共用后续分支，因此标签本身可以没有跳转语句。"},{"id":"basics-7","module":"basics","title":"基础知识","number":7,"type":"single","prompt":"下列哪个属于项目环境？","options":[{"key":"A","text":"社会环境"},{"key":"B","text":"政治环境"},{"key":"C","text":"以上全部"},{"key":"D","text":"自然环境"}],"answer":["C"],"explanation":"项目环境涵盖多种外部条件。社会环境影响利益相关方，政治环境影响政策与审批，自然环境影响实施条件。"},{"id":"basics-8","module":"basics","title":"基础知识","number":8,"type":"judge","prompt":"机械跟踪器由一个串行或并行的运动结构组成，该运动结构由多个带有传感器的关节连接在一起的连杆构成。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"机械跟踪器通过关节传感器测量连杆相对运动，再结合已知的机械结构计算末端的位置和姿态。"},{"id":"basics-9","module":"basics","title":"基础知识","number":9,"type":"judge","prompt":"双极性码指的是用正负电平来分别代表逻辑\\"1\\"和逻辑\\"0\\"。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"按教材的双极性表示口径，两个逻辑值分别用相反极性的电平表示。在其他通信教材中，“双极性”也可能专指 1 交替用正负脉冲表示的 AMI，需结合定义。"},{"id":"basics-10","module":"basics","title":"基础知识","number":10,"type":"judge","prompt":"iFeel Mouse就是一种触觉鼠标，它的外观和重量都与普通的鼠标相似，不同的是附加的电子激励器可以引起鼠标外壳的震动。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"iFeel Mouse 在常规鼠标功能上增加振动执行器。软件可触发外壳振动，向手部传递触觉提示。"},{"id":"basics-11","module":"basics","title":"基础知识","number":11,"type":"single","prompt":"以下哪个选项可以决定一个系统是否属于虚拟现实系统的关键特征？","options":[{"key":"A","text":"交互性"},{"key":"B","text":"沉浸性"},{"key":"C","text":"交互性和想象性"},{"key":"D","text":"沉浸性和交互性"}],"answer":["D"],"explanation":"沉浸性让用户感到身处场景中，交互性让场景随用户输入作出响应。两者结合可区分单纯观看与可交互的虚拟体验。"},{"id":"basics-12","module":"basics","title":"基础知识","number":12,"type":"judge","prompt":"操作系统不可以通过资源管理，提高计算机系统的效率。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"操作系统可利用处理器调度、内存分配及缓冲等机制提高资源利用率，减少设备闲置或程序等待。"},{"id":"basics-13","module":"basics","title":"基础知识","number":13,"type":"judge","prompt":"头盔显示器的图像投影唯一的负面影响是显示器像素之间的距离被缩小了。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"光学放大可能让像素间隙更明显，还可能产生畸变和模糊。像素的物理间距由面板决定。"},{"id":"basics-14","module":"basics","title":"基础知识","number":14,"type":"judge","prompt":"如果跟踪器的遇到时间滞后的问题，在仿真中需要尽量扩大延迟。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"延迟越大，场景对头部或身体运动的响应越晚，容易出现视觉与身体感觉不一致。仿真应尽量降低延迟。"},{"id":"basics-15","module":"basics","title":"基础知识","number":15,"type":"judge","prompt":"增强虚拟现实系统主要特点是将真实世界和虚拟世界隔离开来。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"增强现实将虚拟内容叠加到现实环境中，并尽量维持空间配准。用户同时感知真实环境和数字信息。"},{"id":"basics-16","module":"basics","title":"基础知识","number":16,"type":"judge","prompt":"会话层允许不同计算机上的用户建立会话关系。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"会话层负责建立、管理和结束会话，也可提供对话控制或同步。比特传输和路由由其他层处理。"},{"id":"basics-17","module":"basics","title":"基础知识","number":17,"type":"single","prompt":"网络管理指的是？","options":[{"key":"A","text":"网络利用和计费管理"},{"key":"B","text":"网络性能管理、网络设备和应用配置管理"},{"key":"C","text":"以上全部"},{"key":"D","text":"网络设备和应用故障管理以及安全管理"}],"answer":["C"],"explanation":"这些选项覆盖网络管理常见的五类职责，即故障、配置、计费、性能和安全管理。"},{"id":"basics-18","module":"basics","title":"基础知识","number":18,"type":"single","prompt":"典型的SLP不包括以下哪个项目？","options":[{"key":"A","text":"客户带宽极限"},{"key":"B","text":"能同时服务的客户数目"},{"key":"C","text":"运用经济学"},{"key":"D","text":"运用统计学"}],"answer":["C"],"explanation":"按题目将 SLP 理解为服务等级配置，带宽和并发客户数属于可约定的服务指标，统计用于度量和分析，经济学属于分析视角。题干未展开缩写，答案依赖教材语境。"},{"id":"basics-19","module":"basics","title":"基础知识","number":19,"type":"judge","prompt":"资源约束是指每一个项目都需要具备各种资源作为实施的保证，而资源是有限的。所以资源成本是项目成功实施的一个约束条件。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"人员、资金、设备和材料均有限。项目须在预算和资源供给限制内安排范围、进度和工作量。"},{"id":"basics-20","module":"basics","title":"基础知识","number":20,"type":"judge","prompt":"触觉反馈设备不包括充气式触觉反馈设备。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"充气式设备利用气囊或气室改变对皮肤的压力，可模拟接触、挤压等感觉。"},{"id":"basics-21","module":"basics","title":"基础知识","number":21,"type":"judge","prompt":"硬件是所有软件运行的物质基础；软件能充分发挥硬件潜能和扩充硬件功能，完成各种系统及应用任务，两者互相促进、相辅相成、缺一不可。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"硬件提供运算、存储和输入输出能力，软件调用并协调这些能力，使计算机完成系统和应用任务。"},{"id":"basics-22","module":"basics","title":"基础知识","number":22,"type":"single","prompt":"操作者通过视觉、听觉感知环境，通过自然动作操作环境，而不是通过显示器、键盘、鼠标和计算机交互，这改变了以下人机交互的哪种特征？","options":[{"key":"A","text":"内容"},{"key":"B","text":"效果"},{"key":"C","text":"外观"},{"key":"D","text":"形式"}],"answer":["D"],"explanation":"题干改变的是输入和反馈的方式。自然动作、视觉和听觉替代部分传统输入输出手段，因此对应交互形式。"},{"id":"basics-23","module":"basics","title":"基础知识","number":23,"type":"judge","prompt":"声音跟踪技术不属于高性能计算处理技术。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"声音跟踪通常归入感知和交互技术，用于定位声源或调整空间音频。实现时可以借助高性能计算。"},{"id":"basics-24","module":"basics","title":"基础知识","number":24,"type":"single","prompt":"以下哪个涉及到VR内容潜在的法律问题？","options":[{"key":"A","text":"A和B"},{"key":"B","text":"产品质量责任问题"},{"key":"C","text":"VR内容色情化问题"},{"key":"D","text":"用户隐私数据收集问题"}],"answer":["C"],"explanation":"色情化直接涉及 VR 内容本身，质量责任和数据采集分别偏向产品及数据处理。A 引用了自身，属于选项编排异常。"},{"id":"basics-25","module":"basics","title":"基础知识","number":25,"type":"judge","prompt":"所有内置的数据类型都是值类型，所有用户定义的数据类型都是引用类型。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"C# 内置的 string 和 object 是引用类型。用户自行声明的 struct 和 enum 是值类型。"},{"id":"basics-26","module":"basics","title":"基础知识","number":26,"type":"judge","prompt":"foreach语句总是从索引1遍历到索引Length。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"foreach 按集合的枚举顺序取出元素。对普通数组会从第一个元素开始，并且通常无须访问索引。"},{"id":"basics-27","module":"basics","title":"基础知识","number":27,"type":"judge","prompt":"VR设备潜在的法律问题分别有产品质量责任问题和用户隐私数据。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"VR 设备可能因缺陷或使用安全产生质量责任，也可能通过位置、动作和眼动采集涉及隐私。"},{"id":"basics-28","module":"basics","title":"基础知识","number":28,"type":"judge","prompt":"人类触觉系统的输入是由感知循环提供的，对环境的输出(对触觉反馈接口而言)是以传感器到发动机控制循环为中介的。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"触觉感知依赖皮肤及本体感觉等反馈，使用者又通过运动控制作出动作。这里的“发动机”宜理解为“运动控制”。"},{"id":"basics-29","module":"basics","title":"基础知识","number":29,"type":"judge","prompt":"数组的长度不能是变量。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"创建数组时可用变量指定长度，例如 new int[n]。创建完成后，该数组实例的长度固定。"},{"id":"basics-30","module":"basics","title":"基础知识","number":30,"type":"single","prompt":"曾为\\"虚拟现实技术\\"取名为\\"灵境\\"是哪位著名科学家？","options":[{"key":"A","text":"赵沁平"},{"key":"B","text":"邓稼先"},{"key":"C","text":"钱学森"},{"key":"D","text":"李伯虎"}],"answer":["C"],"explanation":"钱学森用“灵境”指称虚拟现实，强调使用者置身于计算机生成环境中的体验。"},{"id":"basics-31","module":"basics","title":"基础知识","number":31,"type":"single","prompt":"操作系统的功能不具备哪个功能:","options":[{"key":"A","text":"性能管理"},{"key":"B","text":"处理器管理"},{"key":"C","text":"存储管理"},{"key":"D","text":"网络与通信管理"}],"answer":["A"],"explanation":"按基础教材分类，处理器管理、存储管理和网络通信可列入操作系统职能。性能优化通常贯穿各项管理功能。"},{"id":"basics-32","module":"basics","title":"基础知识","number":32,"type":"judge","prompt":"枚举型是值类型，它是一组称为枚举数列表的命名常量组成的独特类型。92枚举型的默认基础类型为int，第一个枚举数的值必须为0，后面每个枚举型的值依次递增1。(× )","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"本题按首句判为正确。题干混入另一道判断题的文字，若将两段合并判断，则应选 B。默认底层类型确为 int，但首项可显式赋予非零值，后续未赋值成员按前项加一。"},{"id":"basics-33","module":"basics","title":"基础知识","number":33,"type":"judge","prompt":"for循环是先判定表达式,后执行循环体语句。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"for 在初始化后先检查条件，条件为真才进入循环体。每轮结束后执行迭代表达式，再检查条件。"},{"id":"basics-34","module":"basics","title":"基础知识","number":34,"type":"single","prompt":"下列哪个不属于战略管理的过程？","options":[{"key":"A","text":"战略制定"},{"key":"B","text":"战略实施"},{"key":"C","text":"战略测试"},{"key":"D","text":"战略评价"}],"answer":["C"],"explanation":"战略管理通常包括战略制定、实施与评价。测试可以是验证手段，通常没有单列为基本阶段。"},{"id":"basics-35","module":"basics","title":"基础知识","number":35,"type":"single","prompt":"应用系统用以描述仿真的具体内容，包括仿真的动态逻辑、结构及仿真对象之间和仿真对象与用户之间的____关系？","options":[{"key":"A","text":"合作"},{"key":"B","text":"交互"},{"key":"C","text":"交叉"},{"key":"D","text":"层级"}],"answer":["B"],"explanation":"应用系统定义仿真对象的行为，以及对象之间、对象和用户之间如何响应彼此的操作，这些都属于交互关系。"},{"id":"basics-36","module":"basics","title":"基础知识","number":36,"type":"single","prompt":"以下哪项不属于虚拟现实的核心技术？","options":[{"key":"A","text":"计算机处理技术"},{"key":"B","text":"系统集成技术"},{"key":"C","text":"人机交互技术"},{"key":"D","text":"环境建模技术"}],"answer":["A"],"explanation":"按本题教材口径，环境建模、人机交互和系统集成作为 VR 专项核心技术列举。计算机处理为这些环节提供基础能力。"},{"id":"basics-37","module":"basics","title":"基础知识","number":37,"type":"judge","prompt":"在C#中，常量的值可以在代码中被修改。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"const 声明的常量须在声明时用常量表达式初始化，代码不能在之后重新赋值。"},{"id":"basics-38","module":"basics","title":"基础知识","number":38,"type":"judge","prompt":"为了增进虚拟现实空间的真实性，影像式虚拟现实的制作往往会利用摄影的方式择取真实世界的影像，这类衍生作品创作的自由度亦是知识产权保护所需讨论的边界。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"摄影素材可能涉及原始作品及拍摄成果的权利。把现实影像纳入 VR 时，需要区分素材使用与新增表达。"},{"id":"basics-39","module":"basics","title":"基础知识","number":39,"type":"single","prompt":"项目的主要特点下列表达错误的是？","options":[{"key":"A","text":"逐步完善"},{"key":"B","text":"资源丰富"},{"key":"C","text":"临时性"},{"key":"D","text":"独特的产品、服务或成果"}],"answer":["B"],"explanation":"项目具备临时性和独特成果，细节会逐步明确。资源供给一般受到限制，资源丰富并非项目定义特征。"},{"id":"basics-40","module":"basics","title":"基础知识","number":40,"type":"judge","prompt":"单极性码表示信号的电压或电流是单极性的，即逻辑\\"0\\"用高电平或正向电流表示，而逻辑\\"1\\"用零电平表示。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"教材通常以零电平表示 0、正电平表示 1。单极性描述的是信号使用同一极性，具体映射仍可由编码约定。"},{"id":"basics-41","module":"basics","title":"基础知识","number":41,"type":"judge","prompt":"若子网掩码为255.255.255.192，即二进制1111111 111111 1111111 11000000，则表示IP的前24位为网络数，接着2位为子网数，后6位为结点 数了。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"在原网络为 /24 的前提下，/26 借两位作为子网位，留下六位主机位。正确二进制掩码为 11111111.11111111.11111111.11000000。"},{"id":"basics-42","module":"basics","title":"基础知识","number":42,"type":"judge","prompt":"HTTP协议是Web服务器与客户浏览器之间的信息传输协议，用于从www服务器传输超文本到本地浏览器，属于TCP/IP模型传输层协议。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"HTTP 规定客户端和服务器之间的请求、响应格式，属于应用层。传输服务由 TCP 或 QUIC 等协议提供。"},{"id":"basics-43","module":"basics","title":"基础知识","number":43,"type":"judge","prompt":"图形生成是虚拟现实的重要瓶颈，虚拟现实最重要的特性是人可以在随意变化的交互控制下感受到场景的静态特性。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"VR 交互要求场景随动作实时更新，用户会感知动态变化。图形实时生成的难点在于及时渲染这些变化。"},{"id":"basics-44","module":"basics","title":"基础知识","number":44,"type":"judge","prompt":"虚拟现实隐私权的客体有个人信息、私人正常生活不受骚扰、个人自主决定不受妨碍和私人空间。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"题干列的是讨论 VR 隐私时的常见保护利益，包括个人信息、生活安宁、自主决定和私人空间。具体法律认定取决于行为和适用规则。"},{"id":"basics-45","module":"basics","title":"基础知识","number":45,"type":"single","prompt":"以下哪个属于中央处理部件？","options":[{"key":"A","text":"存储器"},{"key":"B","text":"控制器"},{"key":"C","text":"运算器"},{"key":"D","text":"计算器"}],"answer":["B","C"],"explanation":"控制器负责指令译码和发出控制信号，运算器负责算术与逻辑运算。两者都属于 CPU，本题有两个正确选项。"},{"id":"basics-46","module":"basics","title":"基础知识","number":46,"type":"single","prompt":"分布式虚拟现实系统主要特征不包括______。","options":[{"key":"A","text":"共享的虚拟工作空间"},{"key":"B","text":"支持实时交互，共享时钟"},{"key":"C","text":"多用户相互屏蔽"},{"key":"D","text":"伪实体的行为真实感"}],"answer":["C"],"explanation":"分布式 VR 依靠多个用户共享空间及状态并开展实时互动。同步机制和仿真实体的行为真实性都与该目标相关。"},{"id":"basics-47","module":"basics","title":"基础知识","number":47,"type":"judge","prompt":"项目管理的对象是项目，即一系列的长期任务。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"项目为实现特定成果而开展，有起点和终点。项目可长可短，临时性指有期限。"},{"id":"basics-48","module":"basics","title":"基础知识","number":48,"type":"judge","prompt":"头盔显示器主要由显示器和光学透镜组成，辅以3个自由度的空间跟踪定位器可进行虚拟输出，同时观察者可以做空间上的自由移动，如行走、旋转等。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"三自由度跟踪通常测量三个旋转方向。行走等空间平移还需要跟踪三个位置方向，合计六自由度。"},{"id":"basics-49","module":"basics","title":"基础知识","number":49,"type":"judge","prompt":"在仿真过程中，观察者的焦点是无意识地动态变化的，如果能跟踪到眼睛的动态变化，就可以探测到焦点的变化。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"眼动跟踪可根据视线方向估计注视点随时间的变化。若需判断准确的三维注视深度，还要结合双眼或场景信息。"},{"id":"basics-50","module":"basics","title":"基础知识","number":50,"type":"judge","prompt":"如果需要修改数组元素就必须使用for语句。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"可直接通过下标修改数组元素，也可以在 while 中按索引修改。普通 foreach 的迭代变量本身不能直接用于回写数组槽位。"},{"id":"basics-51","module":"basics","title":"基础知识","number":51,"type":"single","prompt":"根据需要获得被收集者同意，公示收集用的规则,以及明示收集、使用信息的目的、方式和范围，贯彻\\"合法、正当、必要\\"的原则，属于虚拟现实哪条法律法规？","options":[{"key":"A","text":"专利法"},{"key":"B","text":"网络安全法"},{"key":"C","text":"密码法"},{"key":"D","text":"互联网信息服务管理办法"}],"answer":["B"],"explanation":"题干描述的是网络安全法关于个人信息收集与使用的规则，识别线索包括公开规则、明示目的方式和范围以及合法、正当、必要。"},{"id":"basics-52","module":"basics","title":"基础知识","number":52,"type":"judge","prompt":"foreach语句能使你不用索引就可以遍历整个数组。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"foreach 通过枚举机制依次取得元素，循环代码可以直接读取元素，无需手工维护下标。"},{"id":"basics-53","module":"basics","title":"基础知识","number":53,"type":"single","prompt":"以下哪项不属于操作系统的类型？","options":[{"key":"A","text":"实时操作系统"},{"key":"B","text":"分时操作系统"},{"key":"C","text":"批处理操作系统"},{"key":"D","text":"网络管理操作系统"}],"answer":["D"],"explanation":"实时、分时、批处理是常见操作系统分类。教材也会讨论网络操作系统，题中的“网络管理操作系统”属于不规范表述。"},{"id":"basics-54","module":"basics","title":"基础知识","number":54,"type":"judge","prompt":"虚拟现实隐私权概念与传统隐私权、网络空间隐私权相比，其权利属性均是自然人不与公权力冲突的生活安宁与私人信息秘密依法不受他人打扰、妨碍的权利。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"按题库采用的概念归纳，三种情境均涉及生活安宁与私密利益。公权力处理信息时同样需要法律依据，题干的限定不宜作绝对解释。"},{"id":"basics-55","module":"basics","title":"基础知识","number":55,"type":"single","prompt":"以下哪个不属于沉浸式立体投影系统？","options":[{"key":"A","text":"多通道环幕立体投影系统"},{"key":"B","text":"CAVE 沉浸式虚拟现实系统"},{"key":"C","text":"几何构造系统"},{"key":"D","text":"单通道立体投影系统"}],"answer":["C"],"explanation":"几何构造系统负责建立场景模型。环幕、CAVE 和单通道投影均属于显示实现方式。"},{"id":"basics-56","module":"basics","title":"基础知识","number":56,"type":"judge","prompt":"螺旋模型是一个演化软件过程模型，将原型实现的迭代特征与线性顺序(瀑布)模型中控制的和系统化的方面结合起来，使得软件的增量版本的快速开发成为可能。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"螺旋模型结合迭代原型和阶段管理，每轮评估风险、开发并验证阶段成果，再据此进入下一轮。"},{"id":"basics-57","module":"basics","title":"基础知识","number":57,"type":"judge","prompt":"项目管理的职能与其他管理的职能是完全一致的，即是对组织的资源进行计划、组织、指挥、协调、控制。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"项目管理也包含计划、组织和控制，但要围绕独特成果及临时组织协调进度、范围、资源和风险。“完全一致”的说法过强。"},{"id":"basics-58","module":"basics","title":"基础知识","number":58,"type":"judge","prompt":"集成技术包括信息的同步技术、模型的标定技术、数据转换技术、识别和合成技术等。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"时间同步、坐标标定、数据格式转换以及识别和融合可让不同设备、模型和信息流协同运行。"},{"id":"basics-59","module":"basics","title":"基础知识","number":59,"type":"judge","prompt":"虚拟现实系统具有3个重要特征，它们分别是沉浸感、交互性和创造力。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"按 VR 的 3I 教材口径，三个特征是沉浸、交互和想象。题中“创造力”可理解为想象性。"},{"id":"basics-60","module":"basics","title":"基础知识","number":60,"type":"judge","prompt":"一个典型的虚拟现实系统的组成主要由头盔显示设备、传感设备和力反馈装置。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"按典型头戴式系统的外设构成判断。头显输出视觉，传感设备输入动作，力反馈装置模拟受力，完整系统还需计算和软件。"},{"id":"basics-61","module":"basics","title":"基础知识","number":61,"type":"judge","prompt":"在两个结点间的线路可以是采用电话线、电缆、光纤等有线信道，但不可以是无线电信道。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"无线电也可承载两个节点之间的数据。电话线、电缆和光纤是有线介质，无线电属于无线介质。"},{"id":"basics-62","module":"basics","title":"基础知识","number":62,"type":"judge","prompt":"传输层的主要功能是从端到端经网络透明地传送报文，完成端到端通信链路的建立、维护和管理。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"传输层提供端到端的数据传输。以 TCP 为例，可建立和管理连接，UDP 同属传输层并采用无连接方式。"},{"id":"basics-63","module":"basics","title":"基础知识","number":63,"type":"judge","prompt":"力反馈操纵杆的特点是自由度比较大，外观也比较小巧，能产生较大的力，有较小的机械带宽。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"自由度、力输出和带宽依设备而变。机械带宽越大，设备越能快速再现变化的力，将较小带宽列为通用特征不妥。"},{"id":"basics-64","module":"basics","title":"基础知识","number":64,"type":"single","prompt":"一个完整的数据通信系统，一般由以下几个部分组成？","options":[{"key":"A","text":"数据终端设备，通信控制器，信号变换器"},{"key":"B","text":"数据终端设备，光学跟踪器，通信信道，信号变换器"},{"key":"C","text":"数据终端设备，通信控制器，通信信道"},{"key":"D","text":"数据终端设备，通信控制器，通信信道，信号变换器"}],"answer":["D"],"explanation":"终端产生和接收数据，控制器处理通信控制，信号变换器适配信道，通信信道承担实际传输。"},{"id":"basics-65","module":"basics","title":"基础知识","number":65,"type":"judge","prompt":"分布式虚拟现实系统的设计和实现应该考虑网络宽带的发展和现状，当用户增加时，网络延迟就会出现，带宽的需求也随之增加。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"用户越多，通常要同步的动作和状态越多，带宽压力增大。链路或服务器接近容量时，排队会使延迟上升。"},{"id":"basics-66","module":"basics","title":"基础知识","number":66,"type":"judge","prompt":"for循环体语句中,可以包含多条语句,但要用花括号括起来","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"C# 的循环体语法接收一条嵌入语句。用花括号组成代码块即可把多条语句一同作为循环体。"},{"id":"basics-67","module":"basics","title":"基础知识","number":67,"type":"judge","prompt":"在C#中，int类型变量的位数是16位。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"C# 的 int 对应 System.Int32，宽度为 32 位。16 位有符号整数是 short。"},{"id":"basics-68","module":"basics","title":"基础知识","number":68,"type":"judge","prompt":"电磁跟踪器是一种非接触式的位置测量设备，它使用由一个固定发射器产生的电磁场，来确定移动接收单元的实时位置。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"固定发射器生成电磁场，移动接收单元测量场信号变化，据此估算其相对位置，系统也可据此估计姿态。"},{"id":"basics-69","module":"basics","title":"基础知识","number":69,"type":"judge","prompt":"如果拥有一个网络地址(如一个C类地址210.34.168.X)，则只能用它来唯一标识一个物理网络，而这个网络允许最多有100个结点。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"传统 C 类 /24 有八个主机位，常规子网保留网络和广播地址后可用主机地址数为 254。该地址块也可进一步划分子网。"},{"id":"basics-70","module":"basics","title":"基础知识","number":70,"type":"single","prompt":"图形显示设备正向_____方向发展。","options":[{"key":"A","text":"低分辨率、延迟大、质量轻、行动限制小、跟踪精度高"},{"key":"B","text":"高分辨率、延迟小、质量轻、行动限制小、跟踪精度高"},{"key":"C","text":"低分辨率、延迟小、质量重、行动限制小、跟踪精度低"},{"key":"D","text":"高分辨率、延迟小、质量重、行动限制小、跟踪精度低"}],"answer":["B"],"explanation":"高分辨率提高细节，低延迟改善动作响应，轻量化及较少限制改善佩戴体验，精确跟踪提升空间一致性。"},{"id":"basics-71","module":"basics","title":"基础知识","number":71,"type":"judge","prompt":"隐私权向虚拟空间扩展，虚拟的不属于个人隐私的范围。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"虚拟空间中的账号、私密互动及可关联到个人的行为数据也可能涉及隐私。"},{"id":"basics-72","module":"basics","title":"基础知识","number":72,"type":"judge","prompt":"日常运作和项目两者之间的区分主要在于日常运作是持续不断和重复进行的，而项目是临时性的、独特的。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"日常运作重在持续和重复交付。项目围绕某个独特目标组织工作，并在目标达成或终止时结束。"},{"id":"basics-73","module":"basics","title":"基础知识","number":73,"type":"single","prompt":"下列描述错误的是:","options":[{"key":"A","text":"虚拟现实的交互能力依赖于立体显示和传感器技术的发展。现有的虚拟现实还远远不能满足系统的需要。"},{"key":"B","text":"虚拟现实设备的跟踪精度和跟踪范围也有待提高，因此有必要开发新的三维显示技术。"},{"key":"C","text":"由于虚拟现实系统中包括大量的感知信息和模型，因此模型构建技术起着至关重要的作用。"},{"key":"D","text":"虚拟环境的建立是虚拟现实技术的核心内容，环境建模的目的是获取实际三维环境的三维数据，并根据应用的需要，利用获取的三维数据建立相应的虚拟环境模型。"}],"answer":["B"],"explanation":"跟踪精度和范围取决于传感、定位和算法。改进三维显示可改善视觉呈现，不能直接解决跟踪范围和精度。"},{"id":"basics-74","module":"basics","title":"基础知识","number":74,"type":"judge","prompt":"虚拟现实系统中的人机交互是一种自然的交互，使用者不仅可以利用计算机键盘、鼠标进行交互，而且能够通过专用头盔、数据手套等传感设备进行交互。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"VR 可以兼容键鼠，也可以使用头显传感器、数据手套等采集自然动作。交互方式取决于系统设计。"},{"id":"basics-75","module":"basics","title":"基础知识","number":75,"type":"judge","prompt":"辅助存储器又称外存储器，外存储器主要由磁表面存储器组成。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"外存包括磁盘、磁带、光盘和固态存储。“主要由磁表面存储器组成”只适用于特定历史教材背景，难以概括外存类别。"},{"id":"basics-76","module":"basics","title":"基础知识","number":76,"type":"single","prompt":"关于计算机网络的安全问题，以下哪个不需要考虑？","options":[{"key":"A","text":"金融安全"},{"key":"B","text":"控制安全"},{"key":"C","text":"物理安全"},{"key":"D","text":"服务安全"}],"answer":["A"],"explanation":"物理安全、控制安全和服务安全是题目列举的网络安全维度。金融安全是具体行业的应用目标。"},{"id":"basics-77","module":"basics","title":"基础知识","number":77,"type":"judge","prompt":"球面投影显示系统最大的特点是视野非常广阔，能覆盖观察者的所有视野，从而能让观察者感觉完全置身于场景中，给人身临其境的沉浸感。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"球面投影可扩大视野覆盖角，减少显示边界，使用户更像置身场景。实际覆盖范围由球幕和投影设计决定。"},{"id":"basics-78","module":"basics","title":"基础知识","number":78,"type":"judge","prompt":"C#程序的执行是从第一个方法开始，到Main方法结束。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"通常由 Main 作为 C# 程序入口。顶级语句会由编译器生成入口，源码中方法的排列顺序不决定执行顺序。"},{"id":"basics-79","module":"basics","title":"基础知识","number":79,"type":"single","prompt":"以下哪项技术通过头盔显示器、数据手套、数据衣进行交互？","options":[{"key":"A","text":"基本模型构建技术"},{"key":"B","text":"空间跟踪技术"},{"key":"C","text":"声音跟踪技术"},{"key":"D","text":"视觉跟踪技术"}],"answer":["B"],"explanation":"空间跟踪测量头、手和身体的位置或姿态，供系统更新视角、手部模型或全身动作。"},{"id":"basics-80","module":"basics","title":"基础知识","number":80,"type":"judge","prompt":"不同的命名空间中不能有同名的方法。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"不同命名空间可包含同名类型，这些类型也可有同名方法。编译器根据命名空间、所属类型和签名解析调用。"},{"id":"basics-81","module":"basics","title":"基础知识","number":81,"type":"judge","prompt":"信息系统是以信息的集成为目标，功能的集成为结构，平台的集成为基础，人的集成为保证。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"按题库的集成视角，平台承载运行，功能协同支持业务，信息集成实现共享，人员参与保证系统落地。"},{"id":"basics-82","module":"basics","title":"基础知识","number":82,"type":"single","prompt":"以下哪种装置能产生沉浸感，并且能测定视线方向和手指动作？","options":[{"key":"A","text":"几何构造系统"},{"key":"B","text":"实景仿真器"},{"key":"C","text":"应用系统"},{"key":"D","text":"效果产生器"}],"answer":["D"],"explanation":"按题库的系统结构，效果产生器承担沉浸式呈现，可配合传感设备获取视线和手势。具体测量由眼动或动作传感器完成。"},{"id":"basics-83","module":"basics","title":"基础知识","number":83,"type":"judge","prompt":"在C#中，%运算符的两边都必须是整型的。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"C# 的 % 支持整数，也支持浮点和 decimal 操作数。例如 5.5 % 2.0 的结果为 1.5。"},{"id":"basics-84","module":"basics","title":"基础知识","number":84,"type":"single","prompt":"下列哪个不属于控制器组成部分？","options":[{"key":"A","text":"高速缓冲存储器"},{"key":"B","text":"操作控制信号形成部件"},{"key":"C","text":"程序计数器"},{"key":"D","text":"指令译码器"}],"answer":["A"],"explanation":"程序计数器、指令译码器和控制信号形成部件参与指令控制。高速缓冲存储器用于缩小处理器与主存的访问速度差。"},{"id":"basics-85","module":"basics","title":"基础知识","number":85,"type":"judge","prompt":"流量管理主要涉及网络带宽控制和分配、通信延迟的降低和拥塞控制的最大化。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"流量管理通过整形、调度、分配带宽等手段降低延迟并抑制拥塞。“拥塞控制的最大化”并非标准目标表述。"},{"id":"basics-86","module":"basics","title":"基础知识","number":86,"type":"single","prompt":"下列描述项目管理的特点错误的是:","options":[{"key":"A","text":"项目的复杂性随其范围不同变化很大，项目愈大愈复杂，其所包括或涉及的学科、技术种类也愈多。"},{"key":"B","text":"项目负责人的位置是由特殊需要形成的，因为他行使着大部分传统职能组织以外的职能。"},{"key":"C","text":"项目一般由多个部分组成，工作可能跨越多个部门，需要运用多种学科的知识来解决问题。"},{"key":"D","text":"项目管理具有单独性。"}],"answer":["D"],"explanation":"项目管理常需要跨部门协调并整合多个专业。项目有独特目标，“单独性”不能概括其组织和管理特点。"},{"id":"basics-87","module":"basics","title":"基础知识","number":87,"type":"judge","prompt":"人机交互是一种自然交互，使用者只能通过专用头盔、数据手套等传感设备进行交互，计算机键盘、鼠标无法进行正常交互。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"专用设备可以提高自然交互程度。许多 VR 应用也支持键盘、鼠标或普通控制器。"},{"id":"basics-88","module":"basics","title":"基础知识","number":88,"type":"judge","prompt":"实物虚化是现实世界空间向多维信息化空间的一种映射，主要包括基本模型构建、空间跟踪、声音定位、视觉跟踪和视点感应等关键技术。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"实物虚化把现实对象及其动作、位置、声音等转化为虚拟空间可处理的数据，依赖建模、定位和多类跟踪技术。"},{"id":"basics-89","module":"basics","title":"基础知识","number":89,"type":"judge","prompt":"虚拟现实系统的基本组成主要包括观察者、传感器、效果产生器及实景仿真器。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"观察者提供操作，传感器采集信息，实景仿真器更新环境，效果产生器向观察者反馈，四者构成交互回路。"},{"id":"basics-90","module":"basics","title":"基础知识","number":90,"type":"single","prompt":"根据安全系统的网络性能指标，以下描述错误的是？","options":[{"key":"A","text":"邮件加密系统"},{"key":"B","text":"虚拟专网的建立"},{"key":"C","text":"网络故障率"},{"key":"D","text":"邮件防病毒网关"}],"answer":["C"],"explanation":"网络故障率用于衡量运行可靠性。邮件加密、VPN 和邮件防病毒网关均为安全机制，题目按找不同作答。"},{"id":"basics-91","module":"basics","title":"基础知识","number":91,"type":"judge","prompt":"三维跟踪器能够实时地测量用户身体或其局部的方向和位置，并将信息输入给虚拟现实系统，然后根据用户当前的视角刷新虚拟场景的显示。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"跟踪器测量身体或局部的空间位置与朝向，渲染端据此重新计算视角，使图像跟随动作更新。"},{"id":"basics-92","module":"basics","title":"基础知识","number":92,"type":"judge","prompt":"安装防火墙的作用在于弥补网络服务的脆弱性、控制对网络的存取、集中的安全管理、网络使用情况的记录及统计。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"防火墙可按策略控制访问并记录通信。它通过限制暴露面和集中实施规则，降低部分网络服务风险。"},{"id":"basics-93","module":"basics","title":"基础知识","number":93,"type":"single","prompt":"沉浸式虚拟现实的特点不包括____。","options":[{"key":"A","text":"具有高度沉浸感"},{"key":"B","text":"对硬件要求低"},{"key":"C","text":"良好的系统集成性"},{"key":"D","text":"具有高度的实时性能"}],"answer":["B"],"explanation":"沉浸式系统须及时处理跟踪和渲染，并集成显示及交互设备，通常对硬件性能有较高要求。"},{"id":"basics-94","module":"basics","title":"基础知识","number":94,"type":"single","prompt":"以下哪种可以解决显示输出问题，即如何根据虚拟环境输出用户可以直接感受到的真实信号(声、光、电)。","options":[{"key":"A","text":"实物实化"},{"key":"B","text":"实物虚化"},{"key":"C","text":"虚物虚化"},{"key":"D","text":"虚物实化"}],"answer":["D"],"explanation":"虚物实化将计算得到的虚拟场景转成用户可直接感知的光、声或力等输出。"},{"id":"basics-95","module":"basics","title":"基础知识","number":95,"type":"single","prompt":"关于虚拟现实隐私权侵权的表现形式以下描述错误的是？","options":[{"key":"A","text":"用户之间侵犯个人自主决定和私人虚实融合空间"},{"key":"B","text":"运营商的免责条使得数据隐私被侵犯后完全无法维权"},{"key":"C","text":"开发商和运营商侵犯用户数据隐私"},{"key":"D","text":"用户或开发商侵犯非用户私人现实空间"}],"answer":["B"],"explanation":"免责条款的效力需要结合具体规则判断。用户仍可能依法主张权利，题干“完全无法维权”过于绝对。"},{"id":"basics-96","module":"basics","title":"基础知识","number":96,"type":"judge","prompt":"差错控制编码就是对网络中传输的数字信号进行抗干扰编码，目的是为了提高数字通信系统的容错性和可靠性。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"差错控制通过加入有规则的冗余，使接收端能够检错或纠错，也可触发重传，从而提升传输可靠性。"},{"id":"basics-97","module":"basics","title":"基础知识","number":97,"type":"single","prompt":"下面描述机械跟踪器特征错误的是____。","options":[{"key":"A","text":"抖动比较大，延迟高。"},{"key":"B","text":"机械臂受尺寸限制，工作范围有限。"},{"key":"C","text":"不受周围环境中的金属物质和磁场的影响。"},{"key":"D","text":"简单且易于使用。"}],"answer":["A"],"explanation":"机械跟踪直接测量关节变化，通常具有较小延迟和抖动。机械臂长度和结构会限制活动空间。"},{"id":"basics-98","module":"basics","title":"基础知识","number":98,"type":"single","prompt":"以下哪个不属于传输介质？","options":[{"key":"A","text":"光缆"},{"key":"B","text":"双绞线"},{"key":"C","text":"同轴电缆"},{"key":"D","text":"尼龙线"}],"answer":["D"],"explanation":"光缆传光，双绞线和同轴电缆传电信号。普通尼龙线并非此处所指的网络传输介质。"},{"id":"basics-99","module":"basics","title":"基础知识","number":99,"type":"single","prompt":"下面描述错误的是？","options":[{"key":"A","text":"力反馈提供虚拟对象表面柔顺性、对象的重量和惯性等实时信息。"},{"key":"B","text":"接触反馈可以主动抵抗用户的触摸运动，阻止用户穿过虚拟表面。"},{"key":"C","text":"触觉反馈与前面介绍的视觉反馈和三维听觉反馈结合起来，可以大大提高虚拟现实系统的真实感。"},{"key":"D","text":"触觉反馈可以分为接触反馈和力反馈两种模态。"}],"answer":["B"],"explanation":"接触反馈主要模拟皮肤接触、纹理或振动。抵抗手部移动并阻止其穿过虚拟表面是力反馈的作用。"},{"id":"basics-100","module":"basics","title":"基础知识","number":100,"type":"judge","prompt":"开放回路意味着信息流是双向的，用户不仅能将信息从鼠标发送到计算机，计算机也能将信息传递给鼠标。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"开环系统不利用输出反馈调整输入。鼠标向计算机传动作、计算机再向鼠标发送触觉反馈，描述的是反馈回路。"},{"id":"basics-101","module":"basics","title":"基础知识","number":101,"type":"judge","prompt":"指令寄存器用以存放现行指令，以便在整个指令执行过程中，实现一条指令的全部功能控制。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"指令寄存器保存当前指令的编码，控制器利用它进行译码并生成执行所需的控制信号。"},{"id":"basics-102","module":"basics","title":"基础知识","number":102,"type":"judge","prompt":"面向对象方法的核心是继承。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"继承是面向对象的一项机制。面向对象方法以对象及其协作为基本建模方式，也涉及封装与多态。"},{"id":"basics-103","module":"basics","title":"基础知识","number":103,"type":"single","prompt":"入网的每台计算机都有类似结构的域名，以下描述正确的是:","options":[{"key":"A","text":"计算机主机名.机构名.顶级域名.网络名"},{"key":"B","text":"机构名.计算机主机名.顶级域名.网络名"},{"key":"C","text":"计算机主机名.机构名.网络名.顶级域名"},{"key":"D","text":"机构名.计算机主机名.网络名.顶级域名"}],"answer":["C"],"explanation":"DNS 域名按从具体到上级的顺序书写，顶级域位于最右侧。主机名和中间各级域的数量可因命名方式而异。"},{"id":"basics-104","module":"basics","title":"基础知识","number":104,"type":"judge","prompt":"超文本方式将菜单集成于文本信息之中，采用指针连接的网状交叉索引方式，对不同来源的信息加以链接，形成了一个非线性的网状结构。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"超文本将不同文档或文档内部位置通过链接连接，用户可沿多条路径浏览，形成非线性结构。"},{"id":"basics-105","module":"basics","title":"基础知识","number":105,"type":"judge","prompt":"在C#中，int[][]是定义一个int型的二维数组。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"int[][] 是交错数组，每个元素都是 int[]，各行长度可以不同。矩形二维数组写作 int[,]。"},{"id":"basics-106","module":"basics","title":"基础知识","number":106,"type":"judge","prompt":"数据衣是在虚拟现实系统中比较常用的运动捕捉设备，是为了让虚拟现实系统识别全身运动而设计的输出装置。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"数据衣用于测量身体动作并将数据送入系统，属于输入设备。系统再据此驱动虚拟角色。"},{"id":"basics-107","module":"basics","title":"基础知识","number":107,"type":"judge","prompt":"为了使人脑能理解虚拟世界中的深度，VR的图形显示设备必须简化图像。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"深度感可借助双眼视差、遮挡、透视和运动视差形成。简化图像属于可能采用的性能优化手段。"},{"id":"basics-108","module":"basics","title":"基础知识","number":108,"type":"judge","prompt":"主存储器是计算机系统中的重要部件，用来存放计算机运行时的大量程序和数据，主存储器目前一般用 MOS 半导体存储器构成。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"主存保存处理器运行所需的程序和数据。现代计算机主存通常使用采用 MOS 工艺的 DRAM。"},{"id":"basics-109","module":"basics","title":"基础知识","number":109,"type":"judge","prompt":"结构属于引用类型，字符串属于值类型。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"C# 的 struct 属于值类型，string 属于引用类型。字符串的不可变性与类型归属是两回事。"},{"id":"basics-110","module":"basics","title":"基础知识","number":110,"type":"judge","prompt":"值类型变量直接存放真正的数据，引用类型变量存放的是指向真正数据的内存地址。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"值类型变量含有该类型的值，引用类型变量持有对象引用。“内存地址”可作入门类比，托管引用由运行时管理。"},{"id":"basics-111","module":"basics","title":"基础知识","number":111,"type":"single","prompt":"下面描述立体眼镜特点错误的是_____。","options":[{"key":"A","text":"价格昂贵"},{"key":"B","text":"佩戴时间长且不易疲劳"},{"key":"C","text":"结构简单"},{"key":"D","text":"外形轻巧"}],"answer":["A"],"explanation":"普通立体眼镜可做得结构简单、轻便且成本较低。观看疲劳还会受到内容、视差和佩戴时间的影响。"},{"id":"basics-112","module":"basics","title":"基础知识","number":112,"type":"single","prompt":"桌面式虚拟现实系统的特点不包括_____。","options":[{"key":"A","text":"价格低廉"},{"key":"B","text":"结构简单"},{"key":"C","text":"易于普及推广"},{"key":"D","text":"真实的体验丰富"}],"answer":["D"],"explanation":"桌面式 VR 使用普通屏幕和常见输入设备，结构相对简单且容易推广。其沉浸式感官体验通常较有限。"},{"id":"basics-113","module":"basics","title":"基础知识","number":113,"type":"single","prompt":"关于瀑布模型中每项开发活动的特点，以下描述错误的是:","options":[{"key":"A","text":"利用这一输入，实施该项活动应完成的工作内容。"},{"key":"B","text":"对该项活动的实施工作成果进行评审。"},{"key":"C","text":"从上一项开发活动接受该项活动的工作对象作为输出。"},{"key":"D","text":"给出该项活动的工作成果，作为输出传给下一项开发活动。"}],"answer":["C"],"explanation":"上一阶段的工作成果是本阶段的输入。本阶段完成工作并评审后，再把成果作为输出交给下一阶段。"},{"id":"basics-114","module":"basics","title":"基础知识","number":114,"type":"single","prompt":"以下哪类跟踪器保持了高精度姿态跟踪，同时还增强了跟踪鲁棒性？","options":[{"key":"A","text":"光学跟踪器"},{"key":"B","text":"混合跟踪器"},{"key":"C","text":"GPS跟踪器"},{"key":"D","text":"惯性跟踪器"}],"answer":["B"],"explanation":"混合跟踪将多种传感方式融合，例如用惯性数据补足短时响应、用光学校正漂移，从而改善精度和鲁棒性。"},{"id":"basics-115","module":"basics","title":"基础知识","number":115,"type":"judge","prompt":"for循环中,可以用 break语句跳出循环体。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"break 会结束最内层的可退出结构。在 for 循环体内直接使用时，控制流跳到循环之后。"},{"id":"basics-116","module":"basics","title":"基础知识","number":116,"type":"single","prompt":"几何构造系统提供了描述仿真对象哪些物理特性的信息。","options":[{"key":"A","text":"物体和位置"},{"key":"B","text":"外形、颜色和位置"},{"key":"C","text":"物体和场景"},{"key":"D","text":"外形和颜色"}],"answer":["B"],"explanation":"几何构造需描述物体的形状、外观属性及空间位置，以便生成场景并确定物体的空间关系。"},{"id":"basics-117","module":"basics","title":"基础知识","number":117,"type":"judge","prompt":"在同一介质上，同时传输多个有限带宽信号的方法，被称为数据交换技术。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"同一介质承载多路信号属于多路复用，常见方式有时分、频分和波分。交换主要解决数据如何在网络节点间转发。"},{"id":"basics-118","module":"basics","title":"基础知识","number":118,"type":"single","prompt":"以下关于局域网的介质访问控制方式错误的是？","options":[{"key":"A","text":"令牌总线访问控制方式"},{"key":"B","text":"载波侦听多路访问"},{"key":"C","text":"令牌环访问控制方式"},{"key":"D","text":"令牌环网络控制方式"}],"answer":["D"],"explanation":"令牌总线、载波侦听多路访问和令牌环都是介质访问机制。“令牌环网络控制方式”在此是对标准名称的重复或误写。"},{"id":"basics-119","module":"basics","title":"基础知识","number":119,"type":"single","prompt":"虚拟现实主要研究对象是_____。","options":[{"key":"A","text":"以上全部"},{"key":"B","text":"虚拟环境感知信息合成的真实性"},{"key":"C","text":"虚拟环境表示的准确性"},{"key":"D","text":"人与虚拟环境交互的自然性"}],"answer":["A"],"explanation":"VR 需要准确表示环境、合成可信的感知信息，并支持自然交互，三个方面都是研究对象。"},{"id":"basics-120","module":"basics","title":"基础知识","number":120,"type":"single","prompt":"TCP/IP协议规定，每个地址由____位二进制数组成?","options":[{"key":"A","text":"8"},{"key":"B","text":"16"},{"key":"C","text":"32"},{"key":"D","text":"64"}],"answer":["C"],"explanation":"题目采用 IPv4 口径，地址由 32 位组成，通常写成四段十进制。IPv6 地址长 128 位。"},{"id":"basics-121","module":"basics","title":"基础知识","number":121,"type":"single","prompt":"非常明确的表明了测试过程中存在的不同的级别，并且非常清晰的描述了这些测试阶段和开发阶段的对应关系，指的是以下哪个模型特征？","options":[{"key":"A","text":"原型化模型"},{"key":"B","text":"V模型"},{"key":"C","text":"螺旋模型"},{"key":"D","text":"迭代模型"}],"answer":["B"],"explanation":"V 模型把需求、设计等开发阶段与相应测试层级配对，例如用验收测试验证用户需求。"},{"id":"basics-122","module":"basics","title":"基础知识","number":122,"type":"single","prompt":"以下哪个不属于虚拟现实相关的法律？","options":[{"key":"A","text":"专利法"},{"key":"B","text":"网络安全法"},{"key":"C","text":"劳动法"},{"key":"D","text":"密码法"}],"answer":["C"],"explanation":"按 VR 技术、数据与知识产权的直接相关性，专利法、网络安全法和密码法更符合题意。劳动法仍适用于相关企业的用工。"},{"id":"basics-123","module":"basics","title":"基础知识","number":123,"type":"judge","prompt":"密码法是指采用特定变换的方法对信息等进行加密保护、安全认证的技术、产品和服务。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"题干给出的是“密码”的定义。密码法是规范密码应用和管理的法律。"},{"id":"basics-124","module":"basics","title":"基础知识","number":124,"type":"single","prompt":"跟踪器的性能指标主要包括_____。","options":[{"key":"A","text":"精度、抖动、偏差和延迟"},{"key":"B","text":"偏差和延迟"},{"key":"C","text":"精度和延迟"},{"key":"D","text":"精度和抖动"}],"answer":["A"],"explanation":"精度衡量测量接近真实值的程度，抖动描述短时波动，偏差描述系统性误差，延迟描述实际动作到结果输出的时间差。"},{"id":"basics-125","module":"basics","title":"基础知识","number":125,"type":"judge","prompt":"设计人员高度专业化不属于典型的信息系统项目的特点。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"信息系统项目往往涉及不同业务及技术专业，设计人员会承担专门分工，专业化可以是典型特点。"},{"id":"basics-126","module":"basics","title":"基础知识","number":126,"type":"single","prompt":"Oculus Rift是一款为电子游戏设计的头戴式显示器，有两个目镜，每个目镜的分辨率为____。","options":[{"key":"A","text":"640像素*800像素"},{"key":"B","text":"800像素*600像素"},{"key":"C","text":"1280像素*600像素"},{"key":"D","text":"1920像素*1280像素"}],"answer":["A"],"explanation":"选项对应早期 Oculus Rift DK1 的整屏 1280 × 800，左右眼各分一半，为每眼 640 × 800。Rift 不同型号的规格有差异。"},{"id":"basics-127","module":"basics","title":"基础知识","number":127,"type":"judge","prompt":"虚拟现实可以应用在多个领域之中，但是唯独不可以应用在教育领域。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"VR 可用于虚拟实验、技能实训和场景教学，让学习者在模拟环境中练习或观察难以直接接触的过程。"},{"id":"basics-128","module":"basics","title":"基础知识","number":128,"type":"single","prompt":"如若将虚拟现实出版物认定为计算机程序，并不能使其获得有效的著作权保护，原因是____？","options":[{"key":"A","text":"著作权法保护的对象是符合一定保护条件的\\"表达\\"，任何思想和实用性功能都不在著作权法的保护之列。"},{"key":"B","text":"计算机程序的著作权保护规则套用在虚拟现实出版物上，会导致真正能够体现虚拟现实出版物独特特征、作为出版物营销点的虚拟画面本身无法受到著作权法的保护。"},{"key":"C","text":"以上全部。"},{"key":"D","text":"著作权法意义上的计算机程序，指的是一系列代码形式的指令序列或符号序列，并不包括运行计146算机程序后被调取出的音乐、图画、动画等。"}],"answer":["C"],"explanation":"软件保护着眼于程序表达，思想和实用功能通常不直接受著作权保护。画面、音乐和动画可根据各自的表达及保护条件分别判断。"},{"id":"basics-129","module":"basics","title":"基础知识","number":129,"type":"judge","prompt":"远程存在系统可以使用户通过计算机和网络获得足够的感知和交互反馈，犹如身临其境一般，并可以对远端现场进行遥控操作。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"远程存在系统把远端的感知信息传给操作者，再把操作指令传回远端设备，形成感知与控制回路。"},{"id":"basics-130","module":"basics","title":"基础知识","number":130,"type":"single","prompt":"在人的感觉中，哪个感官摄取的信息量最大，反应最敏锐？","options":[{"key":"A","text":"视觉"},{"key":"B","text":"嗅觉"},{"key":"C","text":"触觉"},{"key":"D","text":"听觉"}],"answer":["A"],"explanation":"视觉可同时传递大量空间、形状、颜色和运动信息。“反应最敏锐”依任务而变，本题主要依据获取的信息量。"},{"id":"basics-131","module":"basics","title":"基础知识","number":131,"type":"single","prompt":"以下哪种装置用于接收效果产生器所产生的沉浸式虚拟现实系统的体系结构不包括以下哪种信号？","options":[{"key":"A","text":"实景仿真器"},{"key":"B","text":"应用系统"},{"key":"C","text":"几何构造系统"},{"key":"D","text":"三维立体声音设备"}],"answer":["D"],"explanation":"题干混入两个问句。按“接收效果产生器输出的装置”理解，立体声设备接收音频信号并向用户播放。其余选项属于仿真及建模环节。"},{"id":"basics-132","module":"basics","title":"基础知识","number":132,"type":"judge","prompt":"for循环只能用于循环次数已经确定的情况。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"for 可根据运行时条件决定是否继续，也可用 break 退出，因此可以用于事先无法确定次数的循环。"},{"id":"basics-133","module":"basics","title":"基础知识","number":133,"type":"single","prompt":"下列哪个阶段花费项目生命周期时间最长？","options":[{"key":"A","text":"执行项目工作"},{"key":"B","text":"组织与准备"},{"key":"C","text":"结束项目"},{"key":"D","text":"启动项目"}],"answer":["A"],"explanation":"在一般项目中，执行阶段承担主要交付物的制作与实施，通常耗时最长。实际时间分布随项目而异。"},{"id":"basics-134","module":"basics","title":"基础知识","number":134,"type":"single","prompt":"沉浸式虚拟现实系统的体系结构不包括以下哪种？","options":[{"key":"A","text":"数据手套"},{"key":"B","text":"投影显示系统"},{"key":"C","text":"立体眼镜"},{"key":"D","text":"电机设备"}],"answer":["D"],"explanation":"数据手套、投影系统和立体眼镜是常见的沉浸式交互或显示组件。电机可作为某些设备的内部部件，通常不单独作为体系结构组件列出。"},{"id":"basics-135","module":"basics","title":"基础知识","number":135,"type":"judge","prompt":"人机交互的内容主要体现于计算机提供的是\\"环境\\"，而不是数据和信息。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"VR 交互以可感知、可操作的虚拟环境作为主要界面。数据和信息通过场景、对象及其动态反馈呈现。"},{"id":"design-1","module":"design","title":"内容设计","number":1,"type":"single","prompt":"Geomagic Wrap软件功能说法错误的是？","options":[{"key":"A","text":"Geomagic Wrap高清面片构建不可以创建封闭面片"},{"key":"B","text":"Geomagic Wrap是一款3D扫描分析软件"},{"key":"C","text":"Geomagic Wrap将3D扫描数据转换为3D模型"},{"key":"D","text":"Geomagic Wrap包含一套纹理贴图处理工具，可控制模型上的自定义纹理分组"}],"answer":["A"],"explanation":"Wrap 的高清面片构建可生成封闭面片；因此 A 中“不可以”与软件能力相反。该软件面向扫描数据清理、修补、封装和转成可用三维模型。"},{"id":"design-2","module":"design","title":"内容设计","number":2,"type":"judge","prompt":"PS软件选择\\"钢笔\\"工具,按住Ctrl键,当\\"钢笔\\"工具移到锚点上时,暂时将\\"钢笔\\"工具转换为\\"转换点\\"工具","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"Ctrl 临时切换到直接选择工具，用于调整路径锚点或线段；转换点工具对应 Alt。题干把 Ctrl 的临时工具说错了。"},{"id":"design-3","module":"design","title":"内容设计","number":3,"type":"judge","prompt":"Maya软件多边形圆柱体常用参数为半径、高度、轴向细分数、高度细分数、端面细分数","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Maya 多边形圆柱体创建历史含半径、高度、轴向细分、高度细分和端面细分等参数。它们分别控制圆周、轴向长度及两端网格密度。"},{"id":"design-4","module":"design","title":"内容设计","number":4,"type":"judge","prompt":"Maya软件NURBS球体参数分别有开始扫描、结束扫描、次数、分段数、跨度数","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"NURBS 球体的创建历史可设置起止扫描角度、次数（Degree）、分段/面片数及跨度数。它们控制球面的截取范围和曲面参数化密度。"},{"id":"design-5","module":"design","title":"内容设计","number":5,"type":"judge","prompt":"Maya软件多边形圆柱体的参数轴向细分数可以设置多边形圆柱体的轴向分段数值。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"轴向细分数控制圆柱底面圆周方向的分段数，分段增多会让截面更圆滑、面数也增加。题干对参数作用的描述正确。"},{"id":"design-6","module":"design","title":"内容设计","number":6,"type":"single","prompt":"关于管理美术资源和关卡设计在性能优化方面说法错误的是？","options":[{"key":"A","text":"贴花的性能开销和它们覆盖的像素数量有关"},{"key":"B","text":"越高的贴图分辨率越快"},{"key":"C","text":"静态光照最快，固定光照稍慢一些，动态光照最慢"},{"key":"D","text":"Skybox Textures都能用来代替实际的几何体物件并有效的提高性能"}],"answer":["B"],"explanation":"更高分辨率纹理一般需要更多显存和带宽，通常不会更快。光照层级、贴花覆盖像素、天空盒替代远景几何体等其余说法符合常见优化原则。"},{"id":"design-7","module":"design","title":"内容设计","number":7,"type":"single","prompt":"下面常用的内置2D程序纹理的种类介绍理解错误的是？","options":[{"key":"A","text":"布料是用来模拟生活中的布料效果"},{"key":"B","text":"文件是可以使用文件纹理节点为物体赋予纹理贴图"},{"key":"C","text":"棋盘格是用于模拟有两种颜色的正方形方格的效果"},{"key":"D","text":"渐变是常用来制作一些特殊的效果"}],"answer":["B"],"explanation":"File 节点读取外部图像文件，属于文件纹理而不是程序生成的程序纹理。布料、棋盘格和渐变则是 Maya 中常见的程序纹理类型。"},{"id":"design-8","module":"design","title":"内容设计","number":8,"type":"judge","prompt":"Maya软件曲面修改工具中的曲面编辑工具是可以使用操纵器来更改曲面上的点","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"曲面编辑类工具可通过操纵器调整曲面上的编辑点或控制点，从而改变曲面形状。题干对工具用途的概括正确。"},{"id":"design-9","module":"design","title":"内容设计","number":9,"type":"judge","prompt":"Photoshop软件工作界面主要由菜单栏、工具箱、属性栏、状态栏和控制面板组成","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Photoshop 工作区通常包含菜单栏、工具箱、工具选项栏、状态栏和各类面板。不同版本面板布局可以自定义，但题干列出的主要区域成立。"},{"id":"design-10","module":"design","title":"内容设计","number":10,"type":"single","prompt":"UE4虚拟摄像机Actor的Details面板参数中的Auto Exposure是()","options":[{"key":"A","text":"模拟因摄像机镜头瑕疵导致观看明亮物体时出现的光线散射"},{"key":"B","text":"近似模拟出因吸收造成的光线衰减效果"},{"key":"C","text":"影响光团发出的间接光照，从而改变场景的亮度、颜色或色调"},{"key":"D","text":"可模拟人眼对明暗区域的调节"}],"answer":["D"],"explanation":"Auto Exposure 根据画面亮暗自动调整曝光，模拟人眼从明处转向暗处时的适应过程。镜头眩光、光衰减和间接光属于其他效果或照明参数。"},{"id":"design-11","module":"design","title":"内容设计","number":11,"type":"single","prompt":"下列关于材质概述错误的是？","options":[{"key":"A","text":"半透明是该属性可以使场景中的对象产生透明效果，而使用贴图可以产生局部透明效果"},{"key":"B","text":"折射是指光线透过对象后，改变了原有的光线的投射角度，使光线产生偏差，如透过水面看对象"},{"key":"C","text":"漫反射是物体表面高亮处显示的颜色"},{"key":"D","text":"材质属性与灯光属性相辅相成，材质属性体现物体受灯光的影响"}],"answer":["C"],"explanation":"漫反射描述入射光向各方向散射后呈现的基础表面颜色，不是高亮处的镜面高光颜色。高光应由镜面反射等参数描述，因此错误项为 C。"},{"id":"design-12","module":"design","title":"内容设计","number":12,"type":"judge","prompt":"Geomagic Wrap可以将3D扫描数据转换为3D模型","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Wrap 可导入并处理扫描得到的点云或网格，再生成多边形模型。其扫描数据转模型正是软件的核心用途之一。"},{"id":"design-13","module":"design","title":"内容设计","number":13,"type":"judge","prompt":"Maya软件多边形管道的参数高度细分数可以设置多边形管道的高度分段数值。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"多边形管道的高度细分参数控制管道轴向（高度方向）的分段数量。题干描述与参数含义一致。"},{"id":"design-14","module":"design","title":"内容设计","number":14,"type":"judge","prompt":"Maya软件多边形平面的参数高度细分数可以设置多边形平面的高度分段数值","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"多边形平面有宽度和高度两个尺寸参数以及对应细分参数；高度决定平面的纵向尺寸。题干正确。"},{"id":"design-15","module":"design","title":"内容设计","number":15,"type":"judge","prompt":"\\"木材\\"纹理中的颗粒间距是颗粒斑点之间的平均距离","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"木材程序纹理的颗粒间距参数表示颗粒斑点之间的平均间隔，改变它会影响纹理颗粒疏密。题干描述正确。"},{"id":"design-16","module":"design","title":"内容设计","number":16,"type":"judge","prompt":"Maya软件多边形类型中\\"文本\\"选项卡参数的前导比例是均匀地调整所有线之间的垂直问距。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Leading（行距/前导）控制多行文字基线之间的垂直间距，不是字母的水平间距。题干所述正确。"},{"id":"design-17","module":"design","title":"内容设计","number":17,"type":"single","prompt":"下列选项中那个不属于点云数据？","options":[{"key":"A","text":"颜色信息"},{"key":"B","text":"激光反射强度"},{"key":"C","text":"二维图片"},{"key":"D","text":"三维坐标"}],"answer":["C"],"explanation":"点云通常由三维坐标构成，可附带颜色、反射强度等属性；二维图片不是点云数据本身。故选 C。"},{"id":"design-18","module":"design","title":"内容设计","number":18,"type":"judge","prompt":"UE4媒体播放编辑器在该软件中播放来自媒体的文件或者其他URL地址的源媒体","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"UE4 Media Player 用于播放媒体源，可连接本地媒体文件或受支持的 URL 媒体源。题干对其用途的描述正确。"},{"id":"design-19","module":"design","title":"内容设计","number":19,"type":"single","prompt":"下面关于UE4工具编辑器理解错误的是？","options":[{"key":"A","text":"UE4在静态网格体编辑器中可以为静态网格模型资源设置LODs(或者叫Level Of Details设置)"},{"key":"B","text":"UE4的Paper2D图片编辑器能够设置并编辑独立的Paper 2D Sprites"},{"key":"C","text":"UE4的Physics Asset工具编辑器用可以新建材质"},{"key":"D","text":"UE4级联系统提供了实时的粒子效果查看,以及效果的模块化编辑,能够多快好省地创建制作哪怕是最为复杂的特效表现"}],"answer":["C"],"explanation":"Physics Asset Editor 用于创建和编辑骨骼物理资产、刚体和约束，不是新建材质的工具。材质在材质编辑器中创建，故 C 错。"},{"id":"design-20","module":"design","title":"内容设计","number":20,"type":"single","prompt":"下面关于UE4的环绕、移动及跟踪操作正确的是？","options":[{"key":"A","text":"按Alt+鼠标左键＋拖动，可以围绕一个单独的支点或兴趣点翻转视口"},{"key":"B","text":"以上都正确"},{"key":"C","text":"按Alt+鼠标右键＋拖动，可以向前推动相机使其接近或远离一个单独支点或兴趣点"},{"key":"D","text":"按Alt+鼠标中键＋拖动，可以根据鼠标移动的方向将相机向左、右、上、下移动"}],"answer":["B"],"explanation":"Alt+左键环绕、Alt+右键推近/拉远、Alt+中键平移视口，是常见透视视口控制组合。A、C、D 均正确，选“以上都正确”。"},{"id":"design-21","module":"design","title":"内容设计","number":21,"type":"single","prompt":"下面关于纹理的通用属性参数定义错误的是？","options":[{"key":"A","text":"曝光是用于控制纹理节点的曝光值"},{"key":"B","text":"Alpha为亮度是表示Alpha的输出由纹理的亮度来决定"},{"key":"C","text":"颜色增益是该参数用于控制纹理颜色输出的强度，可调整纹理中的浅色部分"},{"key":"D","text":"Alpha增益是适用于位移或凹凸纹理，可偏移纹理Alpha输出的系数"}],"answer":["D"],"explanation":"Alpha Gain 是乘数，用来缩放纹理输出的 Alpha；偏移应由 Alpha Offset 控制。D 混淆了增益和偏移，因此错误。"},{"id":"design-22","module":"design","title":"内容设计","number":22,"type":"judge","prompt":"扫描仪测站设置原则是在可视范围内,保证80%以上数据的完整性,站站之间重复率40%左右","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"测站通常应确保较高数据完整率，并保留足够重叠以便配准；题库其他同类题给出的规范是完整率约 90%、重叠约 20%至30%。80%与40%并非这里采用的参数组合。"},{"id":"design-23","module":"design","title":"内容设计","number":23,"type":"judge","prompt":"尽量将类似信息的光源合并。比如，车的头灯可以用一个光源以及一个光照函数让它看起来是两个灯的效果","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"把功能相似、邻近的灯光合并可减少灯光数量和渲染开销。车灯可用一个光源配合光照函数模拟多个灯的视觉效果。"},{"id":"design-24","module":"design","title":"内容设计","number":24,"type":"judge","prompt":"PS软件选择\\"文件\\\\>打开\\"命令,或按Ctrl+D组合键,弹出\\"打开\\"对话框","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"Photoshop 的“打开”快捷键是 Ctrl+O；Ctrl+D 是取消选区。题干给出的快捷键错误。"},{"id":"design-25","module":"design","title":"内容设计","number":25,"type":"judge","prompt":"材质的通用属性透明度是指该参数用来控制物体的透明度，默认情况下是完全不透明","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"材质透明度用于控制表面透明程度，默认不透明意味着透明度为零或不显示透过效果。题干正确。"},{"id":"design-26","module":"design","title":"内容设计","number":26,"type":"single","prompt":"下列关于扫描仪测站设置的一般遵守的原则说法错误的是？","options":[{"key":"A","text":"在可视范围内,保证90%以上数据的完整性,站站之间重复率20%\\\\~30%左右"},{"key":"B","text":"相邻两站之间有不少于2个可清晰识别标靶或特别标志"},{"key":"C","text":"扫描仪至扫描对象平面的距离要在仪器标称测距精度的最佳工作范围"},{"key":"D","text":"要使得扫描仪所架设的各个测站可以扫描到目标区域的全部范围"}],"answer":["B"],"explanation":"测站规范的重叠率应足以保证点云拼接，通常不是仅 20%至30%以外的随意标准；B 的标靶数量也存在不同课程口径。题干问“说法错误”，A 的 90%/20%至30%及 C、D 均常见，最可疑的是 B 的“不少于2个”要求不足，建议按课程标准核验。"},{"id":"design-27","module":"design","title":"内容设计","number":27,"type":"judge","prompt":"UE4虚拟摄像机可以借助摄像机动画(Camera Anim)来创建简短的过场动画","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Camera Animation（摄像机动画）可为摄像机加入抖动、摇移等短时动画效果，常用于过场或镜头表现。题干正确。"},{"id":"design-28","module":"design","title":"内容设计","number":28,"type":"single","prompt":"Maya软件有关创建多边形管道说法错误的是？","options":[{"key":"A","text":"多边形管道的参数端面细分数可以设置多边形管道的端面分段数值"},{"key":"B","text":"多边形管道参数修改在其\\"属性编辑器\\"中，展开\\"多边形管道历史\\"卷展栏"},{"key":"C","text":"多边形管道的参数厚度可以设置多边形管道的高度值"},{"key":"D","text":"在\\"多边形建模\\"工具架上右击\\"柏拉图多面体\\"图标可以创建多边形管道"}],"answer":["C"],"explanation":"管道的“厚度”控制内外半径差或壁厚，并不设置管道高度；高度由 Height 参数控制。其余选项所述分段及历史属性基本正确。"},{"id":"design-29","module":"design","title":"内容设计","number":29,"type":"judge","prompt":"PS软件Lab模式是一种国际色彩标准模式，由3个通道组成是透明度、色相、饱和度","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"Lab 由 L（明度）、a（绿到红）和 b（蓝到黄）三个通道构成，不含透明度、色相和饱和度。题干的通道定义错误。"},{"id":"design-30","module":"design","title":"内容设计","number":30,"type":"judge","prompt":"Maya软件\\"建模工具包\\"中的目标焊接是合并顶点或边，以在它们之间创建共享顶点或边。只能在组件属于同一网格时进行合并","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"目标焊接用于把选定顶点或边拖到目标组件上合并；适用组件需处于可兼容的同一多边形网格上下文。题干概括正确。"},{"id":"design-31","module":"design","title":"内容设计","number":31,"type":"judge","prompt":"UE4在静态网格体编辑器中还可以为静态网格模型资源设置LODs(或者叫Level Of Details设置)","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"UE4 静态网格体编辑器可查看并设置静态网格体的 LOD 级别，也可检查每级网格。题干正确。"},{"id":"design-32","module":"design","title":"内容设计","number":32,"type":"judge","prompt":"Maya软件多边形立方体的参数高度细分数可以设置多边形立方体的高度上的分段数量。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"立方体的高度细分数控制高度方向被切分成多少段。提高该值会增加该方向的面数，题干正确。"},{"id":"design-33","module":"design","title":"内容设计","number":33,"type":"single","prompt":"下列哪个点云数据是正确的？","options":[{"key":"A","text":"以上都正确"},{"key":"B","text":"激光反射强度"},{"key":"C","text":"三维坐标"},{"key":"D","text":"颜色信息"}],"answer":["A"],"explanation":"点云可包含坐标、颜色和激光反射强度等信息，这些是点的空间位置及附加属性。三个列举项都成立。"},{"id":"design-34","module":"design","title":"内容设计","number":34,"type":"single","prompt":"下面关于Maya软件EP曲线工具描述错误的是？","options":[{"key":"A","text":"在\\"曲线/曲面\\"工具架中，单击\\"EP曲线工具\\"图标，用鼠标单击创建编辑点的方式来可以绘制曲线"},{"key":"B","text":"EP曲线在\\"编辑点\\"层级中，可以通过更改曲线的控制顶点位置来改变曲线的弧"},{"key":"C","text":"EP曲线常用参数结间距是指定该软件如何将U位置值指定给结"},{"key":"D","text":"EP曲线常用参数曲线次数默认设置\\"3立方\\"适用于大多数曲线"}],"answer":["B"],"explanation":"EP 曲线由编辑点定义，但“编辑点层级通过更改控制顶点位置”混用了编辑点和 CV 两种组件。控制顶点层级才直接移动 CV，因此 B 错。"},{"id":"design-35","module":"design","title":"内容设计","number":35,"type":"judge","prompt":"Maya软件布尔运算的交集，可以将两个多边形对象进行相减运算，以消去对象与其他对象的相交部分，同时也会消去替他对象","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"布尔交集保留两个对象共同占据的重叠体积，不是把交集部分相减删除。题干描述更接近差集，判断错误。"},{"id":"design-36","module":"design","title":"内容设计","number":36,"type":"judge","prompt":"Maya软件曲线修改工具中的延伸曲线是选择曲线或曲面上的曲线来延伸该曲线。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"延伸曲线工具可沿曲线端部继续延长曲线，也可在曲面上的曲线边界条件下执行延伸。题干正确。"},{"id":"design-37","module":"design","title":"内容设计","number":37,"type":"single","prompt":"下列关于各项异性材质\\"镜面反射着色\\"参数含义理解错误的是？","options":[{"key":"A","text":"反射率是控制材质反射光的颜色"},{"key":"B","text":"Fresnel系数是计算将反射光波连接到传入光波的fresnel因子"},{"key":"C","text":"粗糙度是确定曲面的总体粗糙度"},{"key":"D","text":"扩散X/扩散Y是确定高光在X和Y方向上的扩散程度"}],"answer":["A"],"explanation":"反射率控制反射强度/比例，反射颜色才控制反射光颜色。A 把数值强度参数说成颜色参数，故错误。"},{"id":"design-38","module":"design","title":"内容设计","number":38,"type":"judge","prompt":"用于印刷可以使用TIF、EPS格式","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"TIFF/TIF 和 EPS 都常用于印刷工作流，能够保存较高质量或适合排版输出的数据。题干正确。"},{"id":"design-39","module":"design","title":"内容设计","number":39,"type":"judge","prompt":"UE4材质编辑器中，按住\\"T\\"键并用左键单击图来创建常量节点，常量节点是可修改的浮点型变量","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"UE 材质编辑器中按 T 并单击创建的是 Texture Sample 纹理采样节点，不是可修改的浮点常量。题干把快捷键和节点类型都混淆了。"},{"id":"design-40","module":"design","title":"内容设计","number":40,"type":"single","prompt":"下面多边形类型中\\"几何体\\"选项卡中\\"挤出\\"卷展栏的参数描述有误的是？","options":[{"key":"A","text":"\\"挤出\\"卷展栏挤出偏移是设置网格挤出偏移"},{"key":"B","text":"\\"挤出\\"卷展栏挤出距离是控制挤出多边形的数量"},{"key":"C","text":"\\"挤出\\"卷展栏自定义轮廓，该软件最多允许用户保存12个自定义\\"挤出剖面曲线\\"形状"},{"key":"D","text":"\\"挤出\\"卷展栏挤出分段是控制沿挤出面的细分数"}],"answer":["B"],"explanation":"Extrude Distance 控制挤出长度，不控制挤出多边形的数量；数量通常由分段设置控制。故错误描述为 B。"},{"id":"design-41","module":"design","title":"内容设计","number":41,"type":"single","prompt":"下面关于Nibiru Creator软件工具说法错误的是？","options":[{"key":"A","text":"Nibiru Creator有三维无代码可视化工具，底层采用自主研发的Nibiru Studio引擎"},{"key":"B","text":"Nibiru Creator拥有人工智能后台数据分析能力，支持多个硬件终端和网页模式"},{"key":"C","text":"Nibiru Creator是上海曼恒数字公司设计开发的一款国产无代码三维交互智能引擎工具"},{"key":"D","text":"Nibiru Creator在交通、水利、金融、教育等场景得到广泛应用"}],"answer":["C"],"explanation":"Nibiru Creator 的开发主体与上海曼恒数字的产品归属说法不符；该选项把它归为另一家公司的产品。其余介绍与该类无代码三维交互工具的定位相符。"},{"id":"design-42","module":"design","title":"内容设计","number":42,"type":"single","prompt":"下面关于Maya软件\\"建模工具包\\"的说法正确的有？","options":[{"key":"A","text":"Maya软件\\"建模工具包\\"包括\\"菜单\\"\\"选择模式\\"\\"选择选项\\"及\\"命令和工具\\"四部分"},{"key":"B","text":"以上都正确"},{"key":"C","text":"Maya软件\\"建模工具包\\"的选择模式单击\\"多组件\\"按钮，可以看到\\"多组件\\"为\\"顶点选择\\"、\\"边选择\\"和\\"面选择\\"三种方式"},{"key":"D","text":"Maya软件\\"建模工具包\\"的选择模式分为\\"选择对象\\"\\"多组件\\"和\\"UV选择\\"三种"}],"answer":["B"],"explanation":"建模工具包包含菜单、选择模式、选择选项以及命令/工具等区域；选择模式又含对象、多组件和 UV 等模式。A、C、D 均成立。"},{"id":"design-43","module":"design","title":"内容设计","number":43,"type":"single","prompt":"下列关于纹理描述理解正确的是？","options":[{"key":"A","text":"纹理是可以用来控制物体表面的质感，增添材质的细节"},{"key":"B","text":"以上都正确"},{"key":"C","text":"纹理是指包裹在物体表面上一层花纹，如木头桌子上的木纹、金属表面的锈斑、地毯上的花纹"},{"key":"D","text":"纹理类型主要包括\\"2D纹理\\"、\\"3D纹理\\"、\\"环境纹理\\"和\\"其他纹理\\"这4种"}],"answer":["B"],"explanation":"纹理可控制表面外观并增加细节，既可指表面图案，也有 2D、3D、环境等类别。A、C、D 都成立，故选“以上都正确”。"},{"id":"design-44","module":"design","title":"内容设计","number":44,"type":"judge","prompt":"UE4媒体播放编辑器可以用于定义媒体文件回放时的设置","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Media Player 资产可配置媒体回放相关设置，并由媒体源提供播放内容。题干对设置功能的描述正确。"},{"id":"design-45","module":"design","title":"内容设计","number":45,"type":"single","prompt":"下面关于Maya软件NURBS圆形常用参数描述错误的是？","options":[{"key":"A","text":"NURBS圆形扫描是用于设置NURBS圆形的弧长范围，当值为180，则可以得到一个圆弧"},{"key":"B","text":"NURBS圆形半径是用于设置NURBS圆形的半径大小"},{"key":"C","text":"NURBS圆形扫描是用于设置NURBS圆形的弧长范围，最大值为360"},{"key":"D","text":"NURBS圆形次数是用于设置NURBS圆形的显示方式，有\\"线性\\"和\\"立方\\"两种选项可选"}],"answer":["D"],"explanation":"NURBS Circle 的次数/阶数用于控制曲线的数学阶次与形状平滑度，不是“线性/立方”的显示方式。该描述将曲线阶次与显示方式混为一谈。"},{"id":"design-46","module":"design","title":"内容设计","number":46,"type":"single","prompt":"下面关于PS软件选择\\"裁剪\\"工具属性栏描述错误的是？","options":[{"key":"A","text":"比例是选择预设的裁剪比例"},{"key":"B","text":"删除裁剪的像素是可以控制裁掉的图像是否彻底删除"},{"key":"C","text":"设置是可以选择裁剪方式"},{"key":"D","text":"拉直是可以快速拉直倾斜的图像"}],"answer":["C"],"explanation":"裁剪工具选项栏中的比例、删除裁剪像素和拉直各有明确用途；“设置可以选择裁剪方式”不是该选项的准确说明。具体版本可显示覆盖网格/设置菜单，但不改变该项表述不准。"},{"id":"design-47","module":"design","title":"内容设计","number":47,"type":"single","prompt":"Maya软件创建多边形对象步骤正确的是？","options":[{"key":"A","text":"按住Shift键，单击鼠标右键，在弹出的菜单中找到创建多边形对象的相关命令"},{"key":"B","text":"按住Ctrl键，单击鼠标右键，在弹出的菜单中找到创建多边形对象的相关命令"},{"key":"C","text":"按住Alt键，单击鼠标左键，在弹出的菜单中找到创建多边形对象的相关命令"},{"key":"D","text":"按住Shift键，单击鼠标左键，在弹出的菜单中找到创建多边形对象的相关命令"}],"answer":["A"],"explanation":"Maya 中 Shift+右键可打开建模相关标记菜单，菜单中可调用多边形创建命令。其他组合键并非该创建菜单的标准操作。"},{"id":"design-48","module":"design","title":"内容设计","number":48,"type":"judge","prompt":"纹理是可以用来控制物体表面的质感，增添材质的细节","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"纹理贴图可改变材质的颜色、粗糙度、凹凸等输入，增加表面视觉细节。题干正确。"},{"id":"design-49","module":"design","title":"内容设计","number":49,"type":"judge","prompt":"PS软件选择\\"魔棒\\"工具,或按Q键可以使用魔棒工具","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"Photoshop 魔棒工具快捷键是 W（与快速选择工具同组），Q 用于快速蒙版模式。题干错误。"},{"id":"design-50","module":"design","title":"内容设计","number":50,"type":"judge","prompt":"UE4在蓝图编辑器中可制作或修改蓝图,蓝图是一种特殊的资源,能够被作为一个新的Actor类型来创建,并且用脚本来响应关卡事件,无须编写任何C++的代码","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"蓝图是 UE 的可视化脚本资源，可定义新的 Actor 类并响应事件，不要求必须编写 C++。复杂项目可以混合使用 C++，但题干说“无须”是成立的。"},{"id":"design-51","module":"design","title":"内容设计","number":51,"type":"single","prompt":"下面关于UE4的Project(项目)理解错误的是？","options":[{"key":"A","text":"最基础的建造单元叫作Object(对象)"},{"key":"B","text":"Character(角色)是Pawn Actor的子类,用作玩家角色"},{"key":"C","text":"Actor(演员)是可以放置在关卡中的任意对象"},{"key":"D","text":"组件用来定义BSP关卡几何体和游戏体积的体积"}],"answer":["D"],"explanation":"BSP 几何体和游戏体积主要由 Brush（画刷）定义；组件是组成 Actor 的功能部件。D 把组件和画刷职责混淆了。"},{"id":"design-52","module":"design","title":"内容设计","number":52,"type":"single","prompt":"Maya软件选择模式中的对象选择模式快捷键是()","options":[{"key":"A","text":"F9"},{"key":"B","text":"F10"},{"key":"C","text":"F11"},{"key":"D","text":"F8"}],"answer":["D"],"explanation":"Maya 的 F8 切换对象/组件模式，F9 顶点、F10 边、F11 面。选项 D 对应 F8。"},{"id":"design-53","module":"design","title":"内容设计","number":53,"type":"single","prompt":"下列哪种格式不是点云存储格式？","options":[{"key":"A","text":"stl"},{"key":"B","text":"xyz"},{"key":"C","text":"imw"},{"key":"D","text":"jpg"}],"answer":["A","D"],"explanation":"STL 是三角网格模型格式，JPG 是栅格图像格式，都不是典型点云格式；XYZ 和 IMW 可用于点云数据。题目设置为单选但存在两个不符合项。"},{"id":"design-54","module":"design","title":"内容设计","number":54,"type":"judge","prompt":"点云数据包括二维坐标、激光反射强度、颜色信息","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"点云的核心空间属性是三维坐标，通常还可附带强度、颜色；二维坐标不能完整表达三维点的位置。故题干错误。"},{"id":"design-55","module":"design","title":"内容设计","number":55,"type":"judge","prompt":"PS软件选择\\"钢笔\\"工具,按住Alt键创建锚点时,将强迫系统以45°或45°的倍数绘制路径","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"钢笔工具按住 Shift 可约束方向为 45° 的倍数；Alt 用于转换锚点/调整方向手柄。题干把快捷键说错。"},{"id":"design-56","module":"design","title":"内容设计","number":56,"type":"single","prompt":"下列关于各项异性材质\\"公用材质属性\\"参数含义理解错误的是？","options":[{"key":"A","text":"半透明深度是控制半透明灯光的散射程度"},{"key":"B","text":"白炽度是用来控制材质发射灯光的颜色及亮度"},{"key":"C","text":"凹凸贴图是通过纹理贴图来控制材质表面的粗糙纹理及凹凸程度"},{"key":"D","text":"环境色是用来模拟环境对该材质球所产生的色彩影响"}],"answer":["A"],"explanation":"半透明深度、白炽度、凹凸贴图和环境色都是常见材质通用属性，描述与各自用途基本一致。题目要求找错误项，但四项均可成立，原题可能存在术语转录错误，需对照教材核验。"},{"id":"design-57","module":"design","title":"内容设计","number":57,"type":"judge","prompt":"Maya软件\\"建模工具包\\"中的连接是可以通过其他边连接顶点和/或边，以达到增加分段的目的。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"连接工具可在选定的顶点或边之间建立新边，从而把面进一步分割。题干对其增加拓扑分段的用途描述正确。"},{"id":"design-58","module":"design","title":"内容设计","number":58,"type":"judge","prompt":"Maya软件多边形管道的参数高度可以设置多边形管道的高度值。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"多边形管道的 Height 参数控制管道沿轴线方向的长度。题干正确。"},{"id":"design-59","module":"design","title":"内容设计","number":59,"type":"judge","prompt":"Maya软件\\"建模工具包\\"中的倒角是可以对多边形网格的顶点进行切角处理，或使其边成为圆形边","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Bevel 可倒角边或顶点，生成切角面或圆滑过渡，降低硬锐边效果。题干正确。"},{"id":"design-60","module":"design","title":"内容设计","number":60,"type":"judge","prompt":"Maya软件\\"多边形类型\\"工具可以创建出多边形文本模型","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Maya 的多边形类型工具能生成可编辑的多边形文本几何体。题干正确。"},{"id":"design-61","module":"design","title":"内容设计","number":61,"type":"single","prompt":"下面关于Maya软件\\"建模工具包\\"中的多边形编辑工具的说法错误的有？","options":[{"key":"A","text":"桥接是可用于在现有多边形网格上的两组面或边之间创建桥接"},{"key":"B","text":"倒角是可以对多边形网格的顶点进行切角处理，或使其边成为圆形边"},{"key":"C","text":"添加分段是可以将选定的多边形组件(边或面)分割为较小的组件"},{"key":"D","text":"挤出是对循环边进行切割、切片和插入操作"}],"answer":["D"],"explanation":"挤出是从面/边等组件延伸新几何体；循环边切割、切片和插入属于多切割一类操作。D 将工具功能说错。"},{"id":"design-62","module":"design","title":"内容设计","number":62,"type":"judge","prompt":"Maya软件EP曲线在\\"控制顶点\\"层级中,可以通过更改曲线的编辑点位置来改变曲线的形状","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"EP 曲线由编辑点定义，CV 曲线才直接由控制顶点定义；在 EP 曲线控制顶点层级移动 CV 的说法不匹配。题干错误。"},{"id":"design-63","module":"design","title":"内容设计","number":63,"type":"judge","prompt":"Skybox Textures都能用来代替实际的几何体物件并有效的提高性能","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"天空盒适合表示远处背景，不适合替代所有近景或可交互几何体。把 Skybox 一概用于替代真实物件并保证性能提升过于绝对。"},{"id":"design-64","module":"design","title":"内容设计","number":64,"type":"judge","prompt":"UE4中Character(角色)是Pawn Actor的子类,用作玩家角色","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Character 是 Pawn 的专门子类，带有角色移动、碰撞等常用功能，通常用于玩家角色。题干正确。"},{"id":"design-65","module":"design","title":"内容设计","number":65,"type":"judge","prompt":"UE4级联系统提供了实时的粒子效果查看,以及效果的模块化编辑,能够多快好省地创建制作哪怕是最为复杂的特效表现","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"UE4 Cascade 是集成式粒子系统编辑器，可实时预览并通过模块化组件配置特效。题干描述正确。"},{"id":"design-66","module":"design","title":"内容设计","number":66,"type":"single","prompt":"下面关于Maya软件\\"软选择\\"卷展栏属性内容的说法错误的有？","options":[{"key":"A","text":"对称启用后，可以以\\"对象X/Y/Z\\"及\\"世界X/Y/Z\\"的方式来对称选择对象组件"},{"key":"B","text":"拖选是可以在多边形对象上按住鼠标右键来进行选择"},{"key":"C","text":"调整/框选是可以可用于调整组件进行框选"},{"key":"D","text":"亮显最近组件启用时，亮显距光标最近的组件，然后用户可以选择它"}],"answer":["B"],"explanation":"右键拖动在 Maya 中通常打开标记菜单或执行视口导航，并非“拖选”组件的通用方式。其余描述分别涉及对称、框选和最近组件高亮，B 不准确。"},{"id":"design-67","module":"design","title":"内容设计","number":67,"type":"judge","prompt":"Maya软件NURBS球体参数中的跨度数是可以设置球体模型的横向分段","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"NURBS 球体的跨度数控制曲面参数方向上的分段/跨度密度，可影响球体网格化的细分表现。题干判断正确。"},{"id":"design-68","module":"design","title":"内容设计","number":68,"type":"single","prompt":"下面关于Lab模式描述错误的是?","options":[{"key":"A","text":"Lab模式在理论上包括了人眼可见的所有色彩,它弥补了CMYK模式和RGB模式的不足"},{"key":"B","text":"Lab模式是一种国际色彩标准模式"},{"key":"C","text":"Lab模式由3个通道组成，分别是亮度、色相、饱和度"},{"key":"D","text":"Lab模式一直扮演着中介者的角色"}],"answer":["C"],"explanation":"Lab 的三个通道为 L 明度、a 绿—红、b 蓝—黄；色相和饱和度是 HSB/HSV 的概念。错误项为 C。"},{"id":"design-69","module":"design","title":"内容设计","number":69,"type":"single","prompt":"PS软件按()组合键,可以恢复到图像的上一步操作","options":[{"key":"A","text":"Ctrl+N"},{"key":"B","text":"Ctrl+O"},{"key":"C","text":"Ctrl+Z"},{"key":"D","text":"Ctrl+A"}],"answer":["C"],"explanation":"Ctrl+Z 撤销上一步操作；Ctrl+N 新建、Ctrl+O 打开、Ctrl+A 全选。故选 C。"},{"id":"design-70","module":"design","title":"内容设计","number":70,"type":"judge","prompt":"PS软件选择\\"椭圆选框\\"工具,按住Shift键,在图像中可以绘制出圆形选区","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"椭圆选框工具按住 Shift 可约束宽高相等，绘制圆形选区。题干正确。"},{"id":"design-71","module":"design","title":"内容设计","number":71,"type":"judge","prompt":"PS软件每个通道都有8bit的色彩信息，即一个0\\\\~255的亮度值色域","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"Photoshop 通道位深可为 8、16 或 32 位，取决于文档设置；并非每个通道都固定 8 bit。题干错误。"},{"id":"design-72","module":"design","title":"内容设计","number":72,"type":"judge","prompt":"UE4关卡编辑器是用来构建游戏关卡的最主要的编辑窗口","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"关卡编辑器用于放置 Actor、配置环境并构建游戏地图，是关卡制作的核心窗口。题干正确。"},{"id":"design-73","module":"design","title":"内容设计","number":73,"type":"single","prompt":"下列那种格式不是点云存储格式？","options":[{"key":"A","text":"jpg"},{"key":"B","text":"stl"},{"key":"C","text":"xyz"},{"key":"D","text":"imw"}],"answer":["A","B"],"explanation":"JPG 是图像格式，STL 是三角网格格式，二者都不是点云专用格式；XYZ 和 IMW 可表示点云。单选设置存在两个不符合项。"},{"id":"design-74","module":"design","title":"内容设计","number":74,"type":"judge","prompt":"Maya软件多边形平面的参数高度可以设置多边形平面的高度值。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"多边形平面的高度参数控制平面在高度方向的尺寸。题干正确。"},{"id":"design-75","module":"design","title":"内容设计","number":75,"type":"judge","prompt":"使用背景材质常用参数中的反射率是控制该材质的反射程度。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"背景材质的反射率控制材质中背景反射效果的强弱。题干对该参数作用的概括正确。"},{"id":"design-76","module":"design","title":"内容设计","number":76,"type":"judge","prompt":"Maya软件多边形管道的参数半径可以设置多边形管道的半径大小。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"多边形管道的 Radius 参数控制其外侧半径大小。题干正确。"},{"id":"design-77","module":"design","title":"内容设计","number":77,"type":"judge","prompt":"UE4静态网格体缓存在视频存储器中，因此可以对它们进行平移、旋转和缩放，但不能为其顶点设置动画","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Static Mesh 是静态顶点数据并驻留于 GPU 渲染流程中，Actor 变换可以平移/旋转/缩放，但不能逐帧改变其顶点。要做变形动画需使用骨骼网格或其他方案。"},{"id":"design-78","module":"design","title":"内容设计","number":78,"type":"judge","prompt":"使用背景材质常用参数中的阴影遮罩是确定材质阴影遮罩的密度。如果更改此值，阴影遮罩将变暗或变亮","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"阴影遮罩参数控制阴影在背景材质上的遮罩浓度，调整后会改变阴影显示的明暗。题干正确。"},{"id":"design-79","module":"design","title":"内容设计","number":79,"type":"judge","prompt":"PS软件\\"矩形选框\\"工具羽化是用于设定选区边界的羽化程度","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"羽化为选区边缘设置渐变过渡宽度，可避免硬边选区。题干描述正确。"},{"id":"design-80","module":"design","title":"内容设计","number":80,"type":"single","prompt":"关于VR全景相机按结构不同可分为的类型描述错误的是？","options":[{"key":"A","text":"双目VR全景相机"},{"key":"B","text":"组合式VR全景相机"},{"key":"C","text":"多目全景相机"},{"key":"D","text":"数码相机"}],"answer":["D"],"explanation":"VR 全景相机分类可按镜头/摄像头组合结构分为双目、多目或组合式等；普通数码相机不是此分类中的 VR 全景相机类型。故选 D。"},{"id":"design-81","module":"design","title":"内容设计","number":81,"type":"single","prompt":"三维重建是将三维的物体在()中重建出来","options":[{"key":"A","text":"点云数据"},{"key":"B","text":"虚拟世界"},{"key":"C","text":"扫描仪"},{"key":"D","text":"现实世界"}],"answer":["B"],"explanation":"三维重建把采集和计算得到的空间信息组织成虚拟场景或模型。扫描仪是数据采集设备，点云是数据表示形式，不是最终重建空间。"},{"id":"design-82","module":"design","title":"内容设计","number":82,"type":"single","prompt":"hongE材质在\\"镜面反射着色\\"卷展栏中的粗糙度是()","options":[{"key":"A","text":"控制材质反射物体的程度"},{"key":"B","text":"控制镜面反射度的焦点"},{"key":"C","text":"控制镜面反射高光的颜色"},{"key":"D","text":"控制镜面反射高光的数量"}],"answer":["B"],"explanation":"粗糙度影响镜面反射高光的扩散/聚焦程度；它控制高光形状的宽窄。颜色和反射强度由其他材质参数决定。"},{"id":"design-83","module":"design","title":"内容设计","number":83,"type":"judge","prompt":"UE4静态网格体导入后，可以手动为它创建LOD，这样可以得到最好的结果","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"静态网格体可在 UE 中设置或导入多个 LOD，也可手工创建；手工制作通常能针对资产优化效果。题干正确。"},{"id":"design-84","module":"design","title":"内容设计","number":84,"type":"judge","prompt":"Maya软件多边形球体的轴向细分数可以设置多边形球体高度上的细分段数","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"多边形球体的轴向细分数控制绕球体轴线的横向/经线分段密度，而高度/极向细分由另一参数控制。题干称其设置高度方向，需按 Maya 参数界面定义核对；此处题目术语可能混用。"},{"id":"design-85","module":"design","title":"内容设计","number":85,"type":"judge","prompt":"材质的本质是一个能够描述物体显示外观数据集，主要功能就是给渲染器提供数据和光照算法","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"材质是一组描述表面外观的参数，渲染器依据材质和光照计算最终外观。题干概述基本正确。"},{"id":"design-86","module":"design","title":"内容设计","number":86,"type":"judge","prompt":"UE4材质编辑器中可以按住2键,然后在编辑器的图中单击左键，会出现Texture Sample节点","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"UE 材质编辑器按 2 并单击创建 Constant2Vector（二维向量）节点，不是 Texture Sample。创建纹理采样节点使用 T。"},{"id":"design-87","module":"design","title":"内容设计","number":87,"type":"single","prompt":"下面哪个不属于UE4新建目录的步骤？ 目录\\"","options":[{"key":"A","text":"选择新建目录New Folder并在\\"/Game\\"之下创建完成新建目录"},{"key":"B","text":"单击新建项目New Project的分页，单击蓝图Blueprint分页并选择空项目Blank"},{"key":"C","text":"\\"创建的目录命名为\\"Quick Start Content\\"，双击打开\\"QuickStart Content\\""},{"key":"D","text":"在编辑器的内容管理器中,单击添加或导入(Add/Import)按钮"}],"answer":["B"],"explanation":"新建目录通常在内容浏览器中使用 Add/Import 或 New Folder 完成；创建 Blank 项目属于新建项目流程，不是目录创建步骤。故选 B。"},{"id":"design-88","module":"design","title":"内容设计","number":88,"type":"judge","prompt":"扫描仪测站设置原则是相邻两站之间有不少于1个可清晰识别标靶或特别标志","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"测站之间通常需要多个可识别的公共标靶/特征点以便配准，仅一个公共标靶不足以可靠确定空间变换。题干把数量降为一个，错误。"},{"id":"design-89","module":"design","title":"内容设计","number":89,"type":"judge","prompt":"UE4材质编辑器中，按住\\"1\\"键并用左键单击图来创建1个Constant 3 Vector节点","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"UE 材质编辑器按 1 并单击创建单值 Constant 节点；按 3 创建 Constant3Vector。题干把快捷键和节点维数弄错。"},{"id":"design-90","module":"design","title":"内容设计","number":90,"type":"single","prompt":"关于管理美术资源和关卡设计在性能优化方面说法错误的是？","options":[{"key":"A","text":"按照需要，尽量限制光照的衰减半径以及光锥的角度"},{"key":"B","text":"IES profiles具有额外性能开销(实际开销取决于材质)，并能防止灯光被渲染成 Tiled Light"},{"key":"C","text":"Skybox Textures都能用来代替实际的几何体物件并有效的提高性能"},{"key":"D","text":"将遮蔽裁剪纳入考虑优化关卡(添加一些阻挡视线的物件来提高性能)"}],"answer":["B"],"explanation":"IES 配置会增加一定照明开销，其与 Tiled Light 的关系也并非“防止灯光被渲染成 Tiled Light”。A、C、D是合理的优化建议，因此 B 是错误项。"},{"id":"design-91","module":"design","title":"内容设计","number":91,"type":"single","prompt":"下面关于UE4虚拟摄像机Actor的细节面板描述错误的是？","options":[{"key":"A","text":"Lens Flares是模拟因摄像机镜头瑕疵导致观看明亮物体时出现的光线散射"},{"key":"B","text":"Light Propagation Volume是可实现实时全局光照(GI)"},{"key":"C","text":"Misc是应用可融合效果和抗锯齿等设定"},{"key":"D","text":"Depth Of Field是提供的图像来给场景照明"}],"answer":["D"],"explanation":"Depth of Field 控制景深和焦内/焦外模糊；用图像为场景照明对应 Ambient Cubemap。D 把两个后处理属性混淆。"},{"id":"design-92","module":"design","title":"内容设计","number":92,"type":"judge","prompt":"Maya软件曲线修改工具中的附加曲线是将两条或两条以上的曲线附加成为一条曲线。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Attach Curves 可把多条曲线连接成一条曲线对象，必要时还可处理连接处连续性。题干正确。"},{"id":"design-93","module":"design","title":"内容设计","number":93,"type":"single","prompt":"材质软件的节点不包括哪个？","options":[{"key":"A","text":"渲染节点"},{"key":"B","text":"贴图节点"},{"key":"C","text":"颜色节点"},{"key":"D","text":"灯光节点"}],"answer":["C"],"explanation":"材质网络常见节点分类包括渲染节点、贴图节点、灯光节点等；“颜色节点”不是与这些并列的标准节点大类。故选 C。"},{"id":"design-94","module":"design","title":"内容设计","number":94,"type":"judge","prompt":"使用背景材质常用参数中的反射限制是控制材质反射的距离。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"反射限制用于限制背景材质可显示的反射距离/范围。题干正确。"},{"id":"design-95","module":"design","title":"内容设计","number":95,"type":"judge","prompt":"用于Photoshop软件可以使用PSD、PDD、TIF格式","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"PSD、PDD 和 TIFF 均可保存 Photoshop 图像；PSD/PDD尤其支持图层、蒙版等编辑信息。题干正确。"},{"id":"design-96","module":"design","title":"内容设计","number":96,"type":"single","prompt":"下面关于Maya软件\\"建模工具包\\"中的多边形编辑工具的说法错误的有？","options":[{"key":"A","text":"连接是可以对多边形网格的顶点进行切角处理，或使其边成为圆形边"},{"key":"B","text":"目标焊接是合并顶点或边，以在它们之间创建共享顶点或边。只能在组件属于同一网格时进行合并"},{"key":"C","text":"四边形绘制是以自然而有机的方式建模，使用简化的单工具工作流重新拓扑化网格"},{"key":"D","text":"多切割是对循环边进行切割、切片和插入操作"}],"answer":["A"],"explanation":"连接工具是在组件之间创建边，不是对顶点切角或让边变圆；该功能属于倒角。故错误项 A。"},{"id":"design-97","module":"design","title":"内容设计","number":97,"type":"judge","prompt":"材质的通用属性\\"镜面反射着色\\"镜面反射衰减是指该参数用于控制高光的强度，数值越小，高光就越强。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"镜面反射衰减值越小，高光衰减越弱、强度越明显。题干对该属性作用的描述正确。"},{"id":"design-98","module":"design","title":"内容设计","number":98,"type":"judge","prompt":"Maya软件\\"建模工具包\\"中的桥接是可用于在现有多边形网格上的两组面或边之间创建桥接","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"桥接可在同一网格上两组开放边界或面之间生成连接几何。题干正确。"},{"id":"design-99","module":"design","title":"内容设计","number":99,"type":"single","prompt":"下面哪个不属于UE4导入网格物体的步骤？","options":[{"key":"A","text":"单击\\"导入\\"或者\\"导入所有\\"来将网格物体模型导入项目中"},{"key":"B","text":"单击Add/Import按钮并选择弹出内容的Import to按钮"},{"key":"C","text":"单击保存全部(Save All)的按钮来保存刚刚导入的网格物体模型"},{"key":"D","text":"选择新建目录New Folder并在\\"/Game\\"之下创建新建目录"}],"answer":["B"],"explanation":"Add/Import 中的 Import to 不是导入网格物体的标准按钮序列；其余新建目录、导入/导入全部、保存项目资产符合流程。故选 B。"},{"id":"design-100","module":"design","title":"内容设计","number":100,"type":"judge","prompt":"Maya软件曲面修改工具中的挤出是可以根据选择的曲线来挤出模型。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"曲面挤出可沿选定曲线生成曲面，曲线充当挤出路径或截面。题干正确。"},{"id":"design-101","module":"design","title":"内容设计","number":101,"type":"judge","prompt":"PSD格式和PDD格式能够保存图像数据的细节部分,如图层、附加的蒙版通道等图像特殊处理的信息","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"PSD/PDD 可保留图层、蒙版、通道等编辑结构，而非只保存展平像素。题干正确。"},{"id":"design-102","module":"design","title":"内容设计","number":102,"type":"single","prompt":"下面关于UE4静态网格体LOD设置描述错误的是？","options":[{"key":"A","text":"完整细节的基础网格体和最低细节的LOD网格体应该全部对齐"},{"key":"B","text":"低细节网格体必须指定完全不同的材质"},{"key":"C","text":"每个LOD网格体可以指定完全不同的材质，包括不同数量的材质"},{"key":"D","text":"完整细节的基础网格体和最低细节的LOD网格体应该拥有相同的枢轴点且占有相同空间"}],"answer":["B"],"explanation":"LOD 应保持与基础网格一致的空间范围和枢轴，以便切换时不跳动；材质槽可不同但不要求完全不同。B 的“必须不同”错误。"},{"id":"design-103","module":"design","title":"内容设计","number":103,"type":"single","prompt":"关于管理美术资源和关卡设计在性能优化方面说法错误的是？","options":[{"key":"A","text":"较大的模型可以分为多个，以获得更好的裁剪优化"},{"key":"B","text":"如果一个贴图可以在较小的比例下被用到，应一直都为它采用mipmaps，可以避免因为贴图缓存的未命中导致的性能下降"},{"key":"C","text":"越大的贴图格式能带来更快的材质"},{"key":"D","text":"区域光照源会更费一些，应当在可能的情形下避免使用"}],"answer":["C"],"explanation":"更大的贴图会占用更多内存带宽和缓存，不能因此更快。Mipmaps、控制光照及合理拆分模型都可用于优化，因此错误项 C。"},{"id":"design-104","module":"design","title":"内容设计","number":104,"type":"judge","prompt":"PS软件CMYK代表了印刷中常用的4种油墨颜色是C代表青色,M代表洋红色,Y代表黄色,K代表黑色","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"CMYK 分别代表 Cyan 青、Magenta 洋红、Yellow 黄、Key 黑，是印刷常见减色模型。题干正确。"},{"id":"design-105","module":"design","title":"内容设计","number":105,"type":"single","prompt":"通过()和点云处理可以得到精准的模型表面信息","options":[{"key":"A","text":"三维重建"},{"key":"B","text":"VR全景相机"},{"key":"C","text":"VR全景视频"},{"key":"D","text":"二维重建"}],"answer":["A"],"explanation":"三维重建结合点云处理，可从扫描数据恢复物体表面和几何结构。全景图/视频记录外观，但不直接构成精确几何表面。"},{"id":"design-106","module":"design","title":"内容设计","number":106,"type":"judge","prompt":"Maya软件多边形球体的高度细分数可以设置多边形球体高度上的细分段数","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"多边形球体的高度细分数控制极轴方向（纬向）的分段数量。题干正确。"},{"id":"design-107","module":"design","title":"内容设计","number":107,"type":"judge","prompt":"用于网络图像可以使用GIF、JPEG、PNG格式","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"GIF、JPEG 和 PNG 是常见网络图像格式，分别适用于有限色动画/图形、有损照片压缩和无损图像。题干正确。"},{"id":"design-108","module":"design","title":"内容设计","number":108,"type":"single","prompt":"纹理的通用属性中的颜色增益是该参数用于()","options":[{"key":"A","text":"控制纹理颜色输出的强度"},{"key":"B","text":"控制纹理颜色"},{"key":"C","text":"控制纹理节点的曝光值"},{"key":"D","text":"控制纹理颜色输出的位移"}],"answer":["A"],"explanation":"Color Gain 是纹理颜色输出的乘法增益，可整体增强或减弱颜色强度，尤其改变亮部输出。它不是改变纹理类型或位移的参数。"},{"id":"design-109","module":"design","title":"内容设计","number":109,"type":"judge","prompt":"Maya软件曲面修改工具中的雕刻几何体工具是可以使用笔刷绘制的方式来在曲面模型上进行雕刻操作","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"雕刻几何体工具用笔刷式交互推拉、平滑曲面上的区域，便于进行有机形态修改。题干正确。"},{"id":"design-110","module":"design","title":"内容设计","number":110,"type":"single","prompt":"下列关于Faro scene软件功能说法错误的是？","options":[{"key":"A","text":"Faro scene可以以*.fbx格式导出和导入带纹理网格的三维模型"},{"key":"B","text":"Faro scene扩展了传统的扫描仪HDR功能"},{"key":"C","text":"Faro scene是一款三维数字存档软件"},{"key":"D","text":"Faro scene可以从低分辨率扫描中输出高分辨率"}],"answer":["D"],"explanation":"FARO SCENE 可处理和优化扫描数据，但不能凭低分辨率原始扫描恢复不存在的高频细节并输出真实高分辨率数据。D 所述能力不成立。"},{"id":"design-111","module":"design","title":"内容设计","number":111,"type":"single","prompt":"下面关于材质的通用属性的含义有误的是？","options":[{"key":"A","text":"颜色是指材质的颜色，默认情况下是HSV模式，也可以切换为RGB模式"},{"key":"B","text":"环境色是指该参数用于控制对象受周围环境的影响，默认情况下为黑色"},{"key":"C","text":"白炽度是指用于模拟物体的自发光效果，也会照亮其他的物体"},{"key":"D","text":"透明度是指该参数用来控制物体的透明度，默认情况下是完全不透明"}],"answer":["C"],"explanation":"白炽度/自发光让材质自身显亮，但通常不会像实际光源那样照亮其他对象。C 错在“也会照亮其他物体”。"},{"id":"design-112","module":"design","title":"内容设计","number":112,"type":"single","prompt":"下面关于PS软件选择\\"磁性套索\\"工具属性栏描述错误的是？","options":[{"key":"A","text":"宽度是用于设定套索检测范围,磁性套索工具将在这个范围内选取反差最大的边缘"},{"key":"B","text":"对比度是用于设定选取边缘的灵敏度,数值越大,则要求边缘与背景的反差越大"},{"key":"C","text":"频率是用于设定选区点的速率"},{"key":"D","text":"频率数值越大,标记速率越慢,标记点越少"}],"answer":["D"],"explanation":"磁性套索频率越高，工具沿边缘放置锚点越频繁、点越多；D 说反了。宽度和对比度则控制检测范围和边缘灵敏度。"},{"id":"design-113","module":"design","title":"内容设计","number":113,"type":"judge","prompt":"Maya软件\\"建模工具包\\"中的多切割是对循环边进行切割、切片和插入操作","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"多切割工具可沿网格创建切线、切面和插入边环，题干描述正确。原题 A 为错误、B 为正确，因此答案字母为 B。"},{"id":"design-114","module":"design","title":"内容设计","number":114,"type":"single","prompt":"下面多边形类型中\\"几何体\\"选项卡中\\"挤出\\"卷展栏的参数描述有误的是？","options":[{"key":"A","text":"\\"挤出\\"卷展栏挤出距离是控制挤出多边形的距离"},{"key":"B","text":"\\"挤出\\"卷展栏捕捉到栅格，当启用时，\\"挤出剖面曲线\\"中的控制点捕捉到经过的图形点"},{"key":"C","text":"\\"挤出\\"卷展栏启用挤出，当启用时，文字向前挤出以增加深度，否则保持为平面"},{"key":"D","text":"\\"挤出\\"卷展栏轮廓，该软件为用户提供了6个预设的图形来控制挤出的形状"}],"answer":["B"],"explanation":"挤出距离控制长度；捕捉到栅格约束轮廓控制点；挤出开关控制文字深度；轮廓预设数目为课程版本所述。B 对“捕捉点”的描述混淆栅格与图形点，因此错误。"},{"id":"design-115","module":"design","title":"内容设计","number":115,"type":"judge","prompt":"Maya软件\\"建模工具包\\"中的挤出是可以从现有面、边或顶点挤出新的多边形","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"挤出可从多边形面、边等组件生成新几何并延展形状。题干正确。"},{"id":"design-116","module":"design","title":"内容设计","number":116,"type":"single","prompt":"下面关于UE4媒体播放编辑器理解错误的是？","options":[{"key":"A","text":"UE4媒体播放编辑器能够在这个编辑器中查看媒体的信息,以及使用标准回放的控制来查看该媒体内容"},{"key":"B","text":"UE4媒体播放编辑器在该软件中播放来自媒体的文件或者其他URL地址的源媒体"},{"key":"C","text":"UE4媒体播放编辑器可以用于定义媒体文件回放时的设置"},{"key":"D","text":"UE4媒体播放编辑器是能够在这个编辑器中编辑媒体文件"}],"answer":["D"],"explanation":"Media Player 负责播放与预览媒体、显示媒体信息和配置播放设置，不是用来编辑源媒体文件内容。D 错。"},{"id":"design-117","module":"design","title":"内容设计","number":117,"type":"judge","prompt":"PS软件亮度是色彩的明亮程度,最大亮度是色彩最鲜明的状态,黑色的亮度为0","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"亮度表示明暗程度；在 HSB 中最大亮度接近白，而不是“色彩最鲜明”。黑色亮度为 0 的部分正确，但整体陈述错误。"},{"id":"design-118","module":"design","title":"内容设计","number":118,"type":"judge","prompt":"UE4导入LOD时，导入网格体的命名可以不遵循默认的命名规则","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"UE 导入 LOD 通常要求按基础网格名加 `_LOD` 编号命名（如 `_LOD0`、`_LOD1`），以便正确识别关联。题干说可不遵循规则，错误。"},{"id":"design-119","module":"design","title":"内容设计","number":119,"type":"single","prompt":"Photoshop软件工作界面主要有哪些功能组成？","options":[{"key":"A","text":"菜单栏、工具箱、状态栏、控制面板组成"},{"key":"B","text":"菜单栏、工具箱、属性栏、状态栏和控制面板组成"},{"key":"C","text":"菜单栏、工具箱、属性栏、控制面板组成"},{"key":"D","text":"菜单栏、属性栏、状态栏、控制面板组成"}],"answer":["B"],"explanation":"Photoshop 界面主要组成包括菜单栏、工具箱、属性/选项栏、状态栏和控制面板。B 列举最完整。"},{"id":"design-120","module":"design","title":"内容设计","number":120,"type":"judge","prompt":"PS软件当软件正在进行图像处理时,按Ese键即可中断正在进行的操作","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Esc 常用于取消或中断当前可取消的操作/变换。题干在一般图像操作场景下正确。"},{"id":"design-121","module":"design","title":"内容设计","number":121,"type":"judge","prompt":"静态光照最慢，固定光照稍快一些，动态光照最快","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"静态光照可预计算，运行时开销通常最低；固定光照居中，动态光照实时计算开销最高。题干把快慢顺序完全颠倒。"},{"id":"design-122","module":"design","title":"内容设计","number":122,"type":"judge","prompt":"Maya软件多边形类型中\\"文本\\"选项卡参数的空间宽度比例是调整手动空间的宽度","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"文本参数中的前导比例用于按比例调整多行文字行间距。题干将其描述为文字行之间的垂直间距，正确。"},{"id":"design-123","module":"design","title":"内容设计","number":123,"type":"single","prompt":"下面是有关\\"木材\\"纹理参数的描述，其中错误的是？","options":[{"key":"A","text":"纹理扩散是漫反射到填充颜色中的脉络颜色数量"},{"key":"B","text":"脉络宽度是设置大理石上花纹纹理的宽度"},{"key":"C","text":"扩散是控制脉络颜色和填充颜色的混合程度"},{"key":"D","text":"脉络颜色是纹理之间间距的颜色"}],"answer":["D"],"explanation":"脉络颜色决定木纹脉络本身的颜色，不是纹理间距区域的颜色；间隙/填充颜色用于其余区域。故错误项 D。"},{"id":"design-124","module":"design","title":"内容设计","number":124,"type":"judge","prompt":"移动激光扫描系统主要由激光扫描仪和惯性导航系统组成","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"移动激光扫描系统的核心通常包括激光扫描仪和定位/导航单元；题目中把数码相机说成必需的核心组成并不准确。相机可作为附加传感器采集影像。"},{"id":"design-125","module":"design","title":"内容设计","number":125,"type":"judge","prompt":"PS软件选择\\"编辑\\\\>还原\\"命令,或按Ctrl+Z组合键,可以恢复到图像的上一步操作","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Ctrl+Z 或“编辑>还原”可撤销/回到上一步操作。题干正确。"},{"id":"design-126","module":"design","title":"内容设计","number":126,"type":"judge","prompt":"越高的贴图分辨率越快(当放大时)","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"更高贴图分辨率消耗更多显存与带宽，放大时虽较清晰但不会因此更快。题干把清晰度和性能速度混为一谈。"},{"id":"design-127","module":"design","title":"内容设计","number":127,"type":"judge","prompt":"Maya软件多边形立方体的参数分段宽度可以设置多边形立方体的宽度上的分段数量。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"立方体的分段宽度参数控制宽度方向的细分数量。题干正确。"},{"id":"design-128","module":"design","title":"内容设计","number":128,"type":"judge","prompt":"在不需要的地方应该关闭阴影生成，一个个物件的关闭，或者一个个灯光来关闭","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"关闭不必要的投影阴影可减少阴影贴图/阴影渲染开销；可按物体或光源分别配置。题干正确。"},{"id":"design-129","module":"design","title":"内容设计","number":129,"type":"judge","prompt":"PS软件选择\\"钢笔\\"工具,按住Shift键时,暂时将\\"钢笔\\"工具.转换成\\"直接选择\\"工具","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"钢笔工具按住 Ctrl 会暂时启用直接选择工具；Shift 用于约束角度，不能切换为直接选择。题干错误。"},{"id":"design-130","module":"design","title":"内容设计","number":130,"type":"single","prompt":"下面关于UE4虚拟摄像机用法描述错误的是？","options":[{"key":"A","text":"UE4虚拟摄像机不可以使用搜索栏直接查找摄像机Actor"},{"key":"B","text":"UE4虚拟摄像机可以借助摄像机动画(Camera Anim)来创建简短的过场动画"},{"key":"C","text":"UE4虚拟摄像机可以在视角固定的游戏中使用"},{"key":"D","text":"UE4选中某个摄像机Actor后，主3D视口将显示一个\\"画中画\\"视图"}],"answer":["A"],"explanation":"UE4 中可通过搜索栏查找摄像机 Actor，也可用 Camera Anim、固定视角镜头和画中画预览。A 否认搜索功能，故错误项。"},{"id":"design-131","module":"design","title":"内容设计","number":131,"type":"judge","prompt":"Maya软件多边形平面的参数细分宽度可以设置多边形平面的宽度分段数值。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"多边形平面的细分宽度控制宽度方向的段数，而不是高度方向。题干正确。"},{"id":"design-132","module":"design","title":"内容设计","number":132,"type":"judge","prompt":"UE4中Actor可以通过游戏代码(C++或蓝图)来创建(Spawn)及销毁","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Actor 可由 C++ 或蓝图在运行时 Spawn 创建，并可按逻辑销毁。题干正确。"},{"id":"design-133","module":"design","title":"内容设计","number":133,"type":"single","prompt":"下面关于UE4的Project(项目)理解错误的是？","options":[{"key":"A","text":"内容浏览器的层次结构与硬盘中的项目文件夹内不同"},{"key":"B","text":"尽管项目经常是由与其关联的.uproject文件所引用，它们是互存的两个单独文件"},{"key":"C","text":"Project(项目)中包含了所有与其关联的文件和文件夹，可以创建任意数量的不同项目,可以并行地保存并开发它们"},{"key":"D","text":"项目(Project)是保存所有组成单独游戏并与硬盘上的一组目录设置相一致的所有内容和代码的自包含单位"}],"answer":["A"],"explanation":"内容浏览器目录结构与项目磁盘上的 Content 目录对应，并非彼此不同。B、C、D对项目组织的描述基本成立，因此 A 错。"},{"id":"design-134","module":"design","title":"内容设计","number":134,"type":"judge","prompt":"材质的通用属性颜色是指材质的颜色，默认情况下是HSV模式，也可以切换为RGB模式。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Maya 材质颜色输入默认可用 HSV 色彩选择器表达，也可切换 RGB 数值编辑。题干正确。"},{"id":"design-135","module":"design","title":"内容设计","number":135,"type":"single","prompt":"Maya软件多边形平面常用参数中说法错误的是？","options":[{"key":"A","text":"多边形平面的参数宽度可以设置多边形平面的宽度值"},{"key":"B","text":"多边形平面参数分别是宽度、高度、细分宽度、高度细分数"},{"key":"C","text":"多边形平面的参数高度可以设置多边形平面的高度值"},{"key":"D","text":"多边形平面的参数细分宽度可以设置多边形平面的高度分段数值"}],"answer":["D"],"explanation":"细分宽度应设置平面的宽度方向分段，不能设置高度方向。高度细分数才控制高度方向，因此 D 是错误项。"},{"id":"design-136","module":"design","title":"内容设计","number":136,"type":"judge","prompt":"数码相机用于测量点的三维坐标和颜色信息","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"数码相机本身记录图像像素，不会单独直接测得每个点的三维坐标；通常要结合摄影测量、多视图匹配或其他定位数据。题干错误。"},{"id":"design-137","module":"design","title":"内容设计","number":137,"type":"single","prompt":"下面关于UE4虚拟摄像机Actor的细节面板描述错误的是？","options":[{"key":"A","text":"Film应用可融合效果和抗锯齿等设定"},{"key":"B","text":"Auto Player Activation是指定由哪个激活的玩家控制器(如存在)来自动使用此摄像机"},{"key":"C","text":"Depth Of Field是根据在焦点前方或后方的距离对场景应用模糊效果"},{"key":"D","text":"Transform是这部分描述了摄像机在世界中的位置"}],"answer":["A"],"explanation":"Transform 描述摄像机世界位置/旋转/缩放；自动玩家激活属于 Auto Player Activation。A 把 Transform 与自动激活职责混淆。"},{"id":"design-138","module":"design","title":"内容设计","number":138,"type":"single","prompt":"下面关于UE4执行构建过程理解错误的是？","options":[{"key":"A","text":"要想使场景光照正常运行,就需要运行Build(构建)过程"},{"key":"B","text":"虚幻编辑器中的Building(构建)非常简单，只需要选择质量设置并单击构建按钮即可"},{"key":"C","text":"场景中的所有光源都是静态的,并且使用预计算或烘焙光照，但是这个预计算光照还没有进行计算"},{"key":"D","text":"构建所需时间与场景复杂程度和灯光复杂程度基本成反比"}],"answer":["D"],"explanation":"构建时间随场景、灯光和质量复杂度增加而增加，不是成反比。A、B、C描述了预计算光照构建的基本情形，故 D 错。"},{"id":"design-139","module":"design","title":"内容设计","number":139,"type":"single","prompt":"下面关于曲线修改工具用法错误的有？","options":[{"key":"A","text":"插入点是根据曲线上的参数点来为曲线添加一个控制点"},{"key":"B","text":"附加曲线是将两条或两条以上的曲线附加成为多条曲线"},{"key":"C","text":"分离曲线是根据曲线的参数点来断开曲线"},{"key":"D","text":"延伸曲线是选择曲线或曲面上的曲线来延伸该曲线"}],"answer":["B"],"explanation":"附加曲线的目标是把多条曲线附加为一条曲线对象，不是“附加成为多条曲线”。B 的结果描述错误。"},{"id":"design-140","module":"design","title":"内容设计","number":140,"type":"single","prompt":"下面关于Maya软件EP曲线工具描述正确的是？","options":[{"key":"A","text":"EP曲线在\\"编辑点\\"层级中，可以通过更改曲线的编辑点位置来改变曲线的弧度"},{"key":"B","text":"EP曲线常用参数结间距是指定该软件如何将U位置值指定给结"},{"key":"C","text":"EP曲线常用参数曲线次数值越低,曲线越平滑"},{"key":"D","text":"EP曲线在\\"控制顶点\\"层级中,可以通过更改曲线的控制顶点位置来改变曲线的形状"}],"answer":["D"],"explanation":"EP 曲线在 CV 层级移动控制顶点可以改变曲线形状。A 把 CV 与编辑点层级混淆，B描述结点间距，C说次数越低越平滑均不准确。"},{"id":"design-141","module":"design","title":"内容设计","number":141,"type":"single","prompt":"下面关于Maya软件布尔运算用法错误的是？","options":[{"key":"A","text":"Maya软件布尔运算的并集命令不能无缝拼合"},{"key":"B","text":"Maya软件布尔运算的交集，可以保留两个多变性对象的相交部分，但是会去除其余部分"},{"key":"C","text":"Maya软件布尔运算的并集，可以合并两个多边形"},{"key":"D","text":"Maya软件布尔运算的差集，可以将两个多边形对象进行相减运算，以消去对象与其他对象的相交部分，同时也会消去替他对象"}],"answer":["A"],"explanation":"布尔并集可把相交对象合并为一个结果，交集保留重叠部分，差集执行相减。A 说并集不能无缝拼合，与其基本用途相反。"},{"id":"design-142","module":"design","title":"内容设计","number":142,"type":"single","prompt":"阴影贴图生成的性能开销根据造成阴影的物体的()有关","options":[{"key":"A","text":"光照角度"},{"key":"B","text":"光照函数"},{"key":"C","text":"光照阴影"},{"key":"D","text":"光照锥体"}],"answer":["D"],"explanation":"阴影贴图需要覆盖光源能够照到的区域，聚光灯的光锥越大通常需渲染覆盖范围越大。此类题所问的开销因素对应光照锥体。"},{"id":"design-143","module":"design","title":"内容设计","number":143,"type":"single","prompt":"下列关于PhongE材质在\\"镜面反射着色\\"参数含义理解错误的是？","options":[{"key":"A","text":"粗糙度是控制镜面反射度的焦点"},{"key":"B","text":"高光大小是控制镜面反射高光的数量"},{"key":"C","text":"反射率是控制材质反射的颜色"},{"key":"D","text":"白度是控制镜面反射高光的颜色"}],"answer":["B"],"explanation":"高光大小控制高光面积/宽窄，不是高光“数量”。粗糙度、反射率和白度分别影响高光形状、反射量和颜色，因此 B 错。"},{"id":"design-144","module":"design","title":"内容设计","number":144,"type":"judge","prompt":"多边形由顶点、边、面构成","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"多边形网格由顶点定义位置、边连接顶点、面由边围成。三类元素共同构成网格拓扑。"},{"id":"design-145","module":"design","title":"内容设计","number":145,"type":"judge","prompt":"Maya软件多边形管道参数分别为半径、高度、厚度、轴向细分数、高度细分数、端面细分数","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"管道是带内外半径的空心圆柱，历史参数包括半径、高度、厚度以及圆周、高度和端面细分。题干列出的参数符合创建设置。"},{"id":"design-146","module":"design","title":"内容设计","number":146,"type":"judge","prompt":"UE4中Game Mode类负责设置正在运行的游戏的规则","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"GameMode 定义一局游戏的规则、胜负条件和默认 Pawn/控制器等规则。题干正确。"},{"id":"design-147","module":"design","title":"内容设计","number":147,"type":"judge","prompt":"Maya软件曲线修改工具中的曲线编辑工具是使用操纵器来更改所选择的曲线","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"曲线编辑工具通过操纵器交互调整曲线控制点或曲线形状。题干对其用途的描述正确。"},{"id":"design-148","module":"design","title":"内容设计","number":148,"type":"single","prompt":"下面关于UE4虚拟摄像机Actor的细节面板描述错误的是？","options":[{"key":"A","text":"Lens Flares是模拟因摄像机镜头瑕疵导致观看明亮物体时出现的光线散射"},{"key":"B","text":"Activation是决定是否自动启用摄像机"},{"key":"C","text":"Actor是用于在Actor 上放置标签"},{"key":"D","text":"Ambient Occlusion是近似模拟出因吸收造成的光线衰减效果"}],"answer":["D"],"explanation":"Ambient Occlusion 近似模拟环境遮蔽产生的接触阴影，不是光线穿过介质后的衰减。后者更接近吸收/透射效果，故 D 错。"},{"id":"design-149","module":"design","title":"内容设计","number":149,"type":"single","prompt":"下面关于位图与矢量图理解错误的是？","options":[{"key":"A","text":"位图图像像素点越多,图像的分辨率越高"},{"key":"B","text":"矢量图与分辨率有关,可以将它设置为任意大小,其清晰度不会改变"},{"key":"C","text":"矢量图在任何分辨率下显示或打印,都不会损失细节"},{"key":"D","text":"矢量图也叫向量图，它是用一种基于图形的几何特性来描述的图像"}],"answer":["B"],"explanation":"矢量图由路径和几何对象描述，缩放时可重新栅格化而不损失边缘细节；它不依赖固定像素分辨率。B 声称与分辨率有关，错误。"},{"id":"design-150","module":"design","title":"内容设计","number":150,"type":"judge","prompt":"根据移动激光扫描系统和数码相机采集的数据可以得到点云数据","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"移动激光扫描提供空间点，数码相机提供颜色/纹理影像，二者配准后可形成带颜色的点云数据。题干正确。"},{"id":"design-151","module":"design","title":"内容设计","number":151,"type":"judge","prompt":"\\"标准曲面材质\\"命令参数\\"透射\\"卷展栏中的色散系数是指定材质的色散系数，用于描述折射率随波长变化的程度，值越大，色散越多","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"色散描述折射率随光波长变化的程度；色散系数越大，不同波长偏折差异越明显。题干正确。"},{"id":"design-152","module":"design","title":"内容设计","number":152,"type":"single","prompt":"下面关于PS软件\\"矩形选框\\"工具属性栏描述错误的是？","options":[{"key":"A","text":"消除锯齿是用于清除选区边缘的锯齿"},{"key":"B","text":"羽化是用于设置取样范围的大小"},{"key":"C","text":"在属性栏中的\\"样式\\"选项下拉列表中选择\\"固定比例\\"可以绘制固定比例的选区"},{"key":"D","text":"样式是用于选择类型"}],"answer":["B"],"explanation":"羽化控制选区边界的柔和过渡范围，取样范围大小不是它的用途。A、C、D与选框工具选项大致相符，故 B 错。"},{"id":"design-153","module":"design","title":"内容设计","number":153,"type":"judge","prompt":"UE4中Brush(画刷)是用来定义BSP关卡几何体和游戏体积的体积","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"UE4 的 Brush 用于创建 BSP 几何体，也可构成阻挡体积、触发体积等游戏体积。题干正确。"},{"id":"design-154","module":"design","title":"内容设计","number":154,"type":"judge","prompt":"PS软件选择\\"文件\\\\>关闭\\"命令,或按Ctrl+W组合键,即可关闭文件","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Ctrl+W 是关闭当前文档的常见快捷键，等价于文件菜单中的关闭命令。题干正确。"},{"id":"design-155","module":"design","title":"内容设计","number":155,"type":"single","prompt":"测站设置原则是在可视范围内,保证90%以上数据的完整性,站站之间重复率()左右","options":[{"key":"A","text":"10%~20%"},{"key":"B","text":"30%~40%"},{"key":"C","text":"40%~50%"},{"key":"D","text":"20%~30%"}],"answer":["D"],"explanation":"扫描站间需要保留重叠数据用于配准，常用建议值约为 20%至30%。在给定比例中选 D。"},{"id":"design-156","module":"design","title":"内容设计","number":156,"type":"judge","prompt":"材质的通用属性环境色是指该参数用于控制对象受周围环境的影响，默认情况下为黑色","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"环境色/环境光属性用于表现环境对材质颜色的影响，传统材质中默认值常为黑色。题干正确。"},{"id":"design-157","module":"design","title":"内容设计","number":157,"type":"judge","prompt":"VR全景相机通常用来拍摄制作VR全景图和全景视频","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"VR 全景相机通过多镜头或全景光学方案记录周围视野，常用于制作 360 度全景图片和视频。题干正确。"},{"id":"design-158","module":"design","title":"内容设计","number":158,"type":"single","prompt":"材质的通用属性\\"镜面反射着色\\"反射率是指该参数用于()","options":[{"key":"A","text":"控制高光扩散的大小"},{"key":"B","text":"控制反射的颜色"},{"key":"C","text":"控制高光的颜色"},{"key":"D","text":"控制物体反射的强度"}],"answer":["D"],"explanation":"反射率控制材质反射强度或反射量，不负责反射颜色或高光颜色。题干中只有 D 描述了强度。"},{"id":"design-159","module":"design","title":"内容设计","number":159,"type":"single","prompt":"下面关于UE4放置Actor理解错误的是？","options":[{"key":"A","text":"Modes Panel(模式面板)中的Place Mode(放置模式)使你可以放置任何常用的Actors"},{"key":"B","text":"在模式面板中,启用放置模式,单击几何体类别。在模式面板中,可以通过单击盒体几何体Actor并将其放置到关卡中来进行放置该Actor"},{"key":"C","text":"在模式面板中,可以切换到Volumes(视觉效果)类别。放置一个Lightmass重要体积到关卡中"},{"key":"D","text":"Actor是可以放置到关卡中的对象,但是不可以移动及编辑各项Actor"}],"answer":["D"],"explanation":"Actor 可在关卡中放置、移动并编辑其变换或属性。D 否认 Actor 可移动和编辑，故为错误项。"},{"id":"design-160","module":"design","title":"内容设计","number":160,"type":"single","prompt":"Maya软件NURBS圆形常用参数正确的是？","options":[{"key":"A","text":"扫描、半径、次数、分段数"},{"key":"B","text":"扫描、半径、细分数、分段数"},{"key":"C","text":"扫描、半径、次数、跨度数"},{"key":"D","text":"扫描、长度、次数、分段数"}],"answer":["A"],"explanation":"NURBS 圆形的创建参数包括扫描范围、半径、次数/阶数和分段数。B、C、D 把多边形细分、跨度或长度等参数混入。"},{"id":"design-161","module":"design","title":"内容设计","number":161,"type":"judge","prompt":"点云文件中的三维坐标指的是本地坐标系中的坐标","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"点云文件中的坐标通常以文件采用的局部或工程坐标系表达；它们不是天然的地理坐标，需结合坐标参考系转换。按题干的本地坐标表述判断为正确。"},{"id":"design-162","module":"design","title":"内容设计","number":162,"type":"single","prompt":"下列关于材料类型理解错误的是？","options":[{"key":"A","text":"Lambert材质常用来模拟不光滑没有高光的物体，如木头、墙壁等，它没有高光、反射等属性"},{"key":"B","text":"各项异性材质是各向异性材质常用来模拟具有细微凹槽的表面，例如头发、CD光盘等"},{"key":"C","text":"Phone材质能根据材质的透明度控制高光区的效果"},{"key":"D","text":"Blinn材质主要用来模拟金属和玻璃的效果，它具有金属表面和玻璃表面特性"}],"answer":["C"],"explanation":"Phong（题干误写 Phone）材质的透明度控制透明效果，不是用来控制高光区的通用方式。Lambert、各向异性和 Blinn 的用途描述符合常见材质类型。"},{"id":"design-163","module":"design","title":"内容设计","number":163,"type":"judge","prompt":"Phone材质常用于模拟光滑的、表面有光泽的物体，如水和玻璃等，它具有较强的高光","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Phong 材质可呈现明显镜面高光，适合表现较光滑、有光泽的表面。水和玻璃还需适当透明/折射设置，但高光特点正确。"},{"id":"design-164","module":"design","title":"内容设计","number":164,"type":"judge","prompt":"测站设置原则是在可视范围内,保证90%以上数据的完整性,站站之间重复率20%\\\\~30%左右","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"测站安排通常要求较高覆盖率及约 20%至30%重叠，保证相邻站点云可拼接。题干符合本题库给出的常用口径。"},{"id":"design-165","module":"design","title":"内容设计","number":165,"type":"judge","prompt":"测站设置原则是要与扫描对象平面垂直","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"尽量让扫描方向接近目标表面法线，可减少掠射角造成的遮挡和测量误差，并改善表面完整度。题干正确。"},{"id":"design-166","module":"design","title":"内容设计","number":166,"type":"judge","prompt":"Maya软件曲线修改工具中的重建曲线是将选择的曲线上的控制点重新进行排列。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Rebuild Curve 会重新分布曲线参数和控制点，以获得较均匀的曲线结构。它不是简单移动单个点，而是重算曲线表示。"},{"id":"design-167","module":"design","title":"内容设计","number":167,"type":"judge","prompt":"PS软件按Shift+Tab组合键,可以隐藏控制面板;再次按Shift+Tab组合键,可以显示出隐藏的部分","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Shift+Tab 可隐藏或重新显示面板，Tab 通常切换工具箱与面板的整体可见性。题干描述正确。"},{"id":"design-168","module":"design","title":"内容设计","number":168,"type":"single","prompt":"下面关于曲线修改工具用法错误的有？","options":[{"key":"A","text":"偏移曲线是将曲线移动并偏移一些"},{"key":"B","text":"重建曲线是将选择的曲线上的控制点重新进行排列"},{"key":"C","text":"添加点工具是选择要添加点的曲线来进行加点操作"},{"key":"D","text":"曲线编辑工具是使用操纵器来更改所选择的曲线"}],"answer":["C"],"explanation":"Add Points 工具用于在曲线上增加点/编辑点；“选择曲线并加点”的说法基本正确。此题其余描述也近似成立，若按 Maya 具体菜单术语，需核对 C 对应工具名称，单选题可能存在表述不严谨。"},{"id":"design-169","module":"design","title":"内容设计","number":169,"type":"judge","prompt":"VR全景视频没有可交互性","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"全景视频允许用户改变观看方向，但通常不能像实时三维场景那样改变场景对象或行动路径。按题库对“可交互性”的定义，这类视频不具备场景交互。"},{"id":"design-170","module":"design","title":"内容设计","number":170,"type":"judge","prompt":"UE4中Actor是可以放置到关卡中的对象,可以放置、移动及编辑各项Actor","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Actor 是可放入关卡的对象，可在编辑器中放置、移动并修改属性。题干正确。"},{"id":"design-171","module":"design","title":"内容设计","number":171,"type":"single","prompt":"下面列举的多边形类型工具错误的是哪个？","options":[{"key":"A","text":"Maya软件多边形类型的参数在\\"属性编辑器\\"中找到type1选项卡，即可看到\\"多边形类型\\"工具的设置参数"},{"key":"B","text":"Maya软件多边形类型中\\"文本\\"选项卡的对齐参数有\\"类型左对齐\\"、\\"中心类型\\"、\\"类型右对齐\\"3种对齐方式"},{"key":"C","text":"Maya软件多边形类型\\"几何体\\"选项卡中主要有\\"网格设置\\"\\"挤出\\"\\"倒角\\"这3个卷展栏"},{"key":"D","text":"Maya软件\\"多边形类型\\"工具可以创建出各种各样的多边形"}],"answer":["D"],"explanation":"Maya 多边形类型工具可生成文字等特定多边形类型，不是任意类型的通用建模工具。D 对工具能力范围的概括过宽。"},{"id":"design-172","module":"design","title":"内容设计","number":172,"type":"judge","prompt":"PS软件的工具箱可以根据需要在单栏与双栏之间自由切换","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"工具箱顶部的双箭头可切换单列和双列布局，便于调整工作区。题干正确。"},{"id":"design-173","module":"design","title":"内容设计","number":173,"type":"single","prompt":"下面是有关\\"木材\\"纹理参数的描述，其中错误的是？","options":[{"key":"A","text":"年龄是木材的年龄(以年为单位)。该值确定纹理中的层或环形总数，并影响中间层和外层的相对厚度"},{"key":"B","text":"随机度是随机化各个层或环形的厚度"},{"key":"C","text":"扩散是随机化各个层或环形的厚度"},{"key":"D","text":"颗粒对比度是控制漫反射到周围木材颜色的\\"颗粒颜色\\"量"}],"answer":["C"],"explanation":"木纹扩散控制脉络色与填充色的混合程度，不是随机改变环层厚度。随机度才用于随机化各层/环的变化，因此 C 错。"},{"id":"design-174","module":"design","title":"内容设计","number":174,"type":"judge","prompt":"Faro scene可以以*.obj格式导出和导入带纹理网格的三维模型","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"FARO SCENE 可把处理后的网格导出为 OBJ 等常见格式，OBJ 网格可携带材质/纹理关联信息。题干正确。"},{"id":"design-175","module":"design","title":"内容设计","number":175,"type":"single","prompt":"下面关于PS软件的菜单栏描述错误的是？","options":[{"key":"A","text":"\\"3D\\"菜单包含了创建3D模型、编辑3D属性、调整纹理及编辑光线等命令"},{"key":"B","text":"\\"图层\\"菜单包含了各种调整图像中图层的操作命令"},{"key":"C","text":"\\"选择\\"菜单包含了各种关于选区的操作命令"},{"key":"D","text":"\\"文件\\"菜单包含了各种帮助信息"}],"answer":["D"],"explanation":"帮助信息由 Help（帮助）菜单提供；File（文件）菜单主要处理新建、打开、保存、导入导出和打印。D 错。"},{"id":"design-176","module":"design","title":"内容设计","number":176,"type":"single","prompt":"Maya软件多边形球体常用参数不包括哪个？","options":[{"key":"A","text":"半径"},{"key":"B","text":"深度细分数"},{"key":"C","text":"轴向细分数"},{"key":"D","text":"高度细分数"}],"answer":["B"],"explanation":"多边形球体常用参数包括半径、轴向细分和高度细分；“深度细分”不是球体创建参数。故选 B。"},{"id":"design-177","module":"design","title":"内容设计","number":177,"type":"judge","prompt":"扫描仪测站设置原则是相邻两站之间有不少于三个可清晰识别标靶或特别标志","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"相邻扫描站需有多个共同可识别标靶/特征点来进行配准，三处公共控制信息有助于稳定确定空间变换。题干正确。"},{"id":"design-178","module":"design","title":"内容设计","number":178,"type":"single","prompt":"下面关于UE4虚拟摄像机Actor的细节面板描述错误的是？","options":[{"key":"A","text":"Global Illumination是影响光团发出的间接光照，从而改变场景的亮度、颜色或色调"},{"key":"B","text":"Lens Flares是模拟因摄像机镜头瑕疵导致观看明亮物体时出现的光线散射"},{"key":"C","text":"Ambient Cubemap是用提供的图像来给场景照明"},{"key":"D","text":"Bloom是用于对摄像机应用效果"}],"answer":["A"],"explanation":"Global Illumination 是全局光照概念，旧版 UE4 的 Light Propagation Volume 可近似实时 GI；它并非简单描述“光团发出的间接光”。A 的字段解释不准确，选 A。"},{"id":"design-179","module":"design","title":"内容设计","number":179,"type":"judge","prompt":"使用背景材质常用参数中的镜面反射颜色是定义材质的镜面反射颜色。如果更改此颜色或指定其纹理，场景中的反射将显示这些更改。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"镜面反射颜色决定背景材质反射中显示的颜色，直接改色或接入贴图会改变反射观感。题干正确。"},{"id":"design-180","module":"design","title":"内容设计","number":180,"type":"single","prompt":"下面关于UE4标准操作有误的是？","options":[{"key":"A","text":"在透视口中，鼠标左键+鼠标右键+拖动，可以上下移动"},{"key":"B","text":"在正交视口中，使用鼠标左键+拖动，可以平移视口相机"},{"key":"C","text":"在透视口中，使用鼠标左键+拖动，可以前后移动相机，及左右旋转相机"},{"key":"D","text":"在透视口中，鼠标右键+拖动，可以旋转视口相机"}],"answer":["C"],"explanation":"透视视口中左键拖动通常是前后移动并左右旋转；右键拖动旋转，左键加右键可上下移动，正交视口左键拖动可平移。题目问错误项，C 的组合描述与常见 UE4 控制不符。"},{"id":"design-181","module":"design","title":"内容设计","number":181,"type":"single","prompt":"关于VR全景相机描述错误的是？","options":[{"key":"A","text":"VR全景相机通常用来拍摄制作VR全景图和全景视频"},{"key":"B","text":"VR全景视频不具有可交互性"},{"key":"C","text":"VR全景视频通过VR全景相机的拍摄和计算机软件的后期剪辑处理得到的三维空间视频"},{"key":"D","text":"VR全景图是可以360度观看全景图"}],"answer":["C"],"explanation":"VR 全景视频是由全景影像序列拍摄/拼接形成的 360 度视频，不是可自由探索的实时三维空间视频。A、B、D是题库语境下的正确描述。"},{"id":"design-182","module":"design","title":"内容设计","number":182,"type":"single","prompt":"下列关于Phong材质在\\"镜面反射着色\\"参数含义理解正确的是？","options":[{"key":"A","text":"反射的颜色是控制材质反射的颜色"},{"key":"B","text":"镜面反射颜色是控制反射高光的强弱"},{"key":"C","text":"反射率是控制曲面上反射高光的大小"},{"key":"D","text":"余弦幂是控制材质反射物体的程度"}],"answer":["A"],"explanation":"Phong 材质的反射颜色决定环境反射呈现的颜色。高光颜色由镜面反射颜色控制；反射率控制反射强弱；余弦幂控制高光大小，因此选 A。"},{"id":"design-183","module":"design","title":"内容设计","number":183,"type":"single","prompt":"\\"标准曲面材质\\"命令参数\\"涂层\\"卷展栏中的IOR是()","options":[{"key":"A","text":"控制涂层的颜色"},{"key":"B","text":"控制材质涂层的权重值"},{"key":"C","text":"控制镜面反射的光泽度"},{"key":"D","text":"控制材质的菲涅尔反射率"}],"answer":["D"],"explanation":"Coat IOR 控制涂层边界的菲涅尔反射特性，改变观察角度下的反射比例。颜色、权重和粗糙度分别控制颜色、层强度和模糊程度。"},{"id":"design-184","module":"design","title":"内容设计","number":184,"type":"judge","prompt":"Hypershade为材质编辑器，也可称之为超级着色器","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Hypershade 是 Maya 中创建、浏览和编辑材质/着色网络的工作区，中文常称超级着色器或材质编辑器。题干正确。"},{"id":"design-185","module":"design","title":"内容设计","number":185,"type":"single","prompt":"UE4虚拟摄像机Actor的Details面板参数中的Activation是()","options":[{"key":"A","text":"用于将 Actor 变为蓝图"},{"key":"B","text":"用于在 Actor上放置标签"},{"key":"C","text":"决定是否自动启用摄像机"},{"key":"D","text":"摄像机 Actor 本身的相关信息"}],"answer":["C"],"explanation":"Activation 用于确定摄像机是否自动激活/切换为当前视角。标签、蓝图和 Actor 信息分别属于其他属性，故选 C。"},{"id":"design-186","module":"design","title":"内容设计","number":186,"type":"judge","prompt":"较大的模型可以分为多个，以获得更好的裁剪优化","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"把大型模型拆成适当大小的块，能让视锥/遮挡裁剪只处理可见部分，减少无用渲染。拆分需避免过多 Draw Call，题干作为优化方向成立。"},{"id":"design-187","module":"design","title":"内容设计","number":187,"type":"judge","prompt":"UE4按Alt+鼠标左键＋拖动，可以根据鼠标移动的方向将相机向左、右、上、下移动","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"Alt+左键拖动通常绕兴趣点环绕视口；平移一般使用 Alt+中键。题干把环绕操作说成平移，错误。"},{"id":"design-188","module":"design","title":"内容设计","number":188,"type":"single","prompt":"下面关于PS软件的菜单栏描述错误的是？","options":[{"key":"A","text":"\\"文字\\"菜单包含了各种对文字的编辑和调整功能"},{"key":"B","text":"\\"滤镜\\"菜单包含了各种添加滤镜效果的操作命令"},{"key":"C","text":"\\"图像\\"菜单包含了各种改变图像的大小、颜色等的操作命令"},{"key":"D","text":"\\"编辑\\"菜单包含了各种显示或隐藏控制面板的命令"}],"answer":["D"],"explanation":"面板显示与隐藏主要通过“窗口”菜单或工作区设置管理，不是“编辑”菜单的主要功能。D 错。"},{"id":"design-189","module":"design","title":"内容设计","number":189,"type":"single","prompt":"点云是( )的载体","options":[{"key":"A","text":"二维坐标"},{"key":"B","text":"三维数据"},{"key":"C","text":"三维坐标"},{"key":"D","text":"二维数据"}],"answer":["B"],"explanation":"点云是离散空间采样点集合，用来承载物体或场景的三维数据。三维坐标是每个点的重要字段，但不是点云整体的概念答案。"},{"id":"design-190","module":"design","title":"内容设计","number":190,"type":"judge","prompt":"Maya软件曲面修改工具中的平面是可以根据闭合的曲面来生成曲面模型。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"Maya 的平面曲面工具通常通过平面曲线生成曲面，不是由一个闭合曲面再生成曲面模型。题干把输入对象类型说错。"},{"id":"design-191","module":"design","title":"内容设计","number":191,"type":"judge","prompt":"Maya软件\\"建模工具包\\"中的添加分段是可以将选定的多边形组件(边或面)分割为较小的组件","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Add Divisions 可把所选边或面细分为更小组件，增加局部拓扑密度。题干正确。"},{"id":"design-192","module":"design","title":"内容设计","number":192,"type":"judge","prompt":"低分辨率网格体的几何体可用于生成法线贴图的法线","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"法线贴图通常由高分辨率细节烘焙到低分辨率网格上，低模是接收法线贴图的目标，不是生成细节法线的源。题干倒置了高低模角色。"},{"id":"design-193","module":"design","title":"内容设计","number":193,"type":"single","prompt":"Maya软件EP曲线在\\"控制顶点\\"层级中,可以通过更改曲线的控制顶点位置来改变()","options":[{"key":"A","text":"曲线的形状"},{"key":"B","text":"曲线次数"},{"key":"C","text":"绘制曲线"},{"key":"D","text":"曲线的弧度"}],"answer":["A"],"explanation":"移动 EP 曲线的控制顶点会改变曲线形状；次数、曲线绘制和弧度不是这一操作的直接对象。故选 A。"},{"id":"design-194","module":"design","title":"内容设计","number":194,"type":"single","prompt":"三维重建是将二维图片中的信息在()虚拟空间中显现","options":[{"key":"A","text":"三维"},{"key":"B","text":"二维"},{"key":"C","text":"一维"},{"key":"D","text":"四维"}],"answer":["A"],"explanation":"三维重建把二维图片中可恢复的几何/纹理信息放入三维虚拟空间。二维图片只是输入数据，输出目标为三维。"},{"id":"design-195","module":"design","title":"内容设计","number":195,"type":"judge","prompt":"UE4静态网格体编辑器用来对模型的外观、碰撞和UV来做预览,并且能修改静态网格体的一些参数属性","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"静态网格体编辑器能预览模型外观、碰撞和 UV，并提供碰撞、LOD 等资源属性设置。题干正确。"},{"id":"design-196","module":"design","title":"内容设计","number":196,"type":"judge","prompt":"PS软件位图图像像素点越多,图像的分辨率越低","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"像素越多通常代表图像可提供更高空间分辨率或更多细节，而非更低。题干把关系说反。"},{"id":"design-197","module":"design","title":"内容设计","number":197,"type":"judge","prompt":"PS软件HSB模式下红色为0度,绿色为120度,蓝色为240度","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"HSB 色相角常以红 0°、绿 120°、蓝 240°为基准。题干正确。"},{"id":"design-198","module":"design","title":"内容设计","number":198,"type":"judge","prompt":"Maya软件曲线修改工具中的插入点是根据曲线上的参数点来为曲线添加一个控制点。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Insert Knot/Insert Point 一类曲线编辑操作可在指定参数位置插入控制点或结点，改变曲线表示并允许局部调整。题干基本正确。"},{"id":"design-199","module":"design","title":"内容设计","number":199,"type":"judge","prompt":"Maya软件多边形管道的参数厚度可以设置多边形管道的厚度值。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"多边形管道的 Thickness 参数控制管壁厚度，即外半径和内半径之间的差。题干正确。"},{"id":"design-200","module":"design","title":"内容设计","number":200,"type":"single","prompt":"下面关于纹理的通用属性表述错误的是？","options":[{"key":"A","text":"默认颜色是默认的纹理颜色，可以双击色块进行颜色的设置"},{"key":"B","text":"颜色偏移是该参数适用于位移或凹凸纹理，可缩放纹理Alpha输出的系数"},{"key":"C","text":"颜色增益是该参数用于控制纹理颜色输出的强度，可调整纹理中的浅色部分"},{"key":"D","text":"曝光是用于控制纹理节点的曝光值"}],"answer":["B"],"explanation":"颜色偏移改变纹理输出的颜色偏移量，不是缩放 Alpha 输出；控制 Alpha 缩放的是 Alpha Gain。B 混淆了颜色偏移和 Alpha 增益。"},{"id":"design-201","module":"design","title":"内容设计","number":201,"type":"judge","prompt":"区域光照源会更费一些，应当在可能的情形下避免使用。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"区域光源计算更复杂、开销通常更高，应在收益明显时使用。题干的性能建议正确。"},{"id":"design-202","module":"design","title":"内容设计","number":202,"type":"judge","prompt":"按照需要，尽量限制光照的衰减半径以及光锥的角度","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"限制点光源衰减半径和聚光灯光锥，可减少受影响对象及像素范围，降低照明开销。题干正确。"},{"id":"design-203","module":"design","title":"内容设计","number":203,"type":"judge","prompt":"Maya软件NURBS圆形常用参数扫描是用于设置NURBS圆形的弧长范围，最大值为360，73.为一个圆形;较小的值则可以得到一段圆弧","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"NURBS 圆的扫描角度最大为完整 360°；小于 360° 时会得到弧形曲线。题干文字中的“73.”是排版杂字，不影响判断。"},{"id":"design-204","module":"design","title":"内容设计","number":204,"type":"judge","prompt":"移动激光扫描系统主要由激光扫描仪和数码相机组成","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"移动激光扫描系统的核心是激光扫描仪与定位/惯导系统；数码相机可作为影像采集模块，但并非必需的基本组成。按题库分类应判错误。"},{"id":"design-205","module":"design","title":"内容设计","number":205,"type":"judge","prompt":"PS软件鼠标左键长按工具或鼠标右键单击工具,可弹出隐藏工具选项","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"长按工具组图标或右键单击工具，可展开同组隐藏工具。题干正确。"},{"id":"design-206","module":"design","title":"内容设计","number":206,"type":"judge","prompt":"PS软件Lab模式中的a通道是色相，包括的颜色值从深绿到灰,再到亮粉红色","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Lab 的 a 轴从绿色负值经过灰色中性到红/品红正值，题干的颜色方向描述基本正确。需注意它是色度轴而不是色相通道。"},{"id":"design-207","module":"design","title":"内容设计","number":207,"type":"judge","prompt":"Maya软件多边形平面的参数宽度可以设置多边形平面的宽度值。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"多边形平面的宽度参数控制平面横向尺寸。题干正确。"},{"id":"design-208","module":"design","title":"内容设计","number":208,"type":"single","prompt":"关于管理美术资源和关卡设计在性能优化方面说法错误的是？","options":[{"key":"A","text":"最小化每个物体的元素数量"},{"key":"B","text":"不透明的材质性能最慢，因为有多次渲染的开销，蒙版会稍快一些，半透明则最快，因为有最佳的ZBuffer裁剪"},{"key":"C","text":"模型合并，形成单个元素上有一定数量的三角面(比如每个元素300+个三角面)"},{"key":"D","text":"限制UV裂缝和模型硬边的数量，因为它们会导致硬件计算时更多的顶点数据"}],"answer":["B"],"explanation":"性能排序应为不透明通常最快、蒙版有额外裁剪/测试开销、半透明常最贵；后者常需排序或额外混合。B 将快慢关系反写，故错误。"},{"id":"design-209","module":"design","title":"内容设计","number":209,"type":"judge","prompt":"PS软件HSB模式只有在颜色吸取窗口中才会出现。H代表色相,S代表饱和度,B代表亮度","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Photoshop 不把 HSB 作为可直接保存的文档颜色模式，但颜色选取器中可按 HSB 数值选色。题干所指“HSB模式”是选色界面中的模型，判断正确。"},{"id":"design-210","module":"design","title":"内容设计","number":210,"type":"judge","prompt":"PS软件\\"矩形选框\\"工具消除锯齿是用于清除选区边缘的锯齿","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"消除锯齿会平滑选区边缘的阶梯状锯齿，常用于椭圆/多边形选区。题干正确。"},{"id":"design-211","module":"design","title":"内容设计","number":211,"type":"judge","prompt":"UE4在材质编辑器中,可以新建(或者编辑已经存在的)材质,这些材质能够被应用于一个模型来控制模型的可见外观","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"UE 材质定义模型表面的颜色、粗糙度、透明等可见属性，并通过材质实例/材质应用到网格体。题干正确。"},{"id":"design-212","module":"design","title":"内容设计","number":212,"type":"single","prompt":"下面关于PS软件的工具使用快捷键错误的是？","options":[{"key":"A","text":"反复按Shift+M组合键可以使用矩形选框工具"},{"key":"B","text":"当软件正在进行图像处理时,按Ese键即可中断正在进行的操作"},{"key":"C","text":"按Ctrl+Z组合键,可以恢复到图像的上一步操作"},{"key":"D","text":"按M键，可以使用移动工具"}],"answer":["D"],"explanation":"移动工具快捷键为 V；M 是矩形/椭圆选框工具组快捷键。其他快捷键描述成立，因此错误项 D。"},{"id":"design-213","module":"design","title":"内容设计","number":213,"type":"single","prompt":"下列哪个不属于点云数据？","options":[{"key":"A","text":"颜色信息"},{"key":"B","text":"二维图片"},{"key":"C","text":"三维坐标"},{"key":"D","text":"激光反射强度"}],"answer":["B"],"explanation":"点云包含三维坐标及可选颜色、强度等字段；普通二维图片不是点云数据结构。选 B。"},{"id":"design-214","module":"design","title":"内容设计","number":214,"type":"judge","prompt":"Maya软件多边形球体常用参数分别有半径、半径细分数、高度细分数","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"多边形球体常用的是轴向细分数和高度细分数，不是“半径细分数”。题干参数名称错误。"},{"id":"design-215","module":"design","title":"内容设计","number":215,"type":"judge","prompt":"UE4 Game Mode类负责设置正在运行的游戏的规则","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"GameMode 管理一局游戏规则和默认游戏框架类。题干正确。"},{"id":"design-216","module":"design","title":"内容设计","number":216,"type":"judge","prompt":"UE4媒体播放编辑器能够在这个编辑器中编辑媒体文件","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"媒体播放编辑器用于查看、播放和配置媒体资源，并不直接编辑源视频/媒体文件。题干错误。"},{"id":"design-217","module":"design","title":"内容设计","number":217,"type":"single","prompt":"下面关于曲面修改工具用法描述错误的是？","options":[{"key":"A","text":"曲面修改工具中的挤出是可以根据选择的曲线来挤出模型"},{"key":"B","text":"曲面修改工具中的放样是可以根据选择的多条曲线来放样生成曲面模型"},{"key":"C","text":"曲面修改工具中的旋转是可以根据选择的曲线来旋转生成一个旋转模型"},{"key":"D","text":"曲面修改工具中的平面是可以根据闭合的曲面来生成曲面模型"}],"answer":["D"],"explanation":"曲面平面工具根据闭合曲线（通常为平面边界曲线）生成平面曲面，不是从“闭合曲面”生成另一个曲面。D 输入对象描述错误。"},{"id":"design-218","module":"design","title":"内容设计","number":218,"type":"single","prompt":"点云文件中的三维坐标指的是本地坐标系中的坐标","options":[{"key":"A","text":"外地坐标系"},{"key":"B","text":"本地坐标系"},{"key":"C","text":"三维坐标系"},{"key":"D","text":"二维坐标系"}],"answer":["B"],"explanation":"文件存储的 XYZ 坐标通常是当前数据集采用的本地坐标；若要转到地理/工程坐标需已知参考系和变换。选本地坐标系 B。"},{"id":"design-219","module":"design","title":"内容设计","number":219,"type":"single","prompt":"下面关于PS软件灰度模式描述错误的是？","options":[{"key":"A","text":"灰度模式中每个像素用8个二进制位表示,能产生256级灰色调"},{"key":"B","text":"灰度模式的灰度图又叫8bit深度图"},{"key":"C","text":"灰度模式的图像只有明暗值和饱和度这两种颜色信息,没有色相"},{"key":"D","text":"当一个彩色文件被转换为灰度模式文件时,所有的颜色信息都将丢失"}],"answer":["C"],"explanation":"灰度图每像素记录明暗值，没有色相或饱和度；它并不包含“明暗值和饱和度”两类颜色信息。C 错。"},{"id":"design-220","module":"design","title":"内容设计","number":220,"type":"judge","prompt":"Maya软件多边形圆柱体的参数高度细分数可以设置多边形圆柱体的高度分段数值。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"管道高度细分数控制圆柱轴向分段。该参数改变纵向面数，不改变高度总尺寸。"},{"id":"design-221","module":"design","title":"内容设计","number":221,"type":"single","prompt":"关于管理美术资源和关卡设计在性能优化方面说法错误的是？","options":[{"key":"A","text":"按照需要，尽量限制光照的衰减半径以及光锥的角度"},{"key":"B","text":"较多shader指令数的材质及贴图能运行的更快"},{"key":"C","text":"根据较小的物体来调整渲染距离，来达到更好的裁剪效果"},{"key":"D","text":"着色模式本身具有一定的性能开销:无光模式最快，光照模式应该在大部分情况下使用。"}],"answer":["B"],"explanation":"指令更多的着色器通常更耗时，不会让材质运行更快。限制光照范围、合理裁剪和选择合适着色模式都是优化措施。"},{"id":"design-222","module":"design","title":"内容设计","number":222,"type":"single","prompt":"下面关于UE4虚拟摄像机Actor的细节面板描述错误的是？","options":[{"key":"A","text":"Auto Exposure是模拟因摄像机镜头瑕疵导致观看明亮物体时出现的光线散射"},{"key":"B","text":"Film是在这部分中，你可以应用胶片效果，如色调、饱和度或对比度"},{"key":"C","text":"Scene Color是用于对摄像机应用效果"},{"key":"D","text":"Transform是这部分描述了摄像机在世界中的位置"}],"answer":["A"],"explanation":"Auto Exposure 是自动曝光/眼睛适应明暗，不是镜头瑕疵产生的光线散射；后者是 Lens Flare。A 错。"},{"id":"design-223","module":"design","title":"内容设计","number":223,"type":"single","prompt":"下面关于PS软件常用的文件格式描述正确的是？","options":[{"key":"A","text":"PSD格式和PDD格式能够保存图像数据的细节部分,如图层、附加的蒙版通道等图像特殊处理的信息"},{"key":"B","text":"GIF格式的图像文件容量非常大,它形成一种压缩的8bit图像文件"},{"key":"C","text":"TIF格式是标签图像格式。TIF格式对于色彩通道图像来说是最有用的格式,具有很强的可移植性"},{"key":"D","text":"PNG格式是用于无损压缩和在Web上显示图像的文件格式"}],"answer":["A","C","D"],"explanation":"PSD/PDD 保留编辑信息，TIFF 常用于高质量通道/印刷流程，PNG 适合无损 Web 图像；B 的“GIF容量非常大”不准确。题干是单选却有多个正确陈述，建议修题。"},{"id":"design-224","module":"design","title":"内容设计","number":224,"type":"single","prompt":"Geomagic Wrap软件功能说法正确的是？","options":[{"key":"A","text":"Geomagic Wrap是一款三维数字存档软件"},{"key":"B","text":"Geomagic Wrap高清面片构建有助于克服缺乏信息或需要大量数据集的扫描"},{"key":"C","text":"Geomagic Wrap不能将3D扫描数据转换为3D模型"},{"key":"D","text":"Geomagic Wrap高清面片构建不可以创建封闭面片"}],"answer":["B"],"explanation":"Geomagic Wrap 可处理扫描数据并重建曲面，高密度面片功能可生成细节较多的封闭模型。A 将其误称为数字存档软件，C、D否认核心能力。"},{"id":"design-225","module":"design","title":"内容设计","number":225,"type":"single","prompt":"Maya软件多边形圆柱体常用参数中说法错误的是？","options":[{"key":"A","text":"Maya软件多边形圆柱体的参数宽度可以设置多变形圆柱的宽度值"},{"key":"B","text":"Maya软件多边形圆柱体的参数端面细分数可以设置多边形圆柱体的端面分段数值"},{"key":"C","text":"Maya软件多边形圆柱体的参数半径可以设置多边形圆柱的半径大小"},{"key":"D","text":"Maya软件多边形圆柱体的参数轴向细分数可以设置多边形圆柱体的轴向分段数值"}],"answer":["A"],"explanation":"圆柱体有半径、高度和细分等参数，但没有“宽度”参数。A 将其他几何体的维度参数套用到圆柱体上。"},{"id":"design-226","module":"design","title":"内容设计","number":226,"type":"judge","prompt":"PS软件黑、白、灰3种色彩没有饱和度","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"黑、白、灰是无彩色，饱和度为零或不适用。题干正确。"},{"id":"design-227","module":"design","title":"内容设计","number":227,"type":"judge","prompt":"VR全景图是可以360度观看全景图","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"全景图可通过拖动视点环绕观看，覆盖水平 360° 视野。题干正确。"},{"id":"design-228","module":"design","title":"内容设计","number":228,"type":"judge","prompt":"扫描仪测站设置原则是要与扫描对象平面平行","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"扫描时通常应调整角度以减少掠射和遮挡，不能一概要求扫描仪与对象平面平行；题库原则强调垂直/法向布站。题干错误。"},{"id":"design-229","module":"design","title":"内容设计","number":229,"type":"judge","prompt":"通过三维重建和点云处理可以得到精准的模型表面信息","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"点云提供采样几何，三维重建和去噪、配准等处理可恢复更准确的表面模型。题干正确。"},{"id":"design-230","module":"design","title":"内容设计","number":230,"type":"single","prompt":"Maya软件多边形类型中\\"文本\\"选项卡参数的前导比例是均匀地调整所有线之间的()","options":[{"key":"A","text":"水平问距"},{"key":"B","text":"细分数"},{"key":"C","text":"空间的宽度"},{"key":"D","text":"垂直间距"}],"answer":["D"],"explanation":"Leading Scale 用于调整文字行之间的垂直距离。水平字距由 Tracking/Kerning 控制，故选 D。"},{"id":"design-231","module":"design","title":"内容设计","number":231,"type":"single","prompt":"Faro scene支持的网格格式中错误的是？","options":[{"key":"A","text":"gps"},{"key":"B","text":"obj"},{"key":"C","text":"wrl"},{"key":"D","text":"ply"}],"answer":["A"],"explanation":"FARO SCENE 支持常见网格交换格式如 OBJ、PLY、VRML 等；GPS 是定位系统/数据概念，不是网格文件格式。选 A。"},{"id":"design-232","module":"design","title":"内容设计","number":232,"type":"single","prompt":"下面是有关\\"布料\\"纹理参数的描述，其中错误的是？","options":[{"key":"A","text":"U向宽度/V向宽度是用于设置U向和V向线宽度"},{"key":"B","text":"亮度扩散是用来设置沿着每条线的长度随机化线的宽度"},{"key":"C","text":"U向颜色/V向颜色是设置U向和V向线颜色"},{"key":"D","text":"随机度是用于设置在U方向和V方向的随机涂抹纹理程度"}],"answer":["B"],"explanation":"亮度扩散控制沿线亮度随机变化，不是线宽随机变化；宽度由 U/V 宽度参数控制。B 把亮度和宽度混淆。"},{"id":"design-233","module":"design","title":"内容设计","number":233,"type":"judge","prompt":"Maya软件按住Ctrl键，单击鼠标右键，在弹出的菜单中找到创建多边形对象的相关命令","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"Maya Shift+右键打开多边形建模标记菜单；Ctrl+右键并非创建多边形对象的标准组合。题干错误。"},{"id":"design-234","module":"design","title":"内容设计","number":234,"type":"judge","prompt":"使用背景材质可以将物体渲染成为跟当前场景背景一样的颜色","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Background 材质可让指定对象呈现与渲染背景相协调的颜色，并常用于阴影/反射合成。题干作为基本用途判断正确。"},{"id":"design-235","module":"design","title":"内容设计","number":235,"type":"judge","prompt":"Faro scene可以从低分辨率扫描中输出高分辨率","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"低分辨率扫描无法凭空恢复未采集到的几何细节；软件可插值或网格化，但不等同于真实高分辨率扫描。题干错误。"},{"id":"design-236","module":"design","title":"内容设计","number":236,"type":"single","prompt":"下列那种格式不是点云存储格式？","options":[{"key":"A","text":"pts"},{"key":"B","text":"png"},{"key":"C","text":"asc"},{"key":"D","text":"dat"}],"answer":["B"],"explanation":"PTS、ASC 和 DAT 都可用于点云/测量数据交换；PNG 是栅格图像格式，不是点云格式。选 B。"},{"id":"design-237","module":"design","title":"内容设计","number":237,"type":"judge","prompt":"PS软件灰度模式的灰度图又叫8bit深度图","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"灰度图可按 8、16 或 32 位深度保存，不等同于固定的 8-bit 深度图。题干把常见 8-bit 情况说成定义，错误。"},{"id":"design-238","module":"design","title":"内容设计","number":238,"type":"single","prompt":"下面关于UE4虚拟摄像机Actor的细节面板描述错误的是？","options":[{"key":"A","text":"Ambient Cubemap是用提供的图像来给场景照明"},{"key":"B","text":"Tags是是决定是否自动启用摄像机"},{"key":"C","text":"Scene Color是用于对摄像机应用效果"},{"key":"D","text":"Misc是应用可融合效果和抗锯齿等设定"}],"answer":["B"],"explanation":"Tags 用于分类或查询 Actor，不决定摄像机自动启用；该功能由 Activation 属性控制。故 B 错。"},{"id":"design-239","module":"design","title":"内容设计","number":239,"type":"single","prompt":"下列关于\\"标准曲面材质\\"命令参数\\"涂层\\"参数理解错误的是？","options":[{"key":"A","text":"IOR是控制材质的菲涅尔反射率"},{"key":"B","text":"粗糙度是控制镜面反射的强弱"},{"key":"C","text":"颜色是控制涂层的颜色"},{"key":"D","text":"权重是控制材质涂层的权重值"}],"answer":["B"],"explanation":"涂层粗糙度决定反射高光的模糊程度/清晰度，而非简单决定镜面反射强弱。权重控制涂层量，颜色控制涂层颜色，IOR影响菲涅尔反射。"},{"id":"design-240","module":"design","title":"内容设计","number":240,"type":"judge","prompt":"UE4通过按下\\"W\\"键可以启用旋转工具,进行旋转操作。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"UE4 视口 W 为平移/移动工具，E 为旋转，R 为缩放。题干把 W 说成旋转，错误。"},{"id":"design-241","module":"design","title":"内容设计","number":241,"type":"judge","prompt":"UE4 Level(关卡)是定义的游戏区域,也被称为地图","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Level 是游戏世界中的关卡/地图区域，包含其场景 Actor。题干正确。"},{"id":"design-242","module":"design","title":"内容设计","number":242,"type":"judge","prompt":"PS软件RGB模式是一种加色模式。它通过红、绿、蓝3种色光相叠加而形成更多的颜色","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"RGB 是加色模型，红、绿、蓝光以不同强度叠加产生颜色；三色光同时达到最大时趋近白色。题干正确。"},{"id":"design-243","module":"design","title":"内容设计","number":243,"type":"single","prompt":"下面关于Hypershade面板\\"浏览器\\"选项卡描述错误的是？","options":[{"key":"A","text":"材质和纹理的样例生成是可以该按钮提示用户现在可以启用材质和纹理的样例生成功能"},{"key":"B","text":"图标是可以以列表的方式显示材质球"},{"key":"C","text":"按名称是可以按材质球字母的排序来排列材质球"},{"key":"D","text":"按反转顺序是可以使用此选项可反转排序指定的名称、类型或时间"}],"answer":["A"],"explanation":"Hypershade 浏览器中的样例生成设置控制是否预览材质球，题干 A 的描述缺少准确功能名且表述不完整。其余选项涉及图标列表、排序和反转顺序；本题版本差异较大，建议结合界面核验。"},{"id":"design-244","module":"design","title":"内容设计","number":244,"type":"judge","prompt":"Maya软件多边形类型中\\"文本\\"选项卡参数的跟踪是根据相同的方形边界框均匀地调整所有字母之间的水平间距","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Tracking 均匀调整连续字母间的水平间距；字距微调可按字形关系调整字符间距。题干描述正确。"},{"id":"design-245","module":"design","title":"内容设计","number":245,"type":"single","prompt":"PS软件中哪种色彩是有饱和度的( )","options":[{"key":"A","text":"灰"},{"key":"B","text":"红"},{"key":"C","text":"黑"},{"key":"D","text":"白"}],"answer":["B"],"explanation":"红色是有彩色，具有色相和饱和度；黑、白、灰为无彩色，饱和度为零。选 B。"},{"id":"design-246","module":"design","title":"内容设计","number":246,"type":"single","prompt":"Faro scene支持的网格格式中错误的是？","options":[{"key":"A","text":"ply"},{"key":"B","text":"fbx"},{"key":"C","text":"stl"},{"key":"D","text":"obj"}],"answer":["B"],"explanation":"FARO SCENE 常见网格交换格式包括 PLY、STL、OBJ 等；FBX 通常不是题列的 SCENE 网格支持格式。选 B。"},{"id":"design-247","module":"design","title":"内容设计","number":247,"type":"single","prompt":"下面关于曲面修改工具用法描述错误的是？","options":[{"key":"A","text":"曲面修改工具中的取消修剪工具是可以取消对曲面的修剪操作"},{"key":"B","text":"曲面修改工具中的分离曲面是可以根据曲面模型上所选择的等参线来分离曲面线"},{"key":"C","text":"曲面修改工具中的修剪工具是可以根据曲面上的曲线来对曲面进行修剪操作"},{"key":"D","text":"曲面修改工具中的附加曲面是可以将两个曲面模型附加为一个曲面模型"}],"answer":["A","B","C","D"],"explanation":"取消修剪、按等参线分离曲面、用曲线修剪曲面和附加曲面均是曲面工具常见操作，题干中四项看起来都成立。作为单选题无法据此确定错误项，需查该课程版本或修正题干。"},{"id":"design-248","module":"design","title":"内容设计","number":248,"type":"judge","prompt":"PS软件控制面板可以根据需要进行伸缩","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Photoshop 控制面板/面板组可拖动边界调整大小，也可折叠或展开。题干正确。"},{"id":"design-249","module":"design","title":"内容设计","number":249,"type":"single","prompt":"UE4虚拟摄像机Actor的Details面板参数中的Bloom是()","options":[{"key":"A","text":"可实现实时全局光照(GI)"},{"key":"B","text":"可模拟人眼在看到明亮物体时感受到的效果"},{"key":"C","text":"用于对摄像机应用效果"},{"key":"D","text":"用提供的图像来给场景照明"}],"answer":["B"],"explanation":"Bloom（泛光）在明亮区域周围产生光晕，模拟镜头或视觉系统对高亮的扩散感。全局光照和环境立方体贴图是其他属性。"},{"id":"design-250","module":"design","title":"内容设计","number":250,"type":"single","prompt":"下面关于NURBS球体参数用法错误的有？","options":[{"key":"A","text":"NURBS球体参数中的结束扫描是可以设置球体曲面模型的结束扫描度数"},{"key":"B","text":"NURBS球体参数中的分段数是可以设置球体模型的横向分段"},{"key":"C","text":"NURBS球体参数中的次数分别有\\"Linear(线性)\\"和\\"Cubic(立方)\\"两种方式可选，用来控制球体的显示结果"},{"key":"D","text":"NURBS球体参数中的开始扫描是可以设置球体曲面模型的起始扫描度数"}],"answer":["C"],"explanation":"NURBS 次数（Degree）会影响曲面数学阶次和光滑性，线性/立方选项是参数类型，不是显示模式；C 表述不准确。起止扫描和分段数用途明确。"},{"id":"design-251","module":"design","title":"内容设计","number":251,"type":"judge","prompt":"Maya软件多边形管道的参数轴向细分数可以设置多边形管道的轴向分段数值。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"轴向细分数控制管道圆周方向的分段密度。题干正确。"},{"id":"design-252","module":"design","title":"内容设计","number":252,"type":"judge","prompt":"Maya软件曲面修改工具中的放样是可以根据选择的多条曲线来放样生成曲面模型","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"放样通过一条或多条截面曲线沿路径/顺序生成曲面，适合构造管状或过渡形状。题干正确。"},{"id":"design-253","module":"design","title":"内容设计","number":253,"type":"judge","prompt":"PS软件屏幕分辨率取决于显示器大小及其像素设置","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"屏幕分辨率取决于显示器像素阵列与当前显示设置；显示器物理尺寸影响像素密度而不是像素总数。题干作为基础说法正确。"},{"id":"design-254","module":"design","title":"内容设计","number":254,"type":"single","prompt":"下面关于分辨率理解错误的是？","options":[{"key":"A","text":"图像像素被直接转换成显示器屏幕像素,当图像分辨率高于屏幕分辨率时,屏幕中显示的图像比实际尺寸小"},{"key":"B","text":"屏幕分辨率取决于显示器大小及其像素设置"},{"key":"C","text":"在相同尺寸的两幅图像中,高分辨率的图像包含的像素比低分辨率的图像包含的像素多"},{"key":"D","text":"屏幕分辨率是显示器上每单位长度显示的像素数目"}],"answer":["A"],"explanation":"高分辨率图像在屏幕上按像素显示时是否比实际尺寸小，取决于像素映射和缩放设置，不能如此绝对概括。B、C、D的分辨率定义更准确，因此 A 错。"},{"id":"design-255","module":"design","title":"内容设计","number":255,"type":"judge","prompt":"着色模式本身具有一定的性能开销:无光模式最快，光照模式应该在大部分情况下使用。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Unlit/无光照材质不计算常规光照，开销通常最低；Lit 是多数受光场景应采用的模式。题干正确。"},{"id":"design-256","module":"design","title":"内容设计","number":256,"type":"judge","prompt":"Maya软件执行菜单栏\\"曲面/反转方向\\"命令,可以更改曲面模型的面方向","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Reverse Surface Direction 会反转曲面法线方向，影响正反面、法线和着色结果。题干正确。"},{"id":"design-257","module":"design","title":"内容设计","number":257,"type":"judge","prompt":"Skybox Textures都能用来代替实际的几何体物件并有效的提高性能","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"天空盒仅代表远景背景，不能普遍替代场景中所有几何物件；近景对象需要真实几何和交互碰撞。选项 B 表示错误。"},{"id":"design-258","module":"design","title":"内容设计","number":258,"type":"single","prompt":"Blinn材质\\"镜面反射着色\\"卷展栏中的偏心率是()","options":[{"key":"A","text":"控制曲面上发亮高光区的大小"},{"key":"B","text":"控制曲面高光的强弱"},{"key":"C","text":"控制材质反射物体的程度"},{"key":"D","text":"控制反射高光的颜色"}],"answer":["A"],"explanation":"Blinn 的偏心率控制高光扩散范围/大小；值越大通常高光越集中或更小。选项 A 最符合参数含义。"},{"id":"design-259","module":"design","title":"内容设计","number":259,"type":"judge","prompt":"Maya软件多边形类型中\\"文本\\"选项卡参数的字体大小是设置字体的大小","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Font Size 参数用于设置生成文本的字体大小。题干正确。"},{"id":"design-260","module":"design","title":"内容设计","number":260,"type":"single","prompt":"下面关于Maya软件选择模式快捷键错误的是？","options":[{"key":"A","text":"面选择模式的快捷键是F11"},{"key":"B","text":"边选择模式的快捷键是F10"},{"key":"C","text":"对象选择模式快捷键是F12"},{"key":"D","text":"顶点选择模式的快捷键是F9"}],"answer":["C"],"explanation":"对象选择/组件切换常用 F8，顶点 F9、边 F10、面 F11；不存在题干所称对象模式 F12。选 C。"},{"id":"design-261","module":"design","title":"内容设计","number":261,"type":"single","prompt":"下面关于UE4虚拟摄像机Actor的细节面板描述错误的是？","options":[{"key":"A","text":"Transform是指定由哪个激活的玩家控制器(如存在)来自动使用此摄像机"},{"key":"B","text":"Bloom是可模拟人眼在看到明亮物体时感受到的效果"},{"key":"C","text":"Camera Settings是这部分可用于修改摄像机所用的投影类型、视野、纵横比以及后处理混合"},{"key":"D","text":"Auto Player Activation是指定由哪个激活的玩家控制器(如存在)来自动使用此摄像机"}],"answer":["A"],"explanation":"Transform 描述位置、旋转和缩放，不是自动玩家控制器激活设置。D 的 Auto Player Activation 解释正确，故 A 错。"},{"id":"design-262","module":"design","title":"内容设计","number":262,"type":"single","prompt":"多边形建模技术与曲面建模技术差异正确的是？","options":[{"key":"A","text":"曲面模型编辑起来不麻烦"},{"key":"B","text":"多边形模型编辑起来非常复杂，不自由"},{"key":"C","text":"曲面模型没有严格的UV走向"},{"key":"D","text":"多边形模型是由多个顶点相互连接而成的一种立体拓扑结构"}],"answer":["D"],"explanation":"多边形模型由顶点、边和面构成拓扑网格，可直接编辑组件；这是其结构特征。其他选项对曲面编辑、UV和多边形自由度的描述错误。"},{"id":"design-263","module":"design","title":"内容设计","number":263,"type":"single","prompt":"下面关于材质的通用属性\\"镜面反射着色\\"参数含义正确的是？","options":[{"key":"A","text":"偏心率是指该参数用来控制高光扩散的大小，数值越大，高光点就越大"},{"key":"B","text":"镜面反射颜色是指该参数用于控制反射的颜色，可双击色块选择需要的反射颜色"},{"key":"C","text":"反射的颜色是指该参数用于控制高光的颜色，可双击色块选择需要的颜色"},{"key":"D","text":"镜面反射衰减是指该参数用于控制高光的强度，数值越小，高光就越强"}],"answer":["B"],"explanation":"镜面反射颜色控制反射颜色，可通过颜色输入或贴图驱动。偏心率、反射颜色和衰减各自对应高光/反射参数，B 是准确表述。"},{"id":"design-264","module":"design","title":"内容设计","number":264,"type":"single","prompt":"下面关于曲面修改工具用法描述错误的是？","options":[{"key":"A","text":"曲面修改工具中的双轨成形1工具是可以让一条轮廓线沿着两条曲线进行扫描从而生成曲面线"},{"key":"B","text":"曲面修改工具中的曲面相交是可以在曲面的交界处产生一条相交曲线"},{"key":"C","text":"曲面修改工具中的倒角是可以根据一条曲线生成带有倒角的曲面模型"},{"key":"D","text":"曲面修改工具中的在曲面上投影曲线是可以将曲线投影到曲面上,从而生成曲面曲线"}],"answer":["C"],"explanation":"倒角曲线/曲面工具生成倒角过渡需基于曲面边界或相邻曲面，不是简单“根据一条曲线生成带倒角的曲面模型”。A、B、D描述符合曲面操作。"},{"id":"design-265","module":"design","title":"内容设计","number":265,"type":"judge","prompt":"UE4导航视口WASD飞行控制操作仅在透视口中有效，按住鼠标右键才能使用WASD游戏风格控制","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"UE4 透视视口的 WASD 飞行控制通常要求按住鼠标右键，同时仅在透视视口生效。题干正确。"},{"id":"design-266","module":"design","title":"内容设计","number":266,"type":"judge","prompt":"材质的通用属性白炽度是指用于模拟物体的自发光效果，但是并不会照亮其他的物体","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Incandescence/自发光控制材质自身发亮，不会自动作为照明光源照亮场景其他物体。若要照亮周围，需实际灯光或全局光照。"},{"id":"design-267","module":"design","title":"内容设计","number":267,"type":"judge","prompt":"Maya软件多边形立方体的参数高度可以设置多边形立方体的高度。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"立方体的 Height 参数设置模型高度尺寸。题干正确。"},{"id":"design-268","module":"design","title":"内容设计","number":268,"type":"judge","prompt":"Maya软件多边形平面参数分别是宽度、高度、细分宽度、高度细分数","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"多边形平面常用参数为宽度、高度、宽度细分和高度细分。题干正确。"},{"id":"design-269","module":"design","title":"内容设计","number":269,"type":"judge","prompt":"Maya软件多边形立方体的参数宽度可以设置多边形立方体的宽度","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"多边形立方体的 Width 参数控制宽度尺寸。题干正确。"},{"id":"design-270","module":"design","title":"内容设计","number":270,"type":"judge","prompt":"Blinn材质主要用来模拟金属和玻璃的效果，它具有金属表面和玻璃表面特性","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Blinn 材质能形成较柔和高光，常用于金属或玻璃等具有较明显反射/高光特征的表面。题干正确。"},{"id":"design-271","module":"design","title":"内容设计","number":271,"type":"judge","prompt":"Maya软件多边形球体是在\\"多边形建模\\"工具架上单击\\"多边形球体\\"图标中创建","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"可通过 Maya 的多边形建模工具架上的球体图标创建多边形球体。题干正确。"},{"id":"design-272","module":"design","title":"内容设计","number":272,"type":"single","prompt":"下面关于NURBS立方体参数用法有误的是？","options":[{"key":"A","text":"NURBS立方体参数中的U向面片数是可以控制NURBS立方体U向的分段数"},{"key":"B","text":"NURBS立方体参数中的长度比/高度比是可以调整NURBS立方体的长度和高度"},{"key":"C","text":"URBS立方体参数中的宽度是可以控制NURBS立方体的宽度大小"},{"key":"D","text":"NURBS立方体参数中的V向面片数是可以用来控制NURBS立方体V向的分段数"}],"answer":["C"],"explanation":"NURBS 立方体用 U/V 面片数控制曲面分段，用宽度、长度比和高度比定义尺寸比例；题项 C 将参数组合写错。D 是常见参数组合。"},{"id":"design-273","module":"design","title":"内容设计","number":273,"type":"single","prompt":"下面关于UE4工具编辑器理解错误的是？","options":[{"key":"A","text":"UE4在材质编辑器中,可以新建材质,这些材质能够被应用于一个模型来控制模型的可见外观"},{"key":"B","text":"UE4粒子系统由级联粒子编辑器来编辑制作,这是一个完全整合在引擎中的模块化粒子特效编辑器"},{"key":"C","text":"UE4在蓝图编辑器中可制作或修改蓝图,蓝图是一种特殊的资源,能够被作为一个新的Actor类型来创建,并且用脚本来响应关卡事件,无须编写任何C++的代码"},{"key":"D","text":"UE4关卡编辑器是对模型的外观、碰撞和UV来做预览,并且能修改静态网格体的一些参数属性"}],"answer":["D"],"explanation":"关卡编辑器用于构建关卡；外观、碰撞和 UV 的预览设置属于静态网格体编辑器。D 把两个编辑器的职责混淆。"},{"id":"design-274","module":"design","title":"内容设计","number":274,"type":"judge","prompt":"根据移动激光扫描系统和数码相机采集的数据可以得到点云数据","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"激光扫描提供空间点，数码相机影像可补充颜色和纹理；数据配准后能得到带颜色点云。题干正确。"},{"id":"design-275","module":"design","title":"内容设计","number":275,"type":"single","prompt":"下面关于Maya软件\\"软选择\\"卷展栏属性内容的说法错误的有？","options":[{"key":"A","text":"\\"重置曲线\\"按钮是可以用于将所有\\"软选择\\"的设置重置为默认值"},{"key":"B","text":"拾取/框选是可以在用户要选择的组件上绘制一个矩形框来选择对象"},{"key":"C","text":"亮显背面启用时，亮显距光标最近的组件，然后用户可以选择它"},{"key":"D","text":"基于摄像机的选择启用后，可以根据摄影机的角度来选择对象组件"}],"answer":["C"],"explanation":"“亮显背面”控制是否显示背向视角的组件，不是高亮鼠标最近组件；最近组件有独立选项。故 C 错。"},{"id":"design-276","module":"design","title":"内容设计","number":276,"type":"single","prompt":"下面多边形类型中\\"文本\\"选项卡的参数描述有误的是？","options":[{"key":"A","text":"Maya软件多边形类型中\\"文本\\"选项卡参数的空间宽度比例是调整手动空间的宽度"},{"key":"B","text":"Maya软件多边形类型中\\"文本\\"选项卡参数的跟踪是根据相同的方形边界框均匀地调整所有字母之间的垂直间距"},{"key":"C","text":"Maya软件多边形类型中\\"文本\\"选项卡参数的字体大小是设置字体的大小"},{"key":"D","text":"Maya软件多边形类型中\\"文本\\"选项卡参数的字距微调比例是根据每个字母的特定形状均匀地调整所有字母之间的水平间距"}],"answer":["B"],"explanation":"Tracking 调整字母间的水平间距，不是垂直间距；垂直行距由 Leading 控制。题干错误项为 B。"},{"id":"design-277","module":"design","title":"内容设计","number":277,"type":"single","prompt":"下面是有关\\"木材\\"纹理参数的描述，其中错误的是？","options":[{"key":"A","text":"颗粒对比度是控制漫反射到周围木材颜色的\\"颗粒颜色\\"量"},{"key":"B","text":"中心是纹理的同心环中心在U和V方向的位置"},{"key":"C","text":"颗粒间距是颗粒斑点之间的平均距离"},{"key":"D","text":"层大小是随机化各个层或环形的厚度"}],"answer":["D"],"explanation":"层大小/层宽度控制纹理木材环层的尺度，不等同于随机化层厚度；随机度负责随机变化。故 D 错。"},{"id":"design-278","module":"design","title":"内容设计","number":278,"type":"judge","prompt":"PS软件若需单独拆分出某个控制面板,可用鼠标选中该控制面板的选项卡并向工作区拖曳","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"拖动面板选项卡到工作区外可将它从面板组分离，成为独立浮动面板。题干正确。"},{"id":"design-279","module":"design","title":"内容设计","number":279,"type":"judge","prompt":"Maya软件曲面修改工具中的双轨成形1工具是可以让一条轮廓线沿着两条曲线进行扫描从而生成曲面模型","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"双轨成形工具沿两条轨道曲线扫描轮廓线以生成曲面。题干正确。"},{"id":"design-280","module":"design","title":"内容设计","number":280,"type":"single","prompt":"下列关于\\"标准曲面材质\\"命令参数\\"透射\\"参数理解错误的是？","options":[{"key":"A","text":"颜色是会根据折射光线的传播距离过滤折射"},{"key":"B","text":"色散系数是指定材质的色散系数，值越大，色散越多"},{"key":"C","text":"深度是控制透射颜色在体积中达到的深度"},{"key":"D","text":"权重是用于设置灯光穿过物体表面所产生的散射权重"}],"answer":["D"],"explanation":"透射权重控制透射效果所占比例；灯光穿过物体后的散射属于其他透射/散射参数。D 混淆了权重的作用。"},{"id":"design-281","module":"design","title":"内容设计","number":281,"type":"single","prompt":"下列关于材质概述错误的是？","options":[{"key":"A","text":"材质称为着色器，用于定义对象的基质"},{"key":"B","text":"当高光反射颜色与漫反射颜色相符时，会产生一种无光效果，从而降低材质的光泽性"},{"key":"C","text":"曲面着色是对象的基本材质和应用于它的任何纹理的组合"},{"key":"D","text":"反射是指光线透过对象后，改变了原有的光线的投射角度，使光线产生偏差，如透过水面看对象"}],"answer":["D"],"explanation":"折射是光通过介质后方向改变，不是材质概述中“反射”的定义。D 把折射说成反射，故错误；其余选项均可描述材质或着色。"},{"id":"design-282","module":"design","title":"内容设计","number":282,"type":"judge","prompt":"Maya软件NURBS圆形常用参数半径是用于设置NURBS圆形的半径大小","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"NURBS 圆形的 Radius 参数设置圆的半径。改变此值会按创建历史调整圆的大小，题干正确。"},{"id":"design-283","module":"design","title":"内容设计","number":283,"type":"judge","prompt":"UE4按下\\"T\\"键可以切换到Scale Tool(缩放工具)进行缩放操作","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"UE4 的 T 是缩放工具快捷键，E 是旋转，W 是平移。题干所述正确。"},{"id":"design-284","module":"design","title":"内容设计","number":284,"type":"single","prompt":"NURBS圆柱体参数分别有哪些？","options":[{"key":"A","text":"开始扫描、结束扫描、次数、分段数、跨度数"},{"key":"B","text":"扫描、半径、次数、分段数"},{"key":"C","text":"半径、高度、厚度、轴向细分数、高度细分数、端面细分数"},{"key":"D","text":"开始扫描、结束扫描、半径、分段数、跨度数、高度比"}],"answer":["D"],"explanation":"NURBS 圆柱体创建参数包括起始/结束扫描、半径、分段/跨度和高度比等。D 是唯一包含球面/圆柱共同参数并带高度比的组合。"},{"id":"design-285","module":"design","title":"内容设计","number":285,"type":"judge","prompt":"Geomagic Wrap高清面片构建不可以创建封闭面片","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"Geomagic Wrap 的高密度面片构建可形成封闭面片/水密模型，常用于打印或后续建模。题干否定该能力，因此错误。"},{"id":"design-286","module":"design","title":"内容设计","number":286,"type":"judge","prompt":"PS软件CMYK模式在印刷时应用了色彩学中的减法混合原理,即减色色彩模式","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"CMYK 通过青、洋红、黄、黑油墨吸收部分白光产生颜色，属于减色混合模型。题干正确。"},{"id":"design-287","module":"design","title":"内容设计","number":287,"type":"judge","prompt":"三维重建是将二维图片中的信息在三维虚拟空间中显现","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"三维重建把二维图像中的多视角线索或纹理映射到三维虚拟空间中，恢复几何和外观。题干正确。"},{"id":"design-288","module":"design","title":"内容设计","number":288,"type":"judge","prompt":"PS软件矢量图在任何分辨率下显示或打印,都不会损失细节","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"矢量图用路径和几何描述内容，输出时可按目标分辨率重新栅格化，因此缩放/打印不会像位图那样出现像素化。题干正确。"},{"id":"design-289","module":"design","title":"内容设计","number":289,"type":"judge","prompt":"材质技术在三维软件中可以真实地反映出物体的颜色、纹理、透明、光泽以及凹凸质感","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"材质属性可定义颜色、纹理、透明、粗糙/光泽和凹凸等外观信息，渲染时由光照模型综合计算。题干正确。"},{"id":"design-290","module":"design","title":"内容设计","number":290,"type":"single","prompt":"关于管理美术资源和关卡设计在性能优化方面说法错误的是？","options":[{"key":"A","text":"光照函数具有额外的性能开销(实际开销取决于材质)，并能防止灯光被渲染成Tiled Light"},{"key":"B","text":"区域光照源会更省一些，应当在可能的情形下尽量使用"},{"key":"C","text":"根据较小的物体来调整渲染距离，来达到更好的裁剪效果"},{"key":"D","text":"静态光照最快，固定光照稍慢一些，动态光照最慢"}],"answer":["B"],"explanation":"区域光源通常比点光/聚光计算开销高，不是“更省且尽量使用”。限制范围、裁剪和静态/动态光照层级等其余说法是常见优化方向，故选 B。"},{"id":"design-291","module":"design","title":"内容设计","number":291,"type":"judge","prompt":"Maya软件NURBS球体参数中的分段数是可以设置球体模型的竖向分段","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"NURBS 球体的 Sections/分段数可控制球面一个方向的分段密度，常对应竖向分段。题干正确。"},{"id":"design-292","module":"design","title":"内容设计","number":292,"type":"judge","prompt":"纹理贴图可以视为一个纹理节点","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"图像文件纹理通过 File 纹理节点输入材质网络；纹理节点是着色网络中的数据节点。题干将贴图作为节点描述，正确。"},{"id":"design-293","module":"design","title":"内容设计","number":293,"type":"judge","prompt":"移动测绘系统MMS包括移动激光扫描系统和数码相机","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"MMS 通常把移动激光扫描与相机影像、定位导航等数据结合，用于道路/城市移动测绘。题干列举的两类组成成立。"},{"id":"design-294","module":"design","title":"内容设计","number":294,"type":"single","prompt":"PS软件按()组合键,会弹出\\"新建文档\\"对话框","options":[{"key":"A","text":"Ctrl+W"},{"key":"B","text":"Ctrl+S"},{"key":"C","text":"Ctrl+O"},{"key":"D","text":"Ctrl+N"}],"answer":["D"],"explanation":"Ctrl+N 在 Photoshop 中新建文档；Ctrl+O 打开，Ctrl+S 保存，Ctrl+W 关闭。选 D。"},{"id":"design-295","module":"design","title":"内容设计","number":295,"type":"judge","prompt":"移动激光扫描系统用于测量点的三维坐标和激光反射强度","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"移动激光扫描直接测量点的三维位置并可记录回波强度等属性。题干正确。"},{"id":"design-296","module":"design","title":"内容设计","number":296,"type":"judge","prompt":"UE4在透视口中，按D键，可以向前移动相机","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"UE4 透视视口的 W/A/S/D 飞行键分别用于前、左、后、右等移动，D 通常向右，不是向前。题干错误。"},{"id":"design-297","module":"design","title":"内容设计","number":297,"type":"judge","prompt":"PS软件选择\\"文件\\\\>新建\\"命令,或按Ctrl+M组合键,弹出\\"新建文档\\"对话框","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"Photoshop 新建文档快捷键是 Ctrl+N；Ctrl+M 打开曲线调整，不是新建。题干错误。"},{"id":"design-298","module":"design","title":"内容设计","number":298,"type":"judge","prompt":"纹理类型主要包括\\"2D纹理\\"、\\"3D纹理\\"、\\"环境纹理\\"和\\"其他纹理\\"这4种","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"常见纹理分类可分为 2D、3D、环境和其他纹理。题干符合教材分类。"},{"id":"design-299","module":"design","title":"内容设计","number":299,"type":"judge","prompt":"Maya软件\\"多边形类型\\"工具可以创建出多边形文本模型","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Maya 的多边形类型工具包含 Text 选项，可将文字生成多边形几何体。题干正确。"},{"id":"design-300","module":"design","title":"内容设计","number":300,"type":"judge","prompt":"Maya软件曲面修改工具中的旋转是可以根据选择的曲线来旋转生成一个曲面模型。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"曲面旋转工具绕指定轴旋转一条曲线，生成旋转曲面。题干正确。"},{"id":"design-301","module":"design","title":"内容设计","number":301,"type":"single","prompt":"Maya软件NURBS球体参数分别有哪些？","options":[{"key":"A","text":"开始扫描、结束扫描、次数、分段数、端面数"},{"key":"B","text":"开始扫描、结束扫描、细分数、分段数、跨度数"},{"key":"C","text":"开始扫描、结束扫描、次数、分段数、跨度数"},{"key":"D","text":"开始扫描、结束扫描、半径、分段数、跨度数"}],"answer":["C"],"explanation":"NURBS 球体参数包括起止扫描、次数/阶数、分段数和跨度数。C 是匹配这些参数的选项。"},{"id":"design-302","module":"design","title":"内容设计","number":302,"type":"judge","prompt":"PS软件选择\\"文件\\\\>存储\\"命令,或按Ctrl+O组合键,可以存储文件","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"Ctrl+O 是打开文件；保存快捷键为 Ctrl+S（另存为通常 Ctrl+Shift+S）。题干快捷键错误。"},{"id":"design-303","module":"design","title":"内容设计","number":303,"type":"judge","prompt":"三维重建是将三维的物体在虚拟世界中重建出来","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"三维重建的目标是从图像、扫描数据恢复三维物体/模型，不是把已有三维物体“在虚拟世界重建”。题干把对象和过程说反。"},{"id":"design-304","module":"design","title":"内容设计","number":304,"type":"single","prompt":"关于管理美术资源和关卡设计在性能优化方面说法错误的是？","options":[{"key":"A","text":"越低的贴图分辨率越慢(当放大时)"},{"key":"B","text":"如果一个贴图可以在较小的比例下被用到，应一直都为它采用mipmaps，可以避免因为贴图缓存的未命中导致的性能下降"},{"key":"C","text":"较大的模型可以分为多个，以获得更好的裁剪优化。这不止对于可见性的裁剪，光照则在更细的粒度上被处理"},{"key":"D","text":"最快的几个表达式是:multiply,add,subtract,以及使用0和1的clamp()"}],"answer":["A"],"explanation":"当放大观察时，低分辨率纹理会变得模糊/像素化，并不会因此更慢；贴图缓存、模型裁剪和简单材质运算都是优化考量。错误项 A。"},{"id":"design-305","module":"design","title":"内容设计","number":305,"type":"single","prompt":"UE4通过按下()可以启用旋转工具,进行旋转操作","options":[{"key":"A","text":"\\"W\\"键"},{"key":"B","text":"\\"O\\"键"},{"key":"C","text":"\\"E\\"键"},{"key":"D","text":"\\"R\\"键"}],"answer":["C"],"explanation":"UE4 编辑器快捷键 W 平移、E 旋转、R 缩放。旋转工具对应 E，即选 C。"},{"id":"design-306","module":"design","title":"内容设计","number":306,"type":"judge","prompt":"限制UV裂缝和模型硬边的数量，因为它们会导致硬件计算时更多的顶点数据","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"UV 接缝和硬边可能拆分顶点属性，增加顶点数据与顶点数，提升显存/带宽开销。控制数量有助于优化，题干正确。"},{"id":"design-307","module":"design","title":"内容设计","number":307,"type":"judge","prompt":"IES profiles具有额外性能开销(比光照函数好一些)，并能防止灯光被渲染成 Tiled Light。但不要在可以用聚光灯光锥就能完成效果的情形下，还使用IES","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"IES 配置有额外成本，但有时比复杂光照函数开销低；若普通聚光锥已能达到效果，就不必使用 IES。题干是合理优化原则。"},{"id":"design-308","module":"design","title":"内容设计","number":308,"type":"judge","prompt":"Faro scene是一款三维数字存档软件","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"FARO SCENE 是用于扫描数据处理、注册、可视化和三维数字记录/存档的专业软件。题干正确。"},{"id":"design-309","module":"design","title":"内容设计","number":309,"type":"judge","prompt":"UE4 Paper2D图片编辑器能够设置并编辑独立的Paper 2D Sprites","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Paper2D Sprite Editor 可编辑独立 Sprite 资源的图像区域、枢轴和相关属性。题干正确。"},{"id":"design-310","module":"design","title":"内容设计","number":310,"type":"single","prompt":"Maya软件NURBS圆柱体参数中的跨度数是可以设置NURBS圆柱体的()","options":[{"key":"A","text":"高度"},{"key":"B","text":"半径大小"},{"key":"C","text":"横向分段"},{"key":"D","text":"竖向分段"}],"answer":["D"],"explanation":"NURBS 圆柱体的跨度数对应曲面参数方向分段，题库此处指竖向分段。选 D。"},{"id":"design-311","module":"design","title":"内容设计","number":311,"type":"judge","prompt":"点云数据包括三维坐标、激光反射强度、颜色信息","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"点云基本字段为每点三维坐标，也可以附带反射强度和 RGB 颜色。题干列出的信息均可存在。"},{"id":"design-312","module":"design","title":"内容设计","number":312,"type":"judge","prompt":"Maya软件曲线修改工具中的偏移曲线是将曲线复制并偏移一些。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Offset Curve 会复制曲线并沿指定方向偏移一定距离，生成新曲线。题干正确。"},{"id":"design-313","module":"design","title":"内容设计","number":313,"type":"judge","prompt":"PS软件RGB是色光的彩色模式","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"RGB 通过红、绿、蓝三种色光叠加表示颜色，属于色光/加色模式。题干正确。"},{"id":"design-314","module":"design","title":"内容设计","number":314,"type":"judge","prompt":"材质的通用属性白炽度是指用于模拟物体的自发光效果，但是并不会照亮其他的物体","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"白炽度模拟材质表面的自发光外观；单独的自发光材质通常不产生照亮其他物体的实际光照。题干正确。"},{"id":"design-315","module":"design","title":"内容设计","number":315,"type":"single","prompt":"下面有关曲面建模描述正确的是？","options":[{"key":"A","text":"曲面建模可以通过创建曲线的方式来构建曲面的基本轮廓"},{"key":"B","text":"曲面建模可以通过创建曲面基本体的方式来绘制简单的三维对象"},{"key":"C","text":"以上都正确"},{"key":"D","text":"曲面建模,也叫做NURBS建模,具一种基于几何基本体和绘制曲线的3D建模方式"}],"answer":["C"],"explanation":"曲面/NURBS 建模既可从曲线构造轮廓，也可由曲面基本体开始建立简单物体。D 虽有文字错误但概念仍指这类方法，A、B成立，因此选 C。"},{"id":"design-316","module":"design","title":"内容设计","number":316,"type":"single","prompt":"Maya软件多边形立方体常用参数描述不正确的是？","options":[{"key":"A","text":"Maya软件多边形立方体的参数深度可以设置多边形立方体的深度"},{"key":"B","text":"Maya软件多边形立方体的参数宽度可以设置多边形立方体的宽度"},{"key":"C","text":"Maya软件多边形立方体的参数分段宽度可以设置多边形立方体的高度上的分段数量"},{"key":"D","text":"Maya软件多边形立方体的参数高度可以设置多边形立方体的高度"}],"answer":["C"],"explanation":"立方体的分段宽度参数只影响宽度方向，不是高度方向。A、B、D的尺寸参数解释正确，故错误项 C。"},{"id":"design-317","module":"design","title":"内容设计","number":317,"type":"single","prompt":"下面关于PS软件的工具使用快捷键错误的是？","options":[{"key":"A","text":"按Tab键,可以隐藏工具箱和控制面板"},{"key":"B","text":"按Ctrl+N组合键,弹出\\"新建文档\\"对话框"},{"key":"C","text":"按Ctrl+W组合键,即可关闭文件"},{"key":"D","text":"按Ctrl+S组合键,弹出\\"打开\\"对话框"}],"answer":["D"],"explanation":"Ctrl+S 是保存，不会弹出打开对话框；打开文件用 Ctrl+O。其余快捷键描述基本正确，故 D 错。"},{"id":"design-318","module":"design","title":"内容设计","number":318,"type":"judge","prompt":"光照函数具有额外的性能开销(实际开销取决于材质)，并能防止灯光被渲染成Tiled Light","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"光照函数在材质中采样会增加开销，其实现可能影响灯光在延迟渲染/Tile 光照路径中的处理。题干符合该性能提示。"},{"id":"design-319","module":"design","title":"内容设计","number":319,"type":"judge","prompt":"着色模式本身具有一定的性能开销:无光模式最快，光照模式应该在大部分情况下使用","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Unlit 着色不做常规受光计算，通常最快；多数正常受光材质应使用 Lit。题干正确。"},{"id":"design-320","module":"design","title":"内容设计","number":320,"type":"judge","prompt":"UE4粒子系统由级联粒子编辑器来编辑制作,这是一个完全整合在引擎中的模块化粒子特效编辑器","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"UE4 Cascade 是整合在引擎中的模块化粒子编辑器，可配置发射器和模块并实时预览。题干正确。"},{"id":"design-321","module":"design","title":"内容设计","number":321,"type":"judge","prompt":"Maya软件多边形圆柱体的参数高度可以设置多变形圆柱的高度值。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Maya 多边形圆柱体的 Height 参数控制模型高度。题干正确。"},{"id":"design-322","module":"design","title":"内容设计","number":322,"type":"single","prompt":"下面关于UE4编辑材质的方法描述错误的是？","options":[{"key":"A","text":"UE4材质编辑器中，按住\\"1\\"键并用左键单击图来创建常量节点，常量节点是可修改的浮点型变量"},{"key":"B","text":"UE4材质编辑器中，按住\\"2\\"键并用左键单击图来创建1个Constant 3 Vector节点"},{"key":"C","text":"材质编辑器中可以按住T键,然后在编辑器的图中单击左键，会出现Texture Sample节点"},{"key":"D","text":"在细节面板中，将Shading Model从Default Lit改为Subsurface，可以打开引脚不透明度 Opacity和次表面颜色Subsurface Color"}],"answer":["B"],"explanation":"材质编辑器中按 1 创建单值 Constant；按 2 创建 Constant2Vector，不是 Constant3Vector。3 才创建三维向量，因此 B 错。"},{"id":"design-323","module":"design","title":"内容设计","number":323,"type":"single","prompt":"下列那种格式不是点云存储格式？","options":[{"key":"A","text":"las"},{"key":"B","text":"xyz"},{"key":"C","text":"asc"},{"key":"D","text":"psd"}],"answer":["D"],"explanation":"LAS、XYZ、ASC 是常用点云交换格式；PSD 是 Photoshop 图像文档格式。选 D。"},{"id":"design-324","module":"design","title":"内容设计","number":324,"type":"single","prompt":"下面关于PS软件HSB模式描述错误的是？","options":[{"key":"A","text":"在HSB模式里，亮度是色彩的明亮程度,最大亮度是色彩最鲜明的状态,黑色的亮度为0"},{"key":"B","text":"HSB模式中，H代表色相,S代表饱和度,B代表亮度"},{"key":"C","text":"HSB模式的黑、白、灰3种色彩是有饱和度的"},{"key":"D","text":"HSB模式下红色为0度,绿色为120度,蓝色为240度"}],"answer":["C"],"explanation":"黑、白、灰是无彩色，饱和度为零；HSB 中 H/S/B 分别为色相、饱和度、亮度。C 错。"},{"id":"design-325","module":"design","title":"内容设计","number":325,"type":"single","prompt":"下面关于UE4的Project(项目)理解错误的是？","options":[{"key":"A","text":"PlayerController负责设置正在运行的游戏的规则"},{"key":"B","text":"一个Word(世界)包含了所加载的一系列关卡"},{"key":"C","text":"Brush(画刷)是用来定义BSP关卡几何体和游戏体积的体积"},{"key":"D","text":"Level(关卡)是定义的游戏区域,也被称为地图"}],"answer":["A"],"explanation":"GameMode 管理游戏规则；PlayerController 获取并处理玩家输入。A 把两种 UE 框架类的职责混淆。"},{"id":"design-326","module":"design","title":"内容设计","number":326,"type":"single","prompt":"下列关于2D纹理与3D纹理错误的是？","options":[{"key":"A","text":"\\"棋盘格\\"纹理属于\\"2D纹理\\"贴图"},{"key":"B","text":"\\"文件\\"纹理属于\\"3D纹理\\""},{"key":"C","text":"3D纹理是根据程序以三维方式生成的图案，它不受物体外观的影响"},{"key":"D","text":"2D纹理通常作用于几何对象的表面，它的效果取决于UV坐标和投射的方式"}],"answer":["B"],"explanation":"棋盘格是二维程序纹理，File 节点读取图像文件，属于 2D 纹理而不是 3D 纹理。B 错；3D 纹理按三维空间程序生成。"},{"id":"design-327","module":"design","title":"内容设计","number":327,"type":"judge","prompt":"Maya软件多边形立方体的参数深度可以设置多边形立方体的深度。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"立方体的 Depth 参数控制模型深度尺寸。题干正确。"},{"id":"design-328","module":"design","title":"内容设计","number":328,"type":"single","prompt":"下面关于Maya软件\\"建模工具包\\"中的多边形编辑工具的说法错误的有？","options":[{"key":"A","text":"布尔工具是只能执行并集，以组合所选网格的体积。原始的两个对象均保留，并减去交集"},{"key":"B","text":"结合工具是可以将选定的网格组合到单个多边形网格中9+"},{"key":"C","text":"平滑工具是可以通过向网格上的多边形添加分段来平滑选定多边形网格"},{"key":"D","text":"分离工具是可以将网格中断开的壳分离为单独的网格"}],"answer":["A"],"explanation":"Maya Boolean 不只支持并集，也支持差集和交集；执行后可创建新结果而非只能保留原始对象。A 对工具能力描述错误。"},{"id":"design-329","module":"design","title":"内容设计","number":329,"type":"judge","prompt":"控制固定光照和动态光照的数量。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"控制固定和动态光源的数量可影响渲染成本；应根据需要减少昂贵的动态光源。题干作为优化建议成立。"},{"id":"design-330","module":"design","title":"内容设计","number":330,"type":"judge","prompt":"Maya软件\\"建模工具包\\"中的四边形绘制是以自然而有机的方式建模，使用简化的单工具工作流重新拓扑化网格","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Quad Draw 通过在参考网格表面绘制四边形进行重拓扑，支持自然、逐步构建低密度网格。题干正确。"},{"id":"design-331","module":"design","title":"内容设计","number":331,"type":"single","prompt":"下列关于材质概述错误的是？","options":[{"key":"A","text":"材质主要包括物体颜色、透明度、光泽度等物理或光学特性"},{"key":"B","text":"材质称为物体颜色，用于定义对象的色彩"},{"key":"C","text":"用户可以通过控制对象的材质和场景灯光来控制对象的曲面外观质感"},{"key":"D","text":"材质技术在三维软件中可以真实地反映出物体的颜色、纹理、透明、光泽以及凹凸质感"}],"answer":["B"],"explanation":"材质不是简单等同于物体颜色，它还包含透明、光泽、粗糙、凹凸等表面属性。B 把材质缩减为颜色，因此错误。"},{"id":"design-332","module":"design","title":"内容设计","number":332,"type":"single","prompt":"下面关于PS软件\\"矩形选框\\"工具属性栏描述错误的是？","options":[{"key":"A","text":"新选区是去除旧选区,绘制新选区"},{"key":"B","text":"从区减去是在原有选区上减去新选区的部分"},{"key":"C","text":"添加到选区是在原有选区的上面增加新的选区"},{"key":"D","text":"与选区交叉是选择新旧选区不重叠的部分"}],"answer":["D"],"explanation":"“与选区交叉”保留新旧选区重叠的交集部分，而不是选择不重叠部分。D 描述错误。"},{"id":"design-333","module":"design","title":"内容设计","number":333,"type":"single","prompt":"下面关于UE4虚拟摄像机Actor的细节面板描述错误的是？","options":[{"key":"A","text":"Tags是摄像机Actor 本身的相关信息"},{"key":"B","text":"Motion Blur是用于产生动态模糊效果，根据运动情况将物体变模糊"},{"key":"C","text":"Screen Space Reflections是这是一个默认启用的效果，可以改变物体材质表面反射的效果"},{"key":"D","text":"Misc是应用可融合效果和抗锯齿等设定"}],"answer":["A"],"explanation":"Tags 用于给 Actor 添加标签以便识别/查询，不是摄像机本身的一般信息说明。其他选项分别对应运动模糊、屏幕空间反射和 Misc 后处理设置，错误项 A。"},{"id":"design-334","module":"design","title":"内容设计","number":334,"type":"judge","prompt":"UE4可以使用\\"E\\"键切换到Translation Tool(平移工具)进行移动操作","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"UE4 默认快捷键 E 切换旋转工具，W 平移，R 缩放。题干正确。"},{"id":"design-335","module":"design","title":"内容设计","number":335,"type":"judge","prompt":"越大的贴图格式能带来更快的材质","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"更大的贴图格式/分辨率通常增加内存与采样成本，不会自动让材质更快。题干错误。"},{"id":"design-336","module":"design","title":"内容设计","number":336,"type":"single","prompt":"Phong材质在\\"镜面反射着色\\"卷展栏中的余弦幂是()","options":[{"key":"A","text":"控制材质反射物体的程度"},{"key":"B","text":"控制材质反射的颜色"},{"key":"C","text":"控制反射高光的颜色"},{"key":"D","text":"控制曲面上反射高光的大小"}],"answer":["D"],"explanation":"Phong 余弦幂控制高光集中程度/大小；值越高高光越小越集中。选项 D 最符合高光尺寸控制。"},{"id":"design-337","module":"design","title":"内容设计","number":337,"type":"judge","prompt":"Maya软件多边形球体的半径可以控制多边形球体的半径大小","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"多边形球体 Radius 参数控制球体整体半径。题干正确。"},{"id":"design-338","module":"design","title":"内容设计","number":338,"type":"single","prompt":"UE4材质编辑器中，按住()并用左键单击图来创建常量节点，常量节点是可修改的浮点型变量","options":[{"key":"A","text":"\\"4\\"键"},{"key":"B","text":"\\"2\\"键"},{"key":"C","text":"\\"3\\"键"},{"key":"D","text":"\\"1\\"键"}],"answer":["D"],"explanation":"按 1 并单击创建单值 Constant 节点，其浮点值可在细节面板编辑。2/3/4 分别用于向量常量节点。"},{"id":"design-339","module":"design","title":"内容设计","number":339,"type":"judge","prompt":"PS软件按Tab键,可以隐藏工具箱和控制面板;再次按Tab键,可以显示出隐藏的部分","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Tab 可隐藏工具箱和面板，再次按 Tab 可恢复显示。题干正确。"},{"id":"design-340","module":"design","title":"内容设计","number":340,"type":"single","prompt":"下面关于UE4网格体三角剖分的方法描述错误的是？","options":[{"key":"A","text":"让FBX导出器三角剖分网格体。可以进行清理，但适用于简单网格体"},{"key":"B","text":"让导入器三角剖分网格体。无法进行清理，但适用于简单网格体"},{"key":"C","text":"在3D软件中三角剖分网格体。在导出之前可以进行清理和修改"},{"key":"D","text":"仅使用三角形进行网格体建模。能对最终结果进行最大程度的控制"}],"answer":["B"],"explanation":"导入器可自动三角化，但控制/清理能力有限；在 DCC 软件预先三角化可检查并修改结果。B 对“无法清理、适用于简单网格”的描述不准确。"},{"id":"design-341","module":"design","title":"内容设计","number":341,"type":"judge","prompt":"UE4导航视口环绕、移动及跟踪支持Maya式的平移、旋转及缩放的视口控制","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"UE4 视口可切换 Maya 风格的环绕、平移和缩放导航方式。题干正确。"},{"id":"design-342","module":"design","title":"内容设计","number":342,"type":"judge","prompt":"Maya软件曲线修改工具中的添加点工具是选择要添加点的曲线来进行加点操作","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Add Points 工具需要选取目标曲线并在其上增加编辑点/参数点。题干正确。"},{"id":"design-343","module":"design","title":"内容设计","number":343,"type":"judge","prompt":"节点包括常说的渲染节点、材质节点、贴图节点、灯光节点等","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"着色网络节点类别包括渲染节点、材质节点、纹理节点和灯光节点等。题干正确。"},{"id":"design-344","module":"design","title":"内容设计","number":344,"type":"judge","prompt":"PS软件Lab模式b通道是饱和度，是从亮蓝色到灰,再到焦黄色","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"Lab 的 b 通道表示蓝到黄，不是饱和度；a 通道才近似绿到红。题干错误。"},{"id":"design-345","module":"design","title":"内容设计","number":345,"type":"judge","prompt":"UE4媒体播放编辑器能够在这个编辑器中查看媒体的信息,以及使用标准回放的控制来查看该媒体内容","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Media Player 可查看媒体信息并使用播放、暂停、定位等标准回放控件预览内容。题干正确。"},{"id":"design-346","module":"design","title":"内容设计","number":346,"type":"judge","prompt":"选择场景中的所有模型，单击\\"多边形建模\\"工具架上的\\"结合\\"图标，即可将多个模型组合为一个整体","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"Combine 把多个网格合为一个网格对象，但通常不焊接彼此独立的顶点或消除内部拓扑，也不等同于真正融合成一个连续实体。题干“组合为一个整体”过于绝对。"},{"id":"design-347","module":"design","title":"内容设计","number":347,"type":"judge","prompt":"从3D建模软件中导出网格体时，枢轴点坐标不必固定位于原点处(0,0,0)","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"导出网格的枢轴不必固定在世界原点；原点位置由资产用途和导出设置决定。重要的是与引擎中的预期变换一致。"},{"id":"design-348","module":"design","title":"内容设计","number":348,"type":"judge","prompt":"图像处理数据的最小元素被称为像素，图像处理的工作即为像素的灰度值运算过程","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"像素是图像的最小栅格元素，但图像处理不只运算灰度，还可处理 RGB/多通道、颜色、边缘和频域信息。题干后半句过度缩窄。"},{"id":"design-349","module":"design","title":"内容设计","number":349,"type":"single","prompt":"Maya软件多边形圆柱体常用参数包括哪些？","options":[{"key":"A","text":"半径、高度、轴向细分数、高度细分数、端面细分数"},{"key":"B","text":"半径、高度、高度细分数、端面细分数"},{"key":"C","text":"半径、高度、轴向细分数、高度细分数"},{"key":"D","text":"高度、轴向细分数、高度细分数、端面细分数"}],"answer":["A"],"explanation":"多边形圆柱体的常用参数包含半径、高度、轴向细分、高度细分和端面细分。A 列出完整参数组。"},{"id":"design-350","module":"design","title":"内容设计","number":350,"type":"single","prompt":"Maya软件多边形管道的参数厚度可以设置多边形管道的()","options":[{"key":"A","text":"半径大小"},{"key":"B","text":"厚度值"},{"key":"C","text":"高度值"},{"key":"D","text":"深度值"}],"answer":["B"],"explanation":"Pipe 的 Thickness 决定管壁厚度，即内外半径差。半径、深度和高度由其他参数控制。"},{"id":"design-351","module":"design","title":"内容设计","number":351,"type":"judge","prompt":"将遮蔽裁剪纳入考虑优化关卡(添加一些阻挡视线的物件来提高性能","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"遮挡裁剪利用不透明物体遮挡视线，减少被遮住区域的绘制工作。加入合适遮挡物可改善性能，但不应造成不必要的遮挡/关卡复杂度。"},{"id":"design-352","module":"design","title":"内容设计","number":352,"type":"single","prompt":"下面关于UE4的静态网格体理解错误的是？","options":[{"key":"A","text":"UE4静态网格体缓存在视频存储器中，因此可以对它们进行平移、旋转和缩放，也能为其顶点设置动画"},{"key":"B","text":"UE4静态网格体是用于在虚幻引擎中创建关卡世界场景几何体的基础单元"},{"key":"C","text":"UE4静态网格体(Static Mesh)是由一系列多边形构成的几何体的组成部分，缓存在视频存储器中，可以使用显卡进行渲染"},{"key":"D","text":"UE4利用FBX导入静态网格体所支持的功能有带纹理材质的静态网格体、自定义碰撞、多个UV集、平滑组、顶点颜色、LODs、多个单独的静态网格体"}],"answer":["A"],"explanation":"静态网格体可平移、旋转、缩放，但其顶点数据固定，不能直接设置顶点级变形动画。需要顶点动画时应使用骨骼网格、形变或其他系统，故 A 错。"},{"id":"design-353","module":"design","title":"内容设计","number":353,"type":"single","prompt":"下面关于曲面修改工具用法描述错误的是？","options":[{"key":"A","text":"曲面修改工具中的重建曲面是可以在曲面上重新构造等参线以生成布线均匀的曲面模型"},{"key":"B","text":"曲面修改工具中的延伸曲面是可以根据选择的曲面来延伸并删除曲面模型"},{"key":"C","text":"曲面修改工具中的开放/闭合曲面是可以将曲面在U向/V向进行打开或者封闭操作"},{"key":"D","text":"曲面修改工具中的插入等参线是可以在曲面的任意位置插入新的等参线"}],"answer":["B"],"explanation":"延伸曲面用于沿边界扩展曲面，不会“延伸并删除曲面模型”。A、C、D描述的重建、开闭和插入等参线功能成立，B 错。"},{"id":"design-354","module":"design","title":"内容设计","number":354,"type":"judge","prompt":"Lambert材质常用来模拟不光滑没有高光的物体，如木头、墙壁等，它没有高光、反射等属性","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Lambert 是漫反射材质，适合哑光表面，传统模型中不提供明显镜面高光或反射。题干正确。"},{"id":"design-355","module":"design","title":"内容设计","number":355,"type":"judge","prompt":"PS软件Lab模式中的L通道是指透明度","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"Lab 中 L 表示明度，不表示透明度；透明通常由 Alpha 通道表示。题干错误。"},{"id":"design-356","module":"design","title":"内容设计","number":356,"type":"judge","prompt":"Maya软件多边形立方体的参数深度细分数可以设置多边形立方体的深度上的分段数量","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"立方体的深度细分数控制深度方向上的分段数量。题干正确。"},{"id":"design-357","module":"design","title":"内容设计","number":357,"type":"single","prompt":"下面关于材质\\"公用材质属性\\"卷展栏下通用属性的含义有误的是？","options":[{"key":"A","text":"材质的通用属性颜色是指材质的颜色，默认情况下是HSV模式，也可以切换为RGB模式"},{"key":"B","text":"材质的通用属性透明度是指该参数用来控制物体的透明度，默认情况下是完全透明"},{"key":"C","text":"材质的通用属性环境色是指该参数用于控制对象受周围环境的影响，默认情况下为黑色"},{"key":"D","text":"材质的通用属性白炽度是指用于模拟物体的自发光效果，但是并不会照亮其他的物体"}],"answer":["B"],"explanation":"通用透明度默认通常是不透明（Opacity 为 1），不是完全透明。A、C、D符合该材质通用属性定义，B 错。"},{"id":"design-358","module":"design","title":"内容设计","number":358,"type":"single","prompt":"下面关于PS软件的工具使用说法错误的是？","options":[{"key":"A","text":"PS软件鼠标左键长按工具或鼠标右键单击工具,可弹出隐藏工具选项"},{"key":"B","text":"PS软件的工具箱不可以根据需要在单栏与双栏之间自由切换"},{"key":"C","text":"PS软件单击工具栏上方的双箭头图标,即可实现单栏/双栏的切换,以节省工作空间"},{"key":"D","text":"PS软件用鼠标右键单击工具图标,在弹出的菜单中选择\\"复位工具\\"命令，可以恢复工具默认的设置"}],"answer":["B"],"explanation":"Photoshop 工具箱可通过双箭头在单栏/双栏之间切换。B 否认这一功能，故错误。"},{"id":"design-359","module":"design","title":"内容设计","number":359,"type":"judge","prompt":"Maya软件NURBS圆形常用参数有扫描、半径、次数、分段数","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"NURBS 圆形常用创建参数包括扫描、半径、次数/阶数和分段数。题干正确。"},{"id":"design-360","module":"design","title":"内容设计","number":360,"type":"judge","prompt":"曲面建模可以通过创建曲面基本体的方式来绘制简单的三维对象","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"曲面基本体（球、圆柱、平面等）可作为曲面建模的起点，直接绘制简单三维形体。题干正确。"},{"id":"design-361","module":"design","title":"内容设计","number":361,"type":"judge","prompt":"Maya软件在\\"多边形建模\\"工具架上右击\\"柏拉图多面体\\"图标可以创建多边形管道","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"Maya 中多边形管道应从多边形基本体创建菜单选择，不能通过右击“柏拉图多面体”图标创建管道。题干错误。"},{"id":"design-362","module":"design","title":"内容设计","number":362,"type":"single","prompt":"Maya软件NURBS球体参数中的分段数是可以设置球体模型的()","options":[{"key":"A","text":"次数"},{"key":"B","text":"竖向分段"},{"key":"C","text":"半径大小"},{"key":"D","text":"横向分段"}],"answer":["D"],"explanation":"NURBS 球体分段数控制横向环向分段密度；次数控制阶数，半径控制尺寸，竖向通常由跨度数控制。故选 D。"},{"id":"design-363","module":"design","title":"内容设计","number":363,"type":"judge","prompt":"因为图形硬件仅处理三角形，所以必须对虚幻引擎中的网格体进行三角剖分","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"GPU 图形管线最终以三角形图元进行光栅化，网格在渲染时必须被三角化；引擎或导入器可自动执行。题干正确。"},{"id":"design-364","module":"design","title":"内容设计","number":364,"type":"judge","prompt":"Maya软件多边形管道的参数端面细分数可以设置多边形管道的端面分段数值","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"圆柱管道的端面细分数控制端面环向分段/边数。题干正确。"},{"id":"design-365","module":"design","title":"内容设计","number":365,"type":"single","prompt":"下面关于Hypershade面板描述错误的是？","options":[{"key":"A","text":"Hypershade面板\\"浏览器\\"选项卡由\\"工具栏\\"和\\"样本分类区\\"两部分组成"},{"key":"B","text":"Hypershade面板\\"创建\\"选项卡是用来创建材质、纹理、灯光、工具等节点"},{"key":"C","text":"Hypershade面板\\"材质查看器\\"选项卡提供5种显示方式"},{"key":"D","text":"Hypershade面板\\"工作区\\"选项卡主要用来显示及编辑该软件的材质节点"}],"answer":["C"],"explanation":"Hypershade 的材质查看器显示模式数量随版本而异，题干称固定 5 种并不准确；浏览器、创建和工作区功能描述较符合基本界面。选 C。"},{"id":"design-366","module":"design","title":"内容设计","number":366,"type":"judge","prompt":"Maya软件多边形圆柱体的参数半径可以设置多边形圆柱的半径大小。","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"多边形圆柱体 Radius 参数设置圆柱外半径。题干正确。"},{"id":"design-367","module":"design","title":"内容设计","number":367,"type":"judge","prompt":"点云是三维数据的载体","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"点云用大量离散三维点承载空间数据，可描述物体表面和环境形状。题干正确。"},{"id":"design-368","module":"design","title":"内容设计","number":368,"type":"judge","prompt":"从3D建模软件中导出网格体时，枢轴点坐标必须固定位于原点处(0,0,0)","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"网格导出枢轴可以按对象用途放在任意合理位置，不要求固定为 (0,0,0)。题干错误。"},{"id":"design-369","module":"design","title":"内容设计","number":369,"type":"single","prompt":"下面关于PS软件选择\\"钢笔\\"工具属性栏描述错误的是？","options":[{"key":"A","text":"按住Ctrl键时,暂时将\\"钢笔\\"工具.转换成\\"直接选择\\"工具"},{"key":"B","text":"按住Shift键创建锚点时,将强迫系统以45°或45°的倍数绘制路径"},{"key":"C","text":"反复按Ctrl+P组合键可以使用钢笔工具"},{"key":"D","text":"按住Alt键,当\\"钢笔\\"工具移到锚点上时,暂时将\\"钢笔\\"工具转换为\\"转换点\\"工具"}],"answer":["B"],"explanation":"Shift 不能把钢笔路径强制约束到 45°，常见角度约束是绘制/拖动时按 Shift；但选项 B 说创建锚点时限制方向，应视题干教程操作核验。A、D是常见临时工具切换，Ctrl+P 不是钢笔快捷键，最明确错误项为 C。"},{"id":"design-370","module":"design","title":"内容设计","number":370,"type":"judge","prompt":"各项异性材质\\"特殊效果\\"卷展栏中的辉光强度是控制物体材质的发光程度","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"辉光强度控制材质发光/辉光效果的强弱。它主要改变渲染外观，不一定产生真实照明。题干正确。"},{"id":"design-371","module":"design","title":"内容设计","number":371,"type":"judge","prompt":"PS软件屏幕分辨率是显示器上每单位长度显示的像素数目","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"屏幕分辨率/像素密度常以单位长度中的像素数描述（如 PPI）。题干正确。"},{"id":"design-372","module":"design","title":"内容设计","number":372,"type":"single","prompt":"使用背景材质常用参数中的反射限制是控制材质()","options":[{"key":"A","text":"反射的距离"},{"key":"B","text":"阴影遮罩的密度"},{"key":"C","text":"反射颜色"},{"key":"D","text":"反射程度"}],"answer":["A"],"explanation":"背景材质的 Reflection Limit 限制反射可见的距离/范围。阴影遮罩密度、颜色和整体反射程度由其他参数控制，选 A。"},{"id":"design-373","module":"design","title":"内容设计","number":373,"type":"single","prompt":"下面关于NURBS圆柱体参数用法正确的是？","options":[{"key":"A","text":"NURBS圆柱体参数中的跨度数是可以设置NURBS圆柱体的竖向分段"},{"key":"B","text":"NURBS圆柱体参数中的高度比是可以调整NURBS圆柱体的高度和半径"},{"key":"C","text":"NURBS圆柱体参数中的半径是可以设置NURBS圆柱体的半径大小和高度"},{"key":"D","text":"NURBS圆柱体参数中的分段数是可以设置NURBS圆柱体的横向分段"}],"answer":["A"],"explanation":"NURBS 圆柱体的跨度数控制轴向曲面跨度/竖向分段，其他选项混淆了半径、高度比和分段参数。A 正确。"},{"id":"design-374","module":"design","title":"内容设计","number":374,"type":"judge","prompt":"UE4在透视口中，使用鼠标右键+拖动，可以前后移动相机，及左右旋转相机","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"透视视口右键拖动用于观察旋转；前后移动需要配合其他鼠标按钮/导航操作。题干把右键旋转说成前后移动并旋转，错误。"},{"id":"design-375","module":"design","title":"内容设计","number":375,"type":"single","prompt":"下列关于\\"标准曲面材质\\"命令参数\\"次表面\\"参数理解错误的是？","options":[{"key":"A","text":"权重是用来控制漫反射和次表面散射之间的混合权重"},{"key":"B","text":"比例是控制灯光在再度反射出曲面前在曲面下可能传播的距离"},{"key":"C","text":"半径是用来设置光线在次表面散射半径大小"},{"key":"D","text":"颜色是用来确定次表面散射效果的颜色"}],"answer":["B"],"explanation":"次表面散射中的 Scale 通常控制散射距离的整体比例，描述“灯光再度反射前传播距离”不准确；权重、半径、颜色则对应混合量、散射半径和色调。错误项 B。"},{"id":"design-376","module":"design","title":"内容设计","number":376,"type":"judge","prompt":"Maya软件单击\\"曲线/曲面\\"工具架上的\\"旋转\\"图标,可以将旋转曲面模型","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"曲线/曲面工具架上的 Revolve（旋转）可将轮廓曲线绕轴旋转生成旋转曲面。题干正确。"},{"id":"design-377","module":"design","title":"内容设计","number":377,"type":"single","prompt":"下列关于\\"标准曲面材质\\"命令参数\\"几何体\\"参数理解错误的是？","options":[{"key":"A","text":"各向异性切线是为镜面反射各向异性着色指定一个自定义切线"},{"key":"B","text":"薄壁是勾选该选项,可以定义薄膜的实际厚度"},{"key":"C","text":"不透明度是控制不允许灯光穿过的程度"},{"key":"D","text":"凹凸贴图是通过添加贴图来设置材质的凹凸属性"}],"answer":["B"],"explanation":"薄壁选项用于告诉着色器对象是薄片/薄壁几何，而不是定义薄膜的实际厚度。各向异性切线、不透明度和凹凸贴图的说明基本成立。"},{"id":"design-378","module":"design","title":"内容设计","number":378,"type":"single","prompt":"下列关于Faro scene软件功能说法正确的是？","options":[{"key":"A","text":"Faro scene不可以使用虚拟现实设备，不能在室内体验和探索身现场细节"},{"key":"B","text":"Faro scene支持的网格格式可以.stl、.obj、.ply和.wrl(VRML)"},{"key":"C","text":"Faro scene移动对象过滤不可以自动删除在扫描场景中多余的移动对象"},{"key":"D","text":"Faro scene网格控制由平移和旋转手柄构成,但是不允许手动放置网格"}],"answer":["B"],"explanation":"FARO SCENE 支持常见网格输出/交换格式，包括 STL、OBJ、PLY 和 VRML。A、C、D均错误地否认软件能力，因此选 B。"},{"id":"design-379","module":"design","title":"内容设计","number":379,"type":"judge","prompt":"曲面建模可以通过创建曲线的方式来构建曲面的基本轮廓","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"曲线可作为曲面建模的边界、轨道或截面，用于构建曲面基本轮廓。题干正确。"},{"id":"design-380","module":"design","title":"内容设计","number":380,"type":"single","prompt":"下列关于扫描仪测站设置的一般遵守的原则说法错误的是？","options":[{"key":"A","text":"在可视范围内,保证70%以上数据的完整性,站站之间重复率40%\\\\~50%左右"},{"key":"B","text":"要与扫描对象平面垂直"},{"key":"C","text":"要使得扫描仪所架设的各个测站可以扫描到目标区域的全部范围"},{"key":"D","text":"相邻两站之间有不少于三个可清晰识别标靶或特别标志"}],"answer":["B"],"explanation":"测站应覆盖目标区域并保留足够重叠及公共标靶；扫描方向应结合表面和遮挡调整，不要求一律垂直。题目 A 的覆盖率/重叠值也与其他题不一致，最明显错误项为 B，建议核验课程标准。"},{"id":"design-381","module":"design","title":"内容设计","number":381,"type":"judge","prompt":"不透明的材质性能最快，因为有最佳的ZBuffer裁剪，蒙版会稍慢一些，半透明则最慢，因为有多次渲染的开销","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"不透明材质可进行深度测试/写入，性能通常较好；Masked 需要透明度裁剪，Translucent 常需混合且处理更贵。题干排序正确。"},{"id":"design-382","module":"design","title":"内容设计","number":382,"type":"single","prompt":"测站设置原则是相邻两站之间有不少于()可清晰识别标靶或特别标志","options":[{"key":"A","text":"二个"},{"key":"B","text":"一个"},{"key":"C","text":"三个"},{"key":"D","text":"四个"}],"answer":["A"],"explanation":"相邻站至少两个共同标靶可提供配准约束；若现场要求更稳健，通常会布设更多。按选项中的最低数量选择二个 A。"},{"id":"design-383","module":"design","title":"内容设计","number":383,"type":"judge","prompt":"移动测绘系统MMS包括移动激光扫描系统和惯性导航系统组成","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"MMS 通常由移动激光扫描系统、GNSS/惯性导航和里程计等组成，不是只由扫描仪与惯导构成的固定两项组合。题干不完整，按本题选项判错误。"},{"id":"design-384","module":"design","title":"内容设计","number":384,"type":"single","prompt":"下面哪个不属于UE4新建项目及设置的步骤？","options":[{"key":"A","text":"选择默认内容资源With Starter Conter选项"},{"key":"B","text":"单击蓝图Blueprint分页并选择空项目Blank"},{"key":"C","text":"单击新建项目New Project的分页"},{"key":"D","text":"单击Add/Import按钮，并选择弹出内容的Import to按钮"}],"answer":["D"],"explanation":"新建项目要选项目类型、蓝图模板和 Starter Content 等设置；Add/Import 是内容浏览器导入资产流程，不是新建项目步骤。选 D。"},{"id":"design-385","module":"design","title":"内容设计","number":385,"type":"single","prompt":"下面关于CMYK模式描述正确的是?","options":[{"key":"A","text":"C代表青色,M代表洋红色,Y代表黄色,K代表黑色"},{"key":"B","text":"C代表青色,M代表黑色,Y代表黄色,K代表洋红色"},{"key":"C","text":"C代表洋红色,M代表青色,Y代表黄色,K代表黑色"},{"key":"D","text":"C代表青色,M代表洋红色,Y代表黑色,K代表黄色"}],"answer":["A"],"explanation":"CMYK 代表 Cyan 青、Magenta 洋红、Yellow 黄、Key 黑。A 正确。"},{"id":"design-386","module":"design","title":"内容设计","number":386,"type":"judge","prompt":"Maya软件多边形圆柱体的参数端面细分数可以设置多边形圆柱体的端面分段数值","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"圆柱体端面细分参数控制两端圆面的环向分段。题干正确。"},{"id":"design-387","module":"design","title":"内容设计","number":387,"type":"judge","prompt":"根据较小的物体来调整渲染距离，来达到更好的裁剪效果","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"按较小物体的可见范围设定 Cull Distance，可较早剔除远处小物件，减少渲染负担。需避免剔除近景可见对象，题干原则成立。"},{"id":"design-388","module":"design","title":"内容设计","number":388,"type":"judge","prompt":"Maya软件按下快捷键Ctrl+A是复制模型","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"Ctrl+A 通常是全选，不是复制模型；复制常用 Ctrl+D 或编辑菜单的复制。题干错误。"},{"id":"design-389","module":"design","title":"内容设计","number":389,"type":"judge","prompt":"PS软件按W键，可以使用移动工具","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["A"],"explanation":"Photoshop 的 W 是魔棒/快速选择工具组，移动工具快捷键是 V。题干错误。"},{"id":"design-390","module":"design","title":"内容设计","number":390,"type":"judge","prompt":"PS软件单击控制面板上方的双箭头图标,可以将控制面板收缩","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"面板组上方的双箭头可折叠/展开面板栏，释放工作区空间。题干正确。"},{"id":"design-391","module":"design","title":"内容设计","number":391,"type":"judge","prompt":"材质的通用属性\\"镜面反射着色\\"偏心率是指该参数用来控制高光扩散的大小，数值越大，高光点就越小。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Eccentricity 控制高光扩散大小，数值越大通常使高光更集中、面积更小。题干正确。"},{"id":"design-392","module":"design","title":"内容设计","number":392,"type":"single","prompt":"Maya软件NURBS立方体参数分别有哪些？","options":[{"key":"A","text":"U向面片数、V向面片数、长度、宽度比/高度比"},{"key":"B","text":"X向面片数、Y向面片数、宽度、长度比/高度比"},{"key":"C","text":"U向面片数、V向面片数、高度、长度比/宽度比"},{"key":"D","text":"U向面片数、V向面片数、宽度、长度比/高度比"}],"answer":["D"],"explanation":"NURBS 立方体常用参数为 U/V 面片数、宽度及长度比/高度比等。D 列出了相应尺寸与比例参数组合。"},{"id":"design-393","module":"design","title":"内容设计","number":393,"type":"single","prompt":"PS软件按( )可以使用魔棒工具","options":[{"key":"A","text":"W键"},{"key":"B","text":"X键"},{"key":"C","text":"V键"},{"key":"D","text":"L键"}],"answer":["A"],"explanation":"魔棒工具位于 W 工具组，按 W 可在同组工具间切换到魔棒。选 A。"},{"id":"design-394","module":"design","title":"内容设计","number":394,"type":"single","prompt":"Photoshop软件工作界面用途描述错误的是？","options":[{"key":"A","text":"利用菜单命令可以完成图像的编辑、色彩调整、添加滤镜效果等操作"},{"key":"B","text":"控制面板,可以提供当前文件的显示比例、文档大小、当前工具、暂存盘大小等提示信息"},{"key":"C","text":"通过在属性栏中设置不同的选项,可以快速完成多样化的操作"},{"key":"D","text":"利用不同的工具可以完成图像的绘制、观察、测量等操作"}],"answer":["B"],"explanation":"状态栏提供缩放比例、文档大小等信息；控制面板负责调整和管理工作参数，不是题述信息显示区域。B 把状态栏功能说成控制面板功能。"},{"id":"design-395","module":"design","title":"内容设计","number":395,"type":"single","prompt":"下面关于PS软件选择\\"魔棒\\"工具属性栏描述错误的是？","options":[{"key":"A","text":"容差是用于控制色彩的范围,数值越大,可容许的颜色范围越小"},{"key":"B","text":"对所有图层取样是用于将所有可见层中颜色容许范围内的色彩加入选区"},{"key":"C","text":"消除锯齿是用于清除选区边缘的锯齿"},{"key":"D","text":"取样大小是用于设置取样范围的大小"}],"answer":["A"],"explanation":"容差值越大，魔棒接受的颜色差异范围越宽，选中的颜色范围越大。A 说范围越小，方向相反。"},{"id":"design-396","module":"design","title":"内容设计","number":396,"type":"single","prompt":"下面是有关\\"布料\\"纹理参数的描述，其中错误的是？","options":[{"key":"A","text":"U向波/V向波是设置U向和V向线的波纹"},{"key":"B","text":"宽度扩散是用来设置沿着每条线的长度随机化线的亮度"},{"key":"C","text":"调整\\"随机度\\"值，可以用不规则丝线创建看起来很自然的布料,也可以避免在非常精细的布料纹理上出现锯齿和云纹图案"},{"key":"D","text":"间隙颜色是用于设置经线(U方向)和纬线(V方向)之间区域的颜色"}],"answer":["B"],"explanation":"宽度扩散随机化沿线的宽度变化，不是随机化线的亮度；亮度类参数才改变亮暗分布。B 错。"},{"id":"design-397","module":"design","title":"内容设计","number":397,"type":"single","prompt":"Maya软件多边形立方体的参数宽度可以设置多边形立方体的()","options":[{"key":"A","text":"分段数量"},{"key":"B","text":"宽度"},{"key":"C","text":"高度"},{"key":"D","text":"深度"}],"answer":["B"],"explanation":"Width 参数设置立方体宽度尺寸，而不是分段数量、高度或深度。选 B。"},{"id":"design-398","module":"design","title":"内容设计","number":398,"type":"single","prompt":"下面关于UE4导入LOD的方法描述错误的是？","options":[{"key":"A","text":"UE4导入LOD时，导入网格体的命名不用遵循默认的命名规则"},{"key":"B","text":"UE4静态网格体导入后，可以手动为它创建LOD，这样可以得到最好的结果"},{"key":"C","text":"UE4在静态网格体编辑器中查看导入的网格体时，可使用细节面板中的LOD拾取器(LOD Picker)来循环切换LOD"},{"key":"D","text":"UE4在内容浏览器中，静态网格体LOD可随基础网格体一同导入，或通过静态网格体编辑器单独导入"}],"answer":["A"],"explanation":"UE 导入多级 LOD 通常要求遵循资产命名约定，便于引擎识别各级网格；不能说“不用遵循”。A 错。"},{"id":"design-399","module":"design","title":"内容设计","number":399,"type":"single","prompt":"下列关于\\"标准曲面材质\\"命令参数\\"镜面反射\\"参数理解错误的是？","options":[{"key":"A","text":"各向异性是控制高光的各向异性属性，以得到具有椭圆形状的反射及高光效果"},{"key":"B","text":"粗糙度是控制镜面反射的光泽度，值越大,反射越清晰"},{"key":"C","text":"IOR是用于控制材质的折射率，这在制作玻璃、水、钻石等透明材质时非常重要"},{"key":"D","text":"旋转是用于控制材质UV空间中各向异性反射的方向"}],"answer":["B"],"explanation":"粗糙度越大通常让镜面反射越模糊、越不清晰，而不是越清晰。各向异性、IOR 和旋转的说明分别对应拉伸高光、折射率和方向控制。"},{"id":"design-400","module":"design","title":"内容设计","number":400,"type":"judge","prompt":"纹理的通用属性中的Alpha为亮度是表示Alpha的输出由纹理的亮度来决定","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Alpha Is Luminance 会把纹理亮度转换为 Alpha 输出，亮度越高对应越不透明/Alpha 越高。题干正确。"},{"id":"design-401","module":"design","title":"内容设计","number":401,"type":"judge","prompt":"曲面建模可以通过创建曲线的方式来构建曲面的基本轮廓，也可以通过创建曲面基本体的方式来绘制简单的三维对象","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"曲线可用于构建曲面轮廓，曲面基本体也可直接生成简单对象。题干正确。"},{"id":"design-402","module":"design","title":"内容设计","number":402,"type":"judge","prompt":"Maya软件曲线修改工具中的分离曲线是根据曲线的参数点来断开曲线。","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"Detach/Separate Curve 可按参数位置把一条曲线断成多个曲线段。题干正确。"},{"id":"design-403","module":"design","title":"内容设计","number":403,"type":"judge","prompt":"UE4选中某个摄像机Actor后，主3D视口将显示一个\\"画中画\\"视图","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"选中摄像机 Actor 后，编辑器视口可显示摄像机预览/画中画，便于查看最终镜头画面。题干正确。"},{"id":"design-404","module":"design","title":"内容设计","number":404,"type":"single","prompt":"下面关于UE4的WASD飞行控制操作有误的是？","options":[{"key":"A","text":"在透视口中，按W键，可以向前移动相机"},{"key":"B","text":"在透视口中，按Z键，可以推进相机(降低视场)"},{"key":"C","text":"在透视口中，按左箭头键键，可以向左移动相机"},{"key":"D","text":"在透视口中，按数字键2键，可以向后移动相机"}],"answer":["D"],"explanation":"UE4 透视口 WASD 飞行中 W/S 前后、A/D 左右；Z 常用于推进/拉远视口相机，箭头键也可导航。数字键 2 不是标准向后飞行键，故 D 错。"},{"id":"design-405","module":"design","title":"内容设计","number":405,"type":"single","prompt":"下面哪组工具是主流虚拟现实引擎工具？","options":[{"key":"A","text":"Unity3D、Unreal Engine 4、CryEngine、Unfold3D"},{"key":"B","text":"Unity3D、Substance Painter、CryEngine、IdeaVR"},{"key":"C","text":"Unity3D、Unreal Engine 4、CryEngine、IdeaVR"},{"key":"D","text":"Unity3D、Unreal Engine 4、ZBrush、IdeaVR"}],"answer":["C"],"explanation":"Unity、Unreal Engine、CryEngine 和 IdeaVR 都是游戏/VR 引擎类工具。Unfold3D、Substance Painter、ZBrush 属于 UV、材质或雕刻工具，不是同一类引擎。"},{"id":"design-406","module":"design","title":"内容设计","number":406,"type":"judge","prompt":"各项异性材质\\"光线跟踪选项\\"卷展栏中的表面厚度是控制材质所要模拟的厚度","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"材质光线跟踪选项中的 Surface Thickness 用于描述参与材质透射/次表面效果的表面厚度。题干正确。"},{"id":"design-407","module":"design","title":"内容设计","number":407,"type":"single","prompt":"下面关于UE4虚拟摄像机Actor的细节面板描述错误的是？","options":[{"key":"A","text":"Activation是决定是否自动启用摄像机"},{"key":"B","text":"Actor是摄像机Actor 本身的相关信息"},{"key":"C","text":"Misc是用于产生动态模糊效果"},{"key":"D","text":"Blueprint是用于将Actor 变为蓝图，或者将事件添加到 Actor 的关卡蓝图(Level Blueprint)"}],"answer":["C"],"explanation":"动态模糊由 Motion Blur 控制，不由 Misc 直接定义；Misc 常放置抗锯齿、融合等杂项后处理。故 C 错。"},{"id":"design-408","module":"design","title":"内容设计","number":408,"type":"single","prompt":"下面关于PS软件常用的文件格式描述正确的是？","options":[{"key":"A","text":"用于网络图像可以使用GIF、JPEG、PNG格式"},{"key":"B","text":"以上都正确"},{"key":"C","text":"用于Photoshop软件可以使用PSD、PDD、TIF格式"},{"key":"D","text":"用于印刷可以使用TIF、EPS格式"}],"answer":["B"],"explanation":"GIF、JPEG、PNG 可用于网络图像，PSD/PDD/TIFF 可保存 Photoshop 数据，TIFF/EPS 常用于印刷。三组说法都成立，因此选“以上都正确”。"},{"id":"design-409","module":"design","title":"内容设计","number":409,"type":"judge","prompt":"Geomagic Wrap是一款3D扫描分析软件","options":[{"key":"A","text":"错误"},{"key":"B","text":"正确"}],"answer":["B"],"explanation":"Geomagic Wrap 面向 3D 扫描数据处理、分析和曲面/网格生成。题干正确。"}]');export{e as t};